{
  "name": "Nexus Agent Manager",
  "description": "A comprehensive system for managing AI and Mail Agents, configuring workflows, automation rules, and monitoring audit logs."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AgentType {
  MAIL = 'MAIL',
  AI = 'AI'
}

export enum AgentStatus {
  DRAFT = 'DRAFT',
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

export interface MailConfig {
  senderEmail?: string;
  receiverEmail?: string;
  enableFilter: boolean;
  subjectKeywords: string[];
  bodyKeywords: string[];
}

export interface AIConfig {
  inputSource?: string;
  outputAction?: string;
  model: string;
}

export interface DriveConfig {
  autoSave: boolean;
  targetFolderPath?: string;
  autoRename: boolean;
  renamePattern?: string; // e.g. {DocNo}_{Date}
  autoCreateFolder: boolean;
  folderStructure?: string; // e.g. /{Year}/{Customer}/
}

export interface Agent {
  id: string;
  name: string;
  description: string;
  type: AgentType;
  status: AgentStatus;
  updatedAt: string;
  updatedBy: string;
  companyId: string;
  workflowId?: string; // The workflow this agent is bound to
  triggerEvent?: string; // e.g., "On Document Create"

  // Specific Configs
  mailConfig?: MailConfig;
  aiConfig?: AIConfig;
  driveConfig?: DriveConfig;
}

// Mock Data Types
export const AVAILABLE_WORKFLOWS = [
  { id: 'wf-001', name: 'Invoice Processing' },
  { id: 'wf-002', name: 'Customer Support Ticket' },
  { id: 'wf-003', name: 'HR Onboarding' }
];

export const AVAILABLE_TRIGGERS = [
  'On Email Received',
  'On Document Created',
  'Schedule: Daily 9:00 AM',
  'Manual Trigger Only'
];

export const ALLOWED_VARIABLES = ['{DocNo}', '{Date}', '{Customer}', '{AgentName}', '{Year}', '{Month}', '{DocType}'];

import React from 'react';
import { LayoutDashboard, Users, Settings, ShieldCheck, LogOut, Bot, Mail, Menu } from 'lucide-react';
import { UserRole } from '../types';

