          <div className="flex items-center gap-4">
             <div className="flex flex-col items-end">
                <span className="text-sm font-medium text-slate-800">Jane Doe</span>
                <span className="text-xs text-slate-500">{currentUserRole} @ Acme Corp</span>
             </div>
             <div className="w-9 h-9 bg-brand-100 text-brand-600 rounded-full flex items-center justify-center font-bold">
                JD
             </div>
