const SectionHeader = ({ icon, title }: { icon: any, title: string }) => (
  <div className="flex items-center gap-2 text-slate-800 font-semibold mb-3 border-b border-slate-100 pb-2">
    <span className="text-brand-500">{icon}</span>
    <h3>{title}</h3>
  </div>
);

const Toggle = ({ enabled, onChange, disabled }: { enabled: boolean, onChange: (v: boolean) => void, disabled: boolean }) => (
  <button
    onClick={() => !disabled && onChange(!enabled)}
    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
      enabled ? 'bg-brand-600' : 'bg-slate-300'
    } ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
  >
    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${enabled ? 'translate-x-6' : 'translate-x-1'}`} />
  </button>
);

const KeywordInput = ({ label, keywords, inputValue, setInputValue, onAdd, onRemove, disabled }: any) => (
  <div className="space-y-2">
    <label className="text-sm font-medium text-slate-700">{label}</label>
    <div className="flex gap-2">
      <input 
        type="text" 
        value={inputValue}
        disabled={disabled}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={(e) => e.key === 'Enter' && onAdd()}
        className="flex-1 input-std"
        placeholder="Type keyword and press Enter"
      />
      <button 
        onClick={onAdd}
        disabled={disabled} 
        className="px-3 bg-slate-200 text-slate-700 rounded-lg hover:bg-slate-300 disabled:opacity-50"
      >
        <PlusIcon />
      </button>
    </div>
    <div className="flex flex-wrap gap-2 mt-2">
      {keywords.map((k: string) => (
        <span key={k} className="inline-flex items-center gap-1 bg-white border border-slate-300 px-2 py-1 rounded-md text-sm text-slate-700 shadow-sm">
          {k}
          {!disabled && (
            <button onClick={() => onRemove(k)} className="text-slate-400 hover:text-red-500">
               <XIcon />
            </button>
          )}
        </span>
      ))}
    </div>
  </div>
);

