  ArrowLeft, Save, Play, CheckCircle2, AlertCircle, FileCode, FolderOpen, 
  Mail, Bot, Settings2, History, RotateCcw, X, Beaker, Filter 
} from 'lucide-react';
import { 
  Agent, AgentStatus, AgentType, UserRole, 
  AVAILABLE_WORKFLOWS, AVAILABLE_TRIGGERS, ALLOWED_VARIABLES, AuditLog 
} from '../types';

interface AgentFormProps {
  initialData?: Agent;
  role: UserRole;
  onSave: (agent: Agent) => void;
  onBack: () => void;
  auditLogs: AuditLog[];
}

const TABS = [
  { id: 'general', label: 'General Info', icon: <Settings2 size={16} /> },
  { id: 'config', label: 'Configuration', icon: <FileCode size={16} /> },
  { id: 'automation', label: 'Drive Automation', icon: <FolderOpen size={16} /> },
  { id: 'test', label: 'Test Run', icon: <Beaker size={16} /> },
  { id: 'history', label: 'Audit Log', icon: <History size={16} /> },
];

export const AgentForm: React.FC<AgentFormProps> = ({ initialData, role, onSave, onBack, auditLogs }) => {
  const [activeTab, setActiveTab] = useState('general');
  const [isTestModalOpen, setTestModalOpen] = useState(false);
  const [testResult, setTestResult] = useState<any>(null);
  const [testLoading, setTestLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, // Default
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
      targetFolderPath: '/Shared Drives/Company/',
      renamePattern: '{DocNo}_{Date}',
      folderStructure: '/{Year}/{Month}/'
    }
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Keyword input state
  const [subjectKeyInput, setSubjectKeyInput] = useState('');
  const [bodyKeyInput, setBodyKeyInput] = useState('');

  const isAdmin = role === UserRole.ADMIN;
  const isReadOnly = !isAdmin;

  // Handlers
  const handleInputChange = (field: string, value: any) => {
    if (isReadOnly) return;
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error if exists
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleNestedChange = (section: 'mailConfig' | 'aiConfig' | 'driveConfig', field: string, value: any) => {
    if (isReadOnly) return;
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const addKeyword = (type: 'subject' | 'body', value: string) => {
    if (isReadOnly || !value.trim()) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];

    if (!currentList.includes(value.trim())) {
      handleNestedChange(section, field, [...currentList, value.trim()]);
    }
    if (type === 'subject') setSubjectKeyInput('');
    else setBodyKeyInput('');
  };

  const removeKeyword = (type: 'subject' | 'body', keyword: string) => {
    if (isReadOnly) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];
    handleNestedChange(section, field, currentList.filter(k => k !== keyword));
  };

  const validateForm = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = 'Agent name is required';
    if (formData.name.length > 120) newErrors.name = 'Name must be less than 120 characters';

    // Workflow validation
    if (formData.status === AgentStatus.ACTIVE && !formData.workflowId) {
      newErrors.workflowId = 'Workflow is required to enable agent';
    }

    // Drive validation
    if (formData.driveConfig?.autoSave && !formData.driveConfig.targetFolderPath) {
      newErrors.targetPath = 'Target folder path is required';
    }

    // Pattern validation (check for illegal chars or unknown variables)
    if (formData.driveConfig?.autoRename && formData.driveConfig.renamePattern) {
        // Simple regex for invalid filename chars (windows style)
        if (/[<>:"/\\|?*]/.test(formData.driveConfig.renamePattern)) {
            newErrors.renamePattern = 'Filename pattern contains invalid characters';
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (targetStatus?: AgentStatus) => {
    if (!validateForm()) {
        alert("Please fix the errors before saving.");
        return;
    }

    const updatedAgent = {
      ...formData,
      status: targetStatus || formData.status,
      updatedAt: new Date().toISOString()
    };
    onSave(updatedAgent);
  };

  const runTest = () => {
    setTestLoading(true);
    setTestResult(null);
    // Simulate API call
    setTimeout(() => {
        setTestLoading(false);
        setTestResult({
            success: true,
            message: "Processed successfully",
            details: {
                trigger: "Manual Test",
                input: formData.type === AgentType.MAIL ? "Sample Email Subject: Invoice #1234" : "Sample Context Data",
                actions: [
                    "Filter matched: Yes",
                    "Workflow Triggered: Invoice Processing",
                    formData.driveConfig?.autoSave ? `File Saved to: ${formData.driveConfig.targetFolderPath}` : "File Save: Skipped"
                ]
            }
        });
    }, 1500);
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-slate-50">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
             <h2 className="text-xl font-bold text-slate-800">{initialData ? `Edit Agent: ${formData.name}` : 'Create New Agent'}</h2>
             <div className="flex items-center gap-2 text-sm text-slate-500 mt-0.5">
                <span className={`w-2 h-2 rounded-full ${
                    formData.status === AgentStatus.ACTIVE ? 'bg-emerald-500' : 
                    formData.status === AgentStatus.INACTIVE ? 'bg-slate-400' : 'bg-amber-400'
                }`}></span>
                {formData.status}
             </div>
          </div>
        </div>

        {isAdmin && (
          <div className="flex items-center gap-3">
             <button 
               onClick={() => handleSubmit(AgentStatus.DRAFT)}
               className="px-4 py-2 text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 font-medium transition-colors"
             >
               Save Draft
             </button>
             <button 
               onClick={() => handleSubmit(AgentStatus.ACTIVE)}
               className="px-4 py-2 flex items-center gap-2 text-white bg-emerald-600 rounded-lg hover:bg-emerald-700 font-medium transition-colors shadow-sm"
             >
               <CheckCircle2 size={18} />
               {formData.status === AgentStatus.ACTIVE ? 'Save Changes' : 'Publish & Enable'}
             </button>
             {formData.status === AgentStatus.ACTIVE && (
                 <button 
                    onClick={() => handleSubmit(AgentStatus.INACTIVE)}
                    className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg"
                    title="Disable Agent"
                 >
                    <PowerIcon />
                 </button>
             )}
          </div>
        )}
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Tabs */}
        <div className="w-64 bg-slate-50 border-r border-slate-200 p-4 space-y-1">
          {TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${
                activeTab === tab.id 
                  ? 'bg-white text-brand-600 shadow-sm border border-slate-200' 
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-8">

          {/* GENERAL INFO TAB */}
          {activeTab === 'general' && (
            <div className="max-w-3xl space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2 col-span-2">
                  <label className="block text-sm font-semibold text-slate-700">Agent Name <span className="text-red-500">*</span></label>
                  <input
                    type="text"
                    disabled={isReadOnly}
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none transition-all ${errors.name ? 'border-red-500' : 'border-slate-300'}`}
                    placeholder="e.g. Invoice Processing Agent"
                  />
                  {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Agent Type <span className="text-red-500">*</span></label>
                  <select
                    disabled={isReadOnly}
                    value={formData.type}
                    onChange={(e) => handleInputChange('type', e.target.value)}
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none bg-white"
                  >
                    <option value={AgentType.MAIL}>Mail Agent</option>
                    <option value={AgentType.AI}>AI Agent</option>
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Workflow Binding</label>
                  <select
                    disabled={isReadOnly}
                    value={formData.workflowId}
                    onChange={(e) => handleInputChange('workflowId', e.target.value)}
                    className={`w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-brand-500 outline-none bg-white ${errors.workflowId ? 'border-red-500' : 'border-slate-300'}`}
                  >
                    <option value="">-- Select Workflow --</option>
                    {AVAILABLE_WORKFLOWS.map(wf => (
                      <option key={wf.id} value={wf.id}>{wf.name}</option>
                    ))}
                  </select>
                  {errors.workflowId && <p className="text-red-500 text-xs mt-1">{errors.workflowId}</p>}
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Trigger Event</label>
                  <select
                    disabled={isReadOnly}
                    value={formData.triggerEvent}
                    onChange={(e) => handleInputChange('triggerEvent', e.target.value)}
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none bg-white"
                  >
                     <option value="">-- Select Trigger --</option>
                    {AVAILABLE_TRIGGERS.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>

                <div className="col-span-2 space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Description</label>
                  <textarea
                    disabled={isReadOnly}
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none h-24 resize-none"
                    placeholder="Describe what this agent does..."
                  />
                </div>
              </div>
            </div>
          )}

          {/* CONFIGURATION TAB */}
          {activeTab === 'config' && (
            <div className="max-w-3xl space-y-8 animate-fadeIn">
              {formData.type === AgentType.MAIL ? (
                <>
                  <SectionHeader icon={<Mail size={20} />} title="Email Scope" />
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-4 bg-slate-50 rounded-lg border border-slate-200">
                    <div className="space-y-2">
                       <label className="text-sm font-medium text-slate-700">Sender Email (From)</label>
                       <input 
                          type="email" 
                          disabled={isReadOnly}
                          value={formData.mailConfig?.senderEmail}
                          onChange={(e) => handleNestedChange('mailConfig', 'senderEmail', e.target.value)}
                          className="w-full input-std" 
                          placeholder="notifications@example.com"
                       />
                    </div>
                    <div className="space-y-2">
                       <label className="text-sm font-medium text-slate-700">Receiver Email (To filter)</label>
                       <input 
                          type="email" 
                          disabled={isReadOnly}
                          value={formData.mailConfig?.receiverEmail}
                          onChange={(e) => handleNestedChange('mailConfig', 'receiverEmail', e.target.value)}
                          className="w-full input-std" 
                          placeholder="agent-inbox@company.com"
                       />
                    </div>
                  </div>

                  <div className="flex items-center justify-between">
                     <SectionHeader icon={<Filter size={20} />} title="Keyword Filtering" />
                     <div className="flex items-center gap-2">
                        <span className="text-sm text-slate-600">Enable Filter</span>
                        <Toggle 
                          enabled={formData.mailConfig?.enableFilter || false} 
                          onChange={(v) => handleNestedChange('mailConfig', 'enableFilter', v)} 
                          disabled={isReadOnly}
                        />
                     </div>
                  </div>

                  {formData.mailConfig?.enableFilter && (
                    <div className="space-y-6 p-4 bg-slate-50 rounded-lg border border-slate-200">
                       <KeywordInput 
                          label="Subject Keywords" 
                          keywords={formData.mailConfig?.subjectKeywords || []} 
                          inputValue={subjectKeyInput}
                          setInputValue={setSubjectKeyInput}
                          onAdd={() => addKeyword('subject', subjectKeyInput)}
                          onRemove={(k) => removeKeyword('subject', k)}
                          disabled={isReadOnly}
                       />
                       <KeywordInput 
                          label="Body Keywords" 
                          keywords={formData.mailConfig?.bodyKeywords || []} 
                          inputValue={bodyKeyInput}
                          setInputValue={setBodyKeyInput}
                          onAdd={() => addKeyword('body', bodyKeyInput)}
                          onRemove={(k) => removeKeyword('body', k)}
                          disabled={isReadOnly}
                       />
                    </div>
                  )}
                </>
              ) : (
                <>
                  <SectionHeader icon={<Bot size={20} />} title="AI Agent Settings" />
                  <div className="space-y-4 p-4 bg-purple-50 rounded-lg border border-purple-100">
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">AI Model</label>
                        <select 
                           disabled={isReadOnly}
                           value={formData.aiConfig?.model}
                           onChange={(e) => handleNestedChange('aiConfig', 'model', e.target.value)}
                           className="w-full input-std"
                        >
                           <option value="gemini-pro">Gemini Pro</option>
                           <option value="gpt-4">GPT-4</option>
                           <option value="claude-3">Claude 3</option>
                        </select>
                     </div>
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Input Context Source</label>
                        <textarea 
                           disabled={isReadOnly}
                           value={formData.aiConfig?.inputSource}
                           onChange={(e) => handleNestedChange('aiConfig', 'inputSource', e.target.value)}
                           className="w-full input-std h-24" 
                           placeholder="Define system prompt or context source..."
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Output Action Definition</label>
                        <textarea 
                           disabled={isReadOnly}
                           value={formData.aiConfig?.outputAction}
                           onChange={(e) => handleNestedChange('aiConfig', 'outputAction', e.target.value)}
                           className="w-full input-std h-24" 
                           placeholder="Define what the AI should produce (JSON, Summary, etc.)..."
                        />
                     </div>
                  </div>
                </>
              )}
            </div>
          )}

          {/* AUTOMATION TAB */}
          {activeTab === 'automation' && (
             <div className="max-w-3xl space-y-8 animate-fadeIn">

                {/* Auto Save */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Save size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">Auto Save to Drive</h3>
                            <p className="text-xs text-slate-500">Automatically save attachments/outputs</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoSave || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoSave', v)} 
                        disabled={isReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoSave && (
                      <div className="ml-12 space-y-2">
                         <label className="text-sm font-medium text-slate-700">Target Folder Path <span className="text-red-500">*</span></label>
                         <div className="flex gap-2">
                            <input 
                              type="text" 
                              disabled={isReadOnly}
                              value={formData.driveConfig?.targetFolderPath}
                              onChange={(e) => handleNestedChange('driveConfig', 'targetFolderPath', e.target.value)}
                              className={`flex-1 input-std ${errors.targetPath ? 'border-red-500' : ''}`}
                              placeholder="/My Drive/Agent_Output/"
                            />
                            <button className="px-3 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200" title="Check Permissions">
                               <CheckCircle2 size={18} />
                            </button>
                         </div>
                         {errors.targetPath && <p className="text-red-500 text-xs">{errors.targetPath}</p>}
                      </div>
                   )}
                </div>

                {/* Auto Rename */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><FileCode size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">Auto Rename File</h3>
                            <p className="text-xs text-slate-500">Rename files based on patterns</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoRename || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoRename', v)} 
                        disabled={isReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoRename && (
                      <div className="ml-12 space-y-3">
                         <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700">Rename Pattern</label>
                            <input 
                               type="text" 
                               disabled={isReadOnly}
                               value={formData.driveConfig?.renamePattern}
                               onChange={(e) => handleNestedChange('driveConfig', 'renamePattern', e.target.value)}
                               className="w-full input-std"
                               placeholder="{DocNo}_{Customer}_{Date}"
                            />
                            <p className="text-xs text-slate-500">
                               Allowed variables: {ALLOWED_VARIABLES.map(v => <span key={v} className="inline-block bg-slate-100 px-1 rounded mr-1 text-slate-700 font-mono">{v}</span>)}
                            </p>
                            {errors.renamePattern && <p className="text-red-500 text-xs">{errors.renamePattern}</p>}
                         </div>
                      </div>
                   )}
                </div>

                {/* Auto Create Folder */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><FolderOpen size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">Auto Create Folder</h3>
                            <p className="text-xs text-slate-500">Organize files into dynamic subfolders</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoCreateFolder || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoCreateFolder', v)} 
                        disabled={isReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoCreateFolder && (
                      <div className="ml-12 space-y-2">
                         <label className="text-sm font-medium text-slate-700">Folder Structure Rule</label>
                         <input 
                            type="text" 
                            disabled={isReadOnly}
                            value={formData.driveConfig?.folderStructure}
                            onChange={(e) => handleNestedChange('driveConfig', 'folderStructure', e.target.value)}
                            className="w-full input-std"
                            placeholder="/{Year}/{Month}/{Customer}/"
                         />
                         <p className="text-xs text-slate-500">The system will verify write permissions and create folders if they don't exist.</p>
                      </div>
                   )}
                </div>

             </div>
          )}

          {/* HISTORY TAB */}
          {activeTab === 'history' && (
             <div className="space-y-4 animate-fadeIn">
                <h3 className="text-lg font-semibold text-slate-800 mb-4">Audit Logs</h3>
                <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
                   <table className="w-full text-sm text-left">
                      <thead className="bg-slate-50 border-b border-slate-200 text-slate-600">
                         <tr>
                            <th className="p-4">Timestamp</th>
                            <th className="p-4">User</th>
                            <th className="p-4">Action</th>
                            <th className="p-4">Details</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {auditLogs.map(log => (
                            <tr key={log.id}>
                               <td className="p-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                               <td className="p-4 font-medium text-slate-700">{log.user}</td>
                               <td className="p-4">
                                  <span className="bg-slate-100 text-slate-700 px-2 py-1 rounded text-xs border border-slate-200">{log.action}</span>
                               </td>
                               <td className="p-4 text-slate-600">{log.details}</td>
                            </tr>
                         ))}
                         {auditLogs.length === 0 && (
                             <tr><td colSpan={4} className="p-8 text-center text-slate-400">No history available for this agent.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          )}

          {/* TEST TAB */}
          {activeTab === 'test' && (
             <div className="max-w-3xl animate-fadeIn">
                 <div className="bg-slate-900 text-slate-300 rounded-xl p-6 shadow-lg">
                    <div className="flex items-center justify-between mb-6">
                        <h3 className="text-white text-lg font-semibold flex items-center gap-2"><Beaker /> Test Simulator</h3>
                        {role === UserRole.ADMIN ? (
                             <button 
                                onClick={runTest}
                                disabled={testLoading}
                                className={`px-4 py-2 rounded-lg font-bold text-white transition-all flex items-center gap-2 ${testLoading ? 'bg-slate-700 cursor-not-allowed' : 'bg-brand-600 hover:bg-brand-500'}`}
                             >
                                {testLoading ? 'Running...' : 'Run Test'}
                                {!testLoading && <Play size={16} fill="currentColor"/>}
                             </button>
                        ) : (
                            <span className="text-xs text-amber-500 border border-amber-500/30 px-2 py-1 rounded">Admin Access Required</span>
                        )}
                    </div>

                    <div className="font-mono text-sm bg-black/50 p-4 rounded-lg min-h-[300px] overflow-auto">
                        <div className="mb-2 text-brand-400">$ Initializing Agent Environment...</div>
                        <div className="mb-2 text-brand-400">$ Loading Configuration for "{formData.name}"...</div>

                        {testLoading && (
                            <div className="animate-pulse text-slate-500 mt-4">
                                &gt; Processing input stream...<br/>
                                &gt; Applying filters...<br/>
                                &gt; Validating drive permissions...
                            </div>
                        )}

                        {testResult && (
                            <div className="mt-4 space-y-2 animate-fadeIn">
                                <div className="text-emerald-400 font-bold">✓ Process Completed Successfully</div>
                                <div className="text-slate-400">----------------------------------------</div>
                                {Object.entries(testResult.details).map(([key, val]: any) => (
                                    <div key={key}>
                                        <span className="text-purple-400">{key}: </span>
                                        <span className="text-slate-200">
                                            {Array.isArray(val) ? val.map(v => <div className="pl-4 text-xs text-slate-400" key={v}>- {v}</div>) : val}
                                        </span>
                                    </div>
                                ))}
                                <div className="text-slate-400">----------------------------------------</div>
                                <div className="text-xs text-slate-500 mt-4">[Sandbox Mode] No actual emails were sent. No files were written to production Drive.</div>
                            </div>
                        )}

                        {!testLoading && !testResult && (
                            <div className="mt-8 text-center text-slate-600 italic">
                                Ready to start. Click "Run Test" to simulate execution.
                            </div>
                        )}
                    </div>
                 </div>
             </div>
          )}

        </div>
      </div>
    </div>
  );
};

// --- Helper Sub-components ---

const SectionHeader = ({ icon, title }: { icon: any, title: string }) => (
  <div className="flex items-center gap-2 text-slate-800 font-semibold mb-3 border-b border-slate-100 pb-2">
    <span className="text-brand-500">{icon}</span>
    <h3>{title}</h3>
  </div>
);

const Toggle = ({ enabled, onChange, disabled }: { enabled: boolean, onChange: (v: boolean) => void, disabled: boolean }) => (
  <button
    onClick={() => !disabled && onChange(!enabled)}
    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
      enabled ? 'bg-brand-600' : 'bg-slate-300'
    } ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
  >
    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${enabled ? 'translate-x-6' : 'translate-x-1'}`} />
  </button>
);

const KeywordInput = ({ label, keywords, inputValue, setInputValue, onAdd, onRemove, disabled }: any) => (
  <div className="space-y-2">
    <label className="text-sm font-medium text-slate-700">{label}</label>
    <div className="flex gap-2">
      <input 
        type="text" 
        value={inputValue}
        disabled={disabled}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={(e) => e.key === 'Enter' && onAdd()}
        className="flex-1 input-std"
        placeholder="Type keyword and press Enter"
      />
      <button 
        onClick={onAdd}
        disabled={disabled} 
        className="px-3 bg-slate-200 text-slate-700 rounded-lg hover:bg-slate-300 disabled:opacity-50"
      >
        <PlusIcon />
      </button>
    </div>
    <div className="flex flex-wrap gap-2 mt-2">
      {keywords.map((k: string) => (
        <span key={k} className="inline-flex items-center gap-1 bg-white border border-slate-300 px-2 py-1 rounded-md text-sm text-slate-700 shadow-sm">
          {k}
          {!disabled && (
            <button onClick={() => onRemove(k)} className="text-slate-400 hover:text-red-500">
               <XIcon />
            </button>
          )}
        </span>
      ))}
    </div>
  </div>
);

// Simplified Icons for sub-components
const PlusIcon = () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>;
const XIcon = () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>;
const PowerIcon = () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18.36 6.64a9 9 0 1 1-12.73 0"></path><line x1="12" y1="2" x2="12" y2="12"></line></svg>;

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, Save, Play, CheckCircle2, AlertCircle, FileCode, FolderOpen, 
  Mail, Bot, Settings2, History, RotateCcw, X, Beaker, Filter 
} from 'lucide-react';
import { 
  Agent, AgentStatus, AgentType, UserRole, 
  AVAILABLE_WORKFLOWS, AVAILABLE_TRIGGERS, ALLOWED_VARIABLES, AuditLog 
} from '../types';

interface AgentFormProps {
  initialData?: Agent;
  role: UserRole;
  onSave: (agent: Agent) => void;
  onBack: () => void;
  auditLogs: AuditLog[];
}

const TABS = [
  { id: 'general', label: 'General Info', icon: <Settings2 size={16} /> },
  { id: 'config', label: 'Configuration', icon: <FileCode size={16} /> },
  { id: 'automation', label: 'Drive Automation', icon: <FolderOpen size={16} /> },
  { id: 'test', label: 'Test Run', icon: <Beaker size={16} /> },
  { id: 'history', label: 'Audit Log', icon: <History size={16} /> },
];

export const AgentForm: React.FC<AgentFormProps> = ({ initialData, role, onSave, onBack, auditLogs }) => {
  const [activeTab, setActiveTab] = useState('general');
  const [isTestModalOpen, setTestModalOpen] = useState(false);
  const [testResult, setTestResult] = useState<any>(null);
  const [testLoading, setTestLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, // Default
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
      targetFolderPath: '/Shared Drives/Company/',
      renamePattern: '{DocNo}_{Date}',
      folderStructure: '/{Year}/{Month}/'
    }
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Keyword input state
  const [subjectKeyInput, setSubjectKeyInput] = useState('');
  const [bodyKeyInput, setBodyKeyInput] = useState('');

  const isAdmin = role === UserRole.ADMIN;
  const isReadOnly = !isAdmin;

  const INPUT_CLASS = "w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none transition-all bg-white";

  // Handlers
  const handleInputChange = (field: string, value: any) => {
    if (isReadOnly) return;
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error if exists
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleNestedChange = (section: 'mailConfig' | 'aiConfig' | 'driveConfig', field: string, value: any) => {
    if (isReadOnly) return;
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const addKeyword = (type: 'subject' | 'body', value: string) => {
    if (isReadOnly || !value.trim()) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];

    if (!currentList.includes(value.trim())) {
      handleNestedChange(section, field, [...currentList, value.trim()]);
    }
    if (type === 'subject') setSubjectKeyInput('');
    else setBodyKeyInput('');
  };

  const removeKeyword = (type: 'subject' | 'body', keyword: string) => {
    if (isReadOnly) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];
    handleNestedChange(section, field, currentList.filter(k => k !== keyword));
  };

  const validateForm = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = 'Agent name is required';
    if (formData.name.length > 120) newErrors.name = 'Name must be less than 120 characters';

    // Workflow validation
    if (formData.status === AgentStatus.ACTIVE && !formData.workflowId) {
      newErrors.workflowId = 'Workflow is required to enable agent';
    }

    // Drive validation
    if (formData.driveConfig?.autoSave && !formData.driveConfig.targetFolderPath) {
      newErrors.targetPath = 'Target folder path is required';
    }

    // Pattern validation (check for illegal chars or unknown variables)
    if (formData.driveConfig?.autoRename && formData.driveConfig.renamePattern) {
        // Simple regex for invalid filename chars (windows style)
        if (/[<>:"/\\|?*]/.test(formData.driveConfig.renamePattern)) {
            newErrors.renamePattern = 'Filename pattern contains invalid characters';
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (targetStatus?: AgentStatus) => {
    if (!validateForm()) {
        alert("Please fix the errors before saving.");
        return;
    }

    const updatedAgent = {
      ...formData,
      status: targetStatus || formData.status,
      updatedAt: new Date().toISOString()
    };
    onSave(updatedAgent);
  };

  const runTest = () => {
    setTestLoading(true);
    setTestResult(null);
    // Simulate API call
    setTimeout(() => {
        setTestLoading(false);
        setTestResult({
            success: true,
            message: "Processed successfully",
            details: {
                trigger: "Manual Test",
                input: formData.type === AgentType.MAIL ? "Sample Email Subject: Invoice #1234" : "Sample Context Data",
                actions: [
                    "Filter matched: Yes",
                    "Workflow Triggered: Invoice Processing",
                    formData.driveConfig?.autoSave ? `File Saved to: ${formData.driveConfig.targetFolderPath}` : "File Save: Skipped"
                ]
            }
        });
    }, 1500);
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-slate-50">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
             <h2 className="text-xl font-bold text-slate-800">{initialData ? `Edit Agent: ${formData.name}` : 'Create New Agent'}</h2>
             <div className="flex items-center gap-2 text-sm text-slate-500 mt-0.5">
                <span className={`w-2 h-2 rounded-full ${
                    formData.status === AgentStatus.ACTIVE ? 'bg-emerald-500' : 
                    formData.status === AgentStatus.INACTIVE ? 'bg-slate-400' : 'bg-amber-400'
                }`}></span>
                {formData.status}
             </div>
          </div>
        </div>

        {isAdmin && (
          <div className="flex items-center gap-3">
             <button 
               onClick={() => handleSubmit(AgentStatus.DRAFT)}
               className="px-4 py-2 text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 font-medium transition-colors"
             >
               Save Draft
             </button>
             <button 
               onClick={() => handleSubmit(AgentStatus.ACTIVE)}
               className="px-4 py-2 flex items-center gap-2 text-white bg-emerald-600 rounded-lg hover:bg-emerald-700 font-medium transition-colors shadow-sm"
             >
               <CheckCircle2 size={18} />
               {formData.status === AgentStatus.ACTIVE ? 'Save Changes' : 'Publish & Enable'}
             </button>
             {formData.status === AgentStatus.ACTIVE && (
                 <button 
                    onClick={() => handleSubmit(AgentStatus.INACTIVE)}
                    className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg"
                    title="Disable Agent"
                 >
                    <PowerIcon />
                 </button>
             )}
          </div>
        )}
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Tabs */}
        <div className="w-64 bg-slate-50 border-r border-slate-200 p-4 space-y-1">
          {TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${
                activeTab === tab.id 
                  ? 'bg-white text-brand-600 shadow-sm border border-slate-200' 
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-8">

          {/* GENERAL INFO TAB */}
          {activeTab === 'general' && (
            <div className="max-w-3xl space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2 col-span-2">
                  <label className="block text-sm font-semibold text-slate-700">Agent Name <span className="text-red-500">*</span></label>
                  <input
                    type="text"
                    disabled={isReadOnly}
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    className={`${INPUT_CLASS} ${errors.name ? 'border-red-500' : 'border-slate-300'}`}
                    placeholder="e.g. Invoice Processing Agent"
                  />
                  {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Agent Type <span className="text-red-500">*</span></label>
                  <select
                    disabled={isReadOnly}
                    value={formData.type}
                    onChange={(e) => handleInputChange('type', e.target.value)}
                    className={INPUT_CLASS}
                  >
                    <option value={AgentType.MAIL}>Mail Agent</option>
                    <option value={AgentType.AI}>AI Agent</option>
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Workflow Binding</label>
                  <select
                    disabled={isReadOnly}
                    value={formData.workflowId}
                    onChange={(e) => handleInputChange('workflowId', e.target.value)}
                    className={`${INPUT_CLASS} ${errors.workflowId ? 'border-red-500' : 'border-slate-300'}`}
                  >
                    <option value="">-- Select Workflow --</option>
                    {AVAILABLE_WORKFLOWS.map(wf => (
                      <option key={wf.id} value={wf.id}>{wf.name}</option>
                    ))}
                  </select>
                  {errors.workflowId && <p className="text-red-500 text-xs mt-1">{errors.workflowId}</p>}
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Trigger Event</label>
                  <select
                    disabled={isReadOnly}
                    value={formData.triggerEvent}
                    onChange={(e) => handleInputChange('triggerEvent', e.target.value)}
                    className={INPUT_CLASS}
                  >
                     <option value="">-- Select Trigger --</option>
                    {AVAILABLE_TRIGGERS.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>

                <div className="col-span-2 space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Description</label>
                  <textarea
                    disabled={isReadOnly}
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    className={`${INPUT_CLASS} h-24 resize-none`}
                    placeholder="Describe what this agent does..."
                  />
                </div>
              </div>
            </div>
          )}

          {/* CONFIGURATION TAB */}
          {activeTab === 'config' && (
            <div className="max-w-3xl space-y-8 animate-fadeIn">
              {formData.type === AgentType.MAIL ? (
                <>
                  <SectionHeader icon={<Mail size={20} />} title="Email Scope" />

                  <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-2">
                         <label className="text-sm font-medium text-slate-700">Sender Email (From)</label>
                         <input 
                            type="email" 
                            disabled={isReadOnly}
                            value={formData.mailConfig?.senderEmail}
                            onChange={(e) => handleNestedChange('mailConfig', 'senderEmail', e.target.value)}
                            className={INPUT_CLASS}
                            placeholder="e.g. client@example.com (Optional)"
                         />
                         <p className="text-xs text-slate-500">Only process emails from this specific sender.</p>
                      </div>
                      <div className="space-y-2">
                         <label className="text-sm font-medium text-slate-700">Receiver Email (To)</label>
                         <input 
                            type="email" 
                            disabled={isReadOnly}
                            value={formData.mailConfig?.receiverEmail}
                            onChange={(e) => handleNestedChange('mailConfig', 'receiverEmail', e.target.value)}
                            className={INPUT_CLASS}
                            placeholder="e.g. invoices@mycompany.com"
                         />
                         <p className="text-xs text-slate-500">The specific inbox address this agent monitors.</p>
                      </div>
                    </div>

                    <div className="border-t border-slate-100 bg-slate-50/50 p-6">
                      <div className="flex items-center justify-between mb-4">
                         <div className="flex items-center gap-2">
                            <div className={`p-1.5 rounded-md ${formData.mailConfig?.enableFilter ? 'bg-brand-100 text-brand-600' : 'bg-slate-200 text-slate-500'}`}>
                              <Filter size={18} />
                            </div>
                            <div>
                                <h4 className="text-sm font-semibold text-slate-800">Advanced Filtering</h4>
                                <p className="text-xs text-slate-500">Filter incoming emails by keywords in subject or body.</p>
                            </div>
                         </div>
                         <Toggle 
                            enabled={formData.mailConfig?.enableFilter || false} 
                            onChange={(v) => handleNestedChange('mailConfig', 'enableFilter', v)} 
                            disabled={isReadOnly}
                         />
                      </div>

                      {formData.mailConfig?.enableFilter && (
                        <div className="space-y-6 pt-2 animate-fadeIn">
                           <KeywordInput 
                              label="Subject Keywords" 
                              keywords={formData.mailConfig?.subjectKeywords || []} 
                              inputValue={subjectKeyInput}
                              setInputValue={setSubjectKeyInput}
                              onAdd={() => addKeyword('subject', subjectKeyInput)}
                              onRemove={(k) => removeKeyword('subject', k)}
                              disabled={isReadOnly}
                              inputClass={INPUT_CLASS}
                           />
                           <KeywordInput 
                              label="Body Keywords" 
                              keywords={formData.mailConfig?.bodyKeywords || []} 
                              inputValue={bodyKeyInput}
                              setInputValue={setBodyKeyInput}
                              onAdd={() => addKeyword('body', bodyKeyInput)}
                              onRemove={(k) => removeKeyword('body', k)}
                              disabled={isReadOnly}
                              inputClass={INPUT_CLASS}
                           />
                        </div>
                      )}
                    </div>
                  </div>
                </>
              ) : (
                <>
                  <SectionHeader icon={<Bot size={20} />} title="AI Agent Settings" />
                  <div className="space-y-4 p-4 bg-purple-50 rounded-lg border border-purple-100">
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">AI Model</label>
                        <select 
                           disabled={isReadOnly}
                           value={formData.aiConfig?.model}
                           onChange={(e) => handleNestedChange('aiConfig', 'model', e.target.value)}
                           className={INPUT_CLASS}
                        >
                           <option value="gemini-pro">Gemini Pro</option>
                           <option value="gpt-4">GPT-4</option>
                           <option value="claude-3">Claude 3</option>
                        </select>
                     </div>
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Input Context Source</label>
                        <textarea 
                           disabled={isReadOnly}
                           value={formData.aiConfig?.inputSource}
                           onChange={(e) => handleNestedChange('aiConfig', 'inputSource', e.target.value)}
                           className={`${INPUT_CLASS} h-24`}
                           placeholder="Define system prompt or context source..."
                        />
                     </div>
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">Output Action Definition</label>
                        <textarea 
                           disabled={isReadOnly}
                           value={formData.aiConfig?.outputAction}
                           onChange={(e) => handleNestedChange('aiConfig', 'outputAction', e.target.value)}
                           className={`${INPUT_CLASS} h-24`}
                           placeholder="Define what the AI should produce (JSON, Summary, etc.)..."
                        />
                     </div>
                  </div>
                </>
              )}
            </div>
          )}

          {/* AUTOMATION TAB */}
          {activeTab === 'automation' && (
             <div className="max-w-3xl space-y-8 animate-fadeIn">

                {/* Auto Save */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Save size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">Auto Save to Drive</h3>
                            <p className="text-xs text-slate-500">Automatically save attachments/outputs</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoSave || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoSave', v)} 
                        disabled={isReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoSave && (
                      <div className="ml-12 space-y-2">
                         <label className="text-sm font-medium text-slate-700">Target Folder Path <span className="text-red-500">*</span></label>
                         <div className="flex gap-2">
                            <input 
                              type="text" 
                              disabled={isReadOnly}
                              value={formData.driveConfig?.targetFolderPath}
                              onChange={(e) => handleNestedChange('driveConfig', 'targetFolderPath', e.target.value)}
                              className={`flex-1 ${INPUT_CLASS} ${errors.targetPath ? 'border-red-500' : ''}`}
                              placeholder="/My Drive/Agent_Output/"
                            />
                            <button className="px-3 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200" title="Check Permissions">
                               <CheckCircle2 size={18} />
                            </button>
                         </div>
                         {errors.targetPath && <p className="text-red-500 text-xs">{errors.targetPath}</p>}
                      </div>
                   )}
                </div>

                {/* Auto Rename */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><FileCode size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">Auto Rename File</h3>
                            <p className="text-xs text-slate-500">Rename files based on patterns</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoRename || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoRename', v)} 
                        disabled={isReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoRename && (
                      <div className="ml-12 space-y-3">
                         <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700">Rename Pattern</label>
                            <input 
                               type="text" 
                               disabled={isReadOnly}
                               value={formData.driveConfig?.renamePattern}
                               onChange={(e) => handleNestedChange('driveConfig', 'renamePattern', e.target.value)}
                               className={INPUT_CLASS}
                               placeholder="{DocNo}_{Customer}_{Date}"
                            />
                            <p className="text-xs text-slate-500">
                               Allowed variables: {ALLOWED_VARIABLES.map(v => <span key={v} className="inline-block bg-slate-100 px-1 rounded mr-1 text-slate-700 font-mono">{v}</span>)}
                            </p>
                            {errors.renamePattern && <p className="text-red-500 text-xs">{errors.renamePattern}</p>}
                         </div>
                      </div>
                   )}
                </div>

                {/* Auto Create Folder */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg"><FolderOpen size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">Auto Create Folder</h3>
                            <p className="text-xs text-slate-500">Organize files into dynamic subfolders</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoCreateFolder || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoCreateFolder', v)} 
                        disabled={isReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoCreateFolder && (
                      <div className="ml-12 space-y-2">
                         <label className="text-sm font-medium text-slate-700">Folder Structure Rule</label>
                         <input 
                            type="text" 
                            disabled={isReadOnly}
                            value={formData.driveConfig?.folderStructure}
                            onChange={(e) => handleNestedChange('driveConfig', 'folderStructure', e.target.value)}
                            className={INPUT_CLASS}
                            placeholder="/{Year}/{Month}/{Customer}/"
                         />
                         <p className="text-xs text-slate-500">The system will verify write permissions and create folders if they don't exist.</p>
                      </div>
                   )}
                </div>

             </div>
          )}

          {/* HISTORY TAB */}
          {activeTab === 'history' && (
             <div className="space-y-4 animate-fadeIn">
                <h3 className="text-lg font-semibold text-slate-800 mb-4">Audit Logs</h3>
                <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
                   <table className="w-full text-sm text-left">
                      <thead className="bg-slate-50 border-b border-slate-200 text-slate-600">
                         <tr>
                            <th className="p-4">Timestamp</th>
                            <th className="p-4">User</th>
                            <th className="p-4">Action</th>
                            <th className="p-4">Details</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {auditLogs.map(log => (
                            <tr key={log.id}>
                               <td className="p-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                               <td className="p-4 font-medium text-slate-700">{log.user}</td>
                               <td className="p-4">
                                  <span className="bg-slate-100 text-slate-700 px-2 py-1 rounded text-xs border border-slate-200">{log.action}</span>
                               </td>
                               <td className="p-4 text-slate-600">{log.details}</td>
                            </tr>
                         ))}
                         {auditLogs.length === 0 && (
                             <tr><td colSpan={4} className="p-8 text-center text-slate-400">No history available for this agent.</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          )}

          {/* TEST TAB */}
          {activeTab === 'test' && (
             <div className="max-w-3xl animate-fadeIn">
                 <div className="bg-slate-900 text-slate-300 rounded-xl p-6 shadow-lg">
                    <div className="flex items-center justify-between mb-6">
                        <h3 className="text-white text-lg font-semibold flex items-center gap-2"><Beaker /> Test Simulator</h3>
                        {role === UserRole.ADMIN ? (
                             <button 
                                onClick={runTest}
                                disabled={testLoading}
                                className={`px-4 py-2 rounded-lg font-bold text-white transition-all flex items-center gap-2 ${testLoading ? 'bg-slate-700 cursor-not-allowed' : 'bg-brand-600 hover:bg-brand-500'}`}
                             >
                                {testLoading ? 'Running...' : 'Run Test'}
                                {!testLoading && <Play size={16} fill="currentColor"/>}
                             </button>
                        ) : (
                            <span className="text-xs text-amber-500 border border-amber-500/30 px-2 py-1 rounded">Admin Access Required</span>
                        )}
                    </div>

                    <div className="font-mono text-sm bg-black/50 p-4 rounded-lg min-h-[300px] overflow-auto">
                        <div className="mb-2 text-brand-400">$ Initializing Agent Environment...</div>
                        <div className="mb-2 text-brand-400">$ Loading Configuration for "{formData.name}"...</div>

                        {testLoading && (
                            <div className="animate-pulse text-slate-500 mt-4">
                                &gt; Processing input stream...<br/>
                                &gt; Applying filters...<br/>
                                &gt; Validating drive permissions...
                            </div>
                        )}

                        {testResult && (
                            <div className="mt-4 space-y-2 animate-fadeIn">
                                <div className="text-emerald-400 font-bold">✓ Process Completed Successfully</div>
                                <div className="text-slate-400">----------------------------------------</div>
                                {Object.entries(testResult.details).map(([key, val]: any) => (
                                    <div key={key}>
                                        <span className="text-purple-400">{key}: </span>
                                        <span className="text-slate-200">
                                            {Array.isArray(val) ? val.map(v => <div className="pl-4 text-xs text-slate-400" key={v}>- {v}</div>) : val}
                                        </span>
                                    </div>
                                ))}
                                <div className="text-slate-400">----------------------------------------</div>
                                <div className="text-xs text-slate-500 mt-4">[Sandbox Mode] No actual emails were sent. No files were written to production Drive.</div>
                            </div>
                        )}

                        {!testLoading && !testResult && (
                            <div className="mt-8 text-center text-slate-600 italic">
                                Ready to start. Click "Run Test" to simulate execution.
                            </div>
                        )}
                    </div>
                 </div>
             </div>
          )}

        </div>
      </div>
    </div>
  );
};

// --- Helper Sub-components ---

const SectionHeader = ({ icon, title }: { icon: any, title: string }) => (
  <div className="flex items-center gap-2 text-slate-800 font-semibold mb-3 border-b border-slate-100 pb-2">
    <span className="text-brand-500">{icon}</span>
    <h3>{title}</h3>
  </div>
);

const Toggle = ({ enabled, onChange, disabled }: { enabled: boolean, onChange: (v: boolean) => void, disabled: boolean }) => (
  <button
    onClick={() => !disabled && onChange(!enabled)}
    className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
      enabled ? 'bg-brand-600' : 'bg-slate-300'
    } ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
  >
    <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${enabled ? 'translate-x-6' : 'translate-x-1'}`} />
  </button>
);

const KeywordInput = ({ label, keywords, inputValue, setInputValue, onAdd, onRemove, disabled, inputClass }: any) => (
  <div className="space-y-2">
    <label className="text-sm font-medium text-slate-700">{label}</label>
    <div className="flex gap-2">
      <input 
        type="text" 
        value={inputValue}
        disabled={disabled}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={(e) => e.key === 'Enter' && onAdd()}
        className={`flex-1 ${inputClass || ''}`}
        placeholder="Type keyword and press Enter"
      />
      <button 
        onClick={onAdd}
        disabled={disabled} 
        className="px-3 bg-slate-200 text-slate-700 rounded-lg hover:bg-slate-300 disabled:opacity-50"
      >
        <PlusIcon />
      </button>
    </div>
    <div className="flex flex-wrap gap-2 mt-2">
      {keywords.map((k: string) => (
        <span key={k} className="inline-flex items-center gap-1 bg-white border border-slate-300 px-2 py-1 rounded-md text-sm text-slate-700 shadow-sm">
          {k}
          {!disabled && (
            <button onClick={() => onRemove(k)} className="text-slate-400 hover:text-red-500">
               <XIcon />
            </button>
          )}
        </span>
      ))}
    </div>
  </div>
);

// Simplified Icons for sub-components
const PlusIcon = () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>;
const XIcon = () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>;
const PowerIcon = () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18.36 6.64a9 9 0 1 1-12.73 0"></path><line x1="12" y1="2" x2="12" y2="12"></line></svg>;

export enum AgentType {
  MAIL = 'MAIL',
  AI = 'AI'
}

export enum AgentStatus {
  DRAFT = 'DRAFT',
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

export interface MailConfig {
  senderEmail?: string;
  receiverEmail?: string;
  enableFilter: boolean;
  subjectKeywords: string[];
  bodyKeywords: string[];
  subjectTemplate?: string;
  bodyTemplate?: string;
}

export interface AIConfig {
  inputSource?: string;
  outputAction?: string;
  model: string;
}

export interface DriveConfig {
  autoSave: boolean;
  targetFolderPath?: string;
  autoRename: boolean;
  renamePattern?: string; // e.g. {DocNo}_{Date}
  autoCreateFolder: boolean;
  folderStructure?: string; // e.g. /{Year}/{Customer}/
}

export interface Agent {
  id: string;
  name: string;
  description: string;
  type: AgentType;
  status: AgentStatus;
  updatedAt: string;
  updatedBy: string;
  companyId: string;
  workflowId?: string; // The workflow this agent is bound to
  triggerEvent?: string; // e.g., "On Document Create"

  // Specific Configs
  mailConfig?: MailConfig;
  aiConfig?: AIConfig;
  driveConfig?: DriveConfig;
}

// Mock Data Types
export const AVAILABLE_WORKFLOWS = [
  { id: 'wf-001', name: 'Invoice Processing' },
  { id: 'wf-002', name: 'Customer Support Ticket' },
  { id: 'wf-003', name: 'HR Onboarding' }
];

export const AVAILABLE_TRIGGERS = [
  'On Email Received',
  'On Document Created',
  'Schedule: Daily 9:00 AM',
  'Manual Trigger Only'
];

export const ALLOWED_VARIABLES = ['{DocNo}', '{Date}', '{Customer}', '{AgentName}', '{Year}', '{Month}', '{DocType}'];

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, Save, Play, CheckCircle2, AlertCircle, FileCode, FolderOpen, 
  Mail, Bot, Settings2, History, RotateCcw, X, Beaker, Filter, MessageSquare 
} from 'lucide-react';
import { 
  Agent, AgentStatus, AgentType, UserRole, 
  AVAILABLE_WORKFLOWS, AVAILABLE_TRIGGERS, ALLOWED_VARIABLES, AuditLog 
} from '../types';

interface AgentFormProps {
  initialData?: Agent;
  role: UserRole;
  onSave: (agent: Agent) => void;
  onBack: () => void;
  auditLogs: AuditLog[];
}

const TABS = [
  { id: 'general', label: 'General Info', icon: <Settings2 size={16} /> },
  { id: 'config', label: 'Configuration', icon: <FileCode size={16} /> },
  { id: 'automation', label: 'Drive Automation', icon: <FolderOpen size={16} /> },
  { id: 'test', label: 'Test Run', icon: <Beaker size={16} /> },
  { id: 'history', label: 'Audit Log', icon: <History size={16} /> },
];

export const AgentForm: React.FC<AgentFormProps> = ({ initialData, role, onSave, onBack, auditLogs }) => {
  const [activeTab, setActiveTab] = useState('general');
  const [isTestModalOpen, setTestModalOpen] = useState(false);
  const [testResult, setTestResult] = useState<any>(null);
  const [testLoading, setTestLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, // Default
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: '',
      subjectTemplate: '',
      bodyTemplate: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
      targetFolderPath: '/Shared Drives/Company/',
      renamePattern: '{DocNo}_{Date}',
      folderStructure: '/{Year}/{Month}/'
    }
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Keyword input state
  const [subjectKeyInput, setSubjectKeyInput] = useState('');
  const [bodyKeyInput, setBodyKeyInput] = useState('');

  const isAdmin = role === UserRole.ADMIN;
  const isReadOnly = !isAdmin;

  const INPUT_CLASS = "w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none transition-all bg-white";

  // Handlers
  const handleInputChange = (field: string, value: any) => {
    if (isReadOnly) return;
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error if exists
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleNestedChange = (section: 'mailConfig' | 'aiConfig' | 'driveConfig', field: string, value: any) => {
    if (isReadOnly) return;
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const addKeyword = (type: 'subject' | 'body', value: string) => {
    if (isReadOnly || !value.trim()) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];

    if (!currentList.includes(value.trim())) {
      handleNestedChange(section, field, [...currentList, value.trim()]);
    }
    if (type === 'subject') setSubjectKeyInput('');
    else setBodyKeyInput('');
  };

  const removeKeyword = (type: 'subject' | 'body', keyword: string) => {
    if (isReadOnly) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];
    handleNestedChange(section, field, currentList.filter(k => k !== keyword));
  };

  const validateForm = (checkStatus: AgentStatus) => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = 'Agent name is required';
    if (formData.name.length > 120) newErrors.name = 'Name must be less than 120 characters';

    // Workflow validation: STRICT rule for activation
    if (checkStatus === AgentStatus.ACTIVE) {
      if (!formData.workflowId) {
        newErrors.workflowId = 'Workflow binding is required to enable agent';
      }
      if (!formData.triggerEvent) {
        newErrors.triggerEvent = 'Trigger Event must be defined to enable agent';
      }
    }

    // Drive validation
    if (formData.driveConfig?.autoSave && !formData.driveConfig.targetFolderPath) {
      newErrors.targetPath = 'Target folder path is required';
    }

    // Pattern validation (check for illegal chars or unknown variables)
    if (formData.driveConfig?.autoRename && formData.driveConfig.renamePattern) {
        // Simple regex for invalid filename chars (windows style)
        if (/[<>:"/\\|?*]/.test(formData.driveConfig.renamePattern)) {
            newErrors.renamePattern = 'Filename pattern contains invalid characters';
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (targetStatus?: AgentStatus) => {
    const statusToCheck = targetStatus || formData.status;

    if (!validateForm(statusToCheck)) {
        // Force switch to tab where error might be? Simple alert for now.
        const errorMsg = Object.values(errors)[0] || "Please fix the configuration errors before saving.";

        // Specific error mapping to tabs
        if (errors.workflowId || errors.triggerEvent) setActiveTab('general');
        else if (errors.targetPath || errors.renamePattern) setActiveTab('automation');

        // We need to re-run validate to show the error state in UI (state update batching)
        // Ideally validateForm updates state, which it does.
        return;
    }

    const updatedAgent = {
      ...formData,
      status: statusToCheck,
      updatedAt: new Date().toISOString()
    };
    onSave(updatedAgent);
  };

  const runTest = () => {
    setTestLoading(true);
    setTestResult(null);
    // Simulate API call
    setTimeout(() => {
        setTestLoading(false);
        setTestResult({
            success: true,
            message: "Processed successfully",
            details: {
                trigger: "Manual Test",
                input: formData.type === AgentType.MAIL ? "Sample Email Subject: Invoice #1234" : "Sample Context Data",
                actions: [
                    "Filter matched: Yes",
                    "Workflow Triggered: Invoice Processing",
                    formData.driveConfig?.autoSave ? `File Saved to: ${formData.driveConfig.targetFolderPath}` : "File Save: Skipped"
                ]
            }
        });
    }, 1500);
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-slate-50">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
             <h2 className="text-xl font-bold text-slate-800">{initialData ? `Edit Agent: ${formData.name}` : 'Create New Agent'}</h2>
             <div className="flex items-center gap-2 text-sm text-slate-500 mt-0.5">
                <span className={`w-2 h-2 rounded-full ${
                    formData.status === AgentStatus.ACTIVE ? 'bg-emerald-500' : 
                    formData.status === AgentStatus.INACTIVE ? 'bg-slate-400' : 'bg-amber-400'
                }`}></span>
                {formData.status}
             </div>
          </div>
        </div>

        {isAdmin && (
          <div className="flex items-center gap-3">
             <button 
               onClick={() => handleSubmit(AgentStatus.DRAFT)}
               className="px-4 py-2 text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 font-medium transition-colors"
             >
               Save Draft
             </button>
             <button 
               onClick={() => handleSubmit(AgentStatus.ACTIVE)}
               className="px-4 py-2 flex items-center gap-2 text-white bg-emerald-600 rounded-lg hover:bg-emerald-700 font-medium transition-colors shadow-sm"
               disabled={!!errors.workflowId || !!errors.triggerEvent}
             >
               <CheckCircle2 size={18} />
               {formData.status === AgentStatus.ACTIVE ? 'Save Changes' : 'Publish & Enable'}
             </button>
             {formData.status === AgentStatus.ACTIVE && (
                 <button 
                    onClick={() => handleSubmit(AgentStatus.INACTIVE)}
                    className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg"
                    title="Disable Agent"
                 >
                    <PowerIcon />
                 </button>
             )}
          </div>
        )}
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Tabs */}
        <div className="w-64 bg-slate-50 border-r border-slate-200 p-4 space-y-1">
          {TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${
                activeTab === tab.id 
                  ? 'bg-white text-brand-600 shadow-sm border border-slate-200' 
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-8">

          {/* GENERAL INFO TAB */}
          {activeTab === 'general' && (
            <div className="max-w-3xl space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2 col-span-2">
                  <label className="block text-sm font-semibold text-slate-700">Agent Name <span className="text-red-500">*</span></label>
                  <input
                    type="text"
                    disabled={isReadOnly}
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    className={`${INPUT_CLASS} ${errors.name ? 'border-red-500' : 'border-slate-300'}`}
                    placeholder="e.g. Invoice Processing Agent"
                  />
                  {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Agent Type <span className="text-red-500">*</span></label>
                  <select
                    disabled={isReadOnly}
                    value={formData.type}
                    onChange={(e) => handleInputChange('type', e.target.value)}
                    className={INPUT_CLASS}
                  >
                    <option value={AgentType.MAIL}>Mail Agent</option>
                    <option value={AgentType.AI}>AI Agent</option>
                  </select>
                </div>

                <div className="col-span-2 grid grid-cols-2 gap-6 p-4 bg-blue-50 border border-blue-100 rounded-lg">
                    <div className="col-span-2 text-sm text-blue-800 font-semibold flex items-center gap-2">
                        <Settings2 size={16} /> Workflow Integration
                    </div>
                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-slate-700">Workflow Binding <span className="text-red-500">*</span></label>
                      <select
                        disabled={isReadOnly}
                        value={formData.workflowId}
                        onChange={(e) => handleInputChange('workflowId', e.target.value)}
                        className={`${INPUT_CLASS} ${errors.workflowId ? 'border-red-500' : 'border-slate-300'}`}
                      >
                        <option value="">-- Select Workflow --</option>
                        {AVAILABLE_WORKFLOWS.map(wf => (
                          <option key={wf.id} value={wf.id}>{wf.name}</option>
                        ))}
                      </select>
                      {errors.workflowId && <p className="text-red-500 text-xs mt-1">{errors.workflowId}</p>}
                      <p className="text-xs text-slate-500">The business process this agent is attached to.</p>
                    </div>

                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-slate-700">Trigger Event <span className="text-red-500">*</span></label>
                      <select
                        disabled={isReadOnly}
                        value={formData.triggerEvent}
                        onChange={(e) => handleInputChange('triggerEvent', e.target.value)}
                        className={`${INPUT_CLASS} ${errors.triggerEvent ? 'border-red-500' : 'border-slate-300'}`}
                      >
                         <option value="">-- Select Trigger --</option>
                        {AVAILABLE_TRIGGERS.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                      {errors.triggerEvent && <p className="text-red-500 text-xs mt-1">{errors.triggerEvent}</p>}
                       <p className="text-xs text-slate-500">When should this agent start working?</p>
                    </div>
                </div>

                <div className="col-span-2 space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">Description</label>
                  <textarea
                    disabled={isReadOnly}
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    className={`${INPUT_CLASS} h-24 resize-none`}
                    placeholder="Describe what this agent does..."
                  />
                </div>
              </div>
            </div>
          )}

          {/* CONFIGURATION TAB */}
          {activeTab === 'config' && (
            <div className="max-w-3xl space-y-8 animate-fadeIn">
              {formData.type === AgentType.MAIL ? (
                <>
                  <SectionHeader icon={<Mail size={20} />} title="Email Scope" />

                  <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-2">
                         <label className="text-sm font-medium text-slate-700">From / Email Profile</label>
                         <select 
                            disabled={isReadOnly}
                            value={formData.mailConfig?.senderEmail}
