          {isProfileOpen && (
            <div
              ref={dropdownRef}
              className="absolute top-full right-0 mt-2 w-48 bg-white rounded-md shadow-md py-1 z-10 ring-1 ring-black ring-opacity-5 focus:outline-none"
            >
              <button
                className="block w-full px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 focus:outline-none focus:bg-gray-100"
              >
                AI Agent Settings
              </button>
              <button
                className="block w-full px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 focus:outline-none focus:bg-gray-100"
              >
                User Management
              </button>
              <button
                className="block w-full px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 focus:outline-none focus:bg-gray-100"
                onClick={handleSignOut}
              >
                {t("sign_out")}
              </button>
            </div>
          )}
        </div>
      </header>

      {/* Main content */}
      <main className="flex-grow p-6">
        Main content goes here
      </main>

      {/* Footer */}
      <footer>Footer content here</footer>
    </div>
  );
}

export default Layout;
