import React, { useState, useRef, useEffect } from 'react';
import { LayoutDashboard, Users, Settings, ShieldCheck, LogOut, Bot, Menu, Globe, Home, ChevronRight, Folder, FileText } from 'lucide-react';
import { UserRole, Language } from '../types';
import { TRANSLATIONS } from '../translations';

interface LayoutProps {
  children: React.ReactNode;
  currentUserRole: UserRole;
  onToggleRole: () => void;
  language: Language;
  onLanguageChange: (lang: Language) => void;
}

export const Layout: React.FC<LayoutProps> = ({ children, currentUserRole, onToggleRole, language, onLanguageChange }) => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const profileRef = useRef<HTMLDivElement>(null);
  const t = TRANSLATIONS[language];

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside 
        className={`${isSidebarOpen ? 'w-[280px]' : 'w-20'} bg-white border-r border-slate-200 transition-all duration-300 flex flex-col shadow-sm z-20`}
      >
        {/* Logo Area */}
        <div className="h-16 flex items-center px-6 border-b border-transparent">
             <div className={`flex items-center gap-1 ${!isSidebarOpen && 'justify-center w-full'}`}>
                {isSidebarOpen ? (
                   <div className="flex items-end leading-none cursor-pointer">
                      <span className="text-2xl font-extrabold text-slate-800 tracking-tight">Biz</span>
                      <span className="text-3xl font-extrabold text-[#0ea5e9] -ml-0.5 -mt-1 italic">X</span>
                   </div>
                ) : (
                   <span className="text-2xl font-extrabold text-[#0ea5e9] italic">X</span>
                )}
             </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 py-6 px-3 space-y-1 overflow-y-auto custom-scrollbar">
          <NavItem icon={<LayoutDashboard size={20} />} label={t.dashboard} isActive={false} isOpen={isSidebarOpen} />

          {/* Active Item - Styled like the reference 'Document Tracking' */}
          <NavItem icon={<Bot size={20} />} label={t.agentManagement} isActive={true} isOpen={isSidebarOpen} />

          <NavItem icon={<Users size={20} />} label={t.teamAccess} isActive={false} isOpen={isSidebarOpen} />
          <NavItem icon={<ShieldCheck size={20} />} label={t.auditLogs} isActive={false} isOpen={isSidebarOpen} />
          <NavItem icon={<Settings size={20} />} label={t.settings} isActive={false} isOpen={isSidebarOpen} />
        </nav>

        {/* Bottom Actions */}
        <div className="p-4 border-t border-slate-100">
           <div className={`flex flex-col gap-3 ${!isSidebarOpen && 'items-center'}`}>

              {isSidebarOpen && (
                <>
                   {/* Language Switcher */}
                   <div className="flex items-center justify-between px-3 py-2 bg-slate-50 rounded-lg border border-slate-100">
                       <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                          <Globe size={14} />
                          <span>{t.language}</span>
                       </div>
                       <div className="flex bg-white rounded border border-slate-200 p-0.5 shadow-sm">
                          <button 
                             onClick={() => onLanguageChange('EN')} 
                             className={`px-2 py-0.5 text-[10px] font-bold rounded transition-colors ${language === 'EN' ? 'bg-[#0284c7] text-white' : 'text-slate-400 hover:text-slate-600'}`}
                          >
                             EN
                          </button>
                          <button 
                             onClick={() => onLanguageChange('TH')} 
                             className={`px-2 py-0.5 text-[10px] font-bold rounded transition-colors ${language === 'TH' ? 'bg-[#0284c7] text-white' : 'text-slate-400 hover:text-slate-600'}`}
                          >
                             TH
                          </button>
                       </div>
                   </div>

                   {/* Demo Role Switcher */}
                   <div className="px-1">
                     <p className="text-[10px] text-slate-400 uppercase font-bold tracking-wider mb-1">{t.currentRole}</p>
                     <button 
                       onClick={onToggleRole}
                       className="text-xs font-semibold text-[#0284c7] hover:text-[#0369a1] hover:underline flex items-center gap-1"
                     >
                       {currentUserRole === UserRole.ADMIN ? 'Administrator' : 'Standard User'}
                       <span className="text-slate-400 text-[10px] font-normal">({t.switchTo} {currentUserRole === UserRole.ADMIN ? t.roleUser : t.roleAdmin})</span>
                     </button>
                   </div>
                </>
              )}

              <button className={`flex items-center gap-3 text-slate-500 hover:text-red-600 p-2 rounded-lg hover:bg-red-50 transition-colors w-full ${!isSidebarOpen && 'justify-center'}`}>
                <LogOut size={20} />
                {isSidebarOpen && <span className="text-sm font-medium">{t.signOut}</span>}
              </button>
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full min-w-0 bg-slate-50/50">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 shadow-sm z-10 sticky top-0">

          <div className="flex items-center gap-4">
             <button 
               onClick={() => setIsSidebarOpen(!isSidebarOpen)}
               className="p-2 hover:bg-slate-100 rounded-lg text-slate-600 transition-colors"
             >
               <Menu size={20} />
             </button>

             {/* Breadcrumbs */}
             <div className="hidden md:flex items-center gap-2 text-sm text-slate-500">
                <a href="#" className="flex items-center gap-1 hover:text-[#0284c7] transition-colors">
                   <Home size={16} />
                   <span className="hidden lg:inline">{language === 'TH' ? 'หน้าแรก' : 'Home'}</span>
                </a>
                <ChevronRight size={14} className="text-slate-300" />
                <div className="flex items-center gap-1 hover:text-[#0284c7] transition-colors cursor-pointer">
                   <Folder size={16} />
                   <span>Agent System</span>
                </div>
                <ChevronRight size={14} className="text-slate-300" />
                <div className="flex items-center gap-1 font-medium text-slate-800">
                   <FileText size={16} />
                   <span>{t.agentManagement}</span>
                </div>
             </div>
          </div>

          {/* User Profile */}
          <div className="flex items-center gap-4 pl-4 border-l border-slate-100 h-8" ref={profileRef}>
             <div 
                 className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity relative"
                 onClick={() => setIsProfileOpen(!isProfileOpen)}
             >
                 <div className="hidden sm:flex flex-col items-end mr-1">
                    <span className="text-sm font-bold text-slate-800 leading-tight">Kunawut Wachirapunyawut</span>
                    <span className="text-[11px] text-slate-500">Acme Corp</span>
                 </div>
                 <div className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-600 font-bold text-lg ring-2 ring-white shadow-sm">
                    K
                 </div>

                 {/* Dropdown Menu */}
                 {isProfileOpen && (
                    <div className="absolute top-full right-0 mt-2 w-60 bg-white rounded-xl shadow-xl border border-slate-100 py-2 z-50 animate-in fade-in zoom-in-95 duration-200 origin-top-right">
                        <div className="px-4 py-2 border-b border-slate-50 mb-1">
                            <p className="text-sm font-bold text-slate-800">Kunawut Wachirapunyawut</p>
                            <p className="text-xs text-slate-500 truncate">kunawut.w@bizx.com</p>
                        </div>

                        <button className="w-full text-left px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-50 flex items-center gap-3 transition-colors">
                            <Bot size={18} className="text-slate-400" />
                            {t.aiAgentSettings}
                        </button>

                        <button className="w-full text-left px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-50 flex items-center gap-3 transition-colors">
                            <Users size={18} className="text-slate-400" />
                            {t.userManagement}
                        </button>

                        <div className="border-t border-slate-100 my-1"></div>

                        <button className="w-full text-left px-4 py-2.5 text-sm font-medium text-red-600 hover:bg-red-50 flex items-center gap-3 transition-colors rounded-b-xl">
                            <LogOut size={18} />
                            {t.signOut}
                        </button>
                    </div>
                 )}
             </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 scroll-smooth">
          {children}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ icon, label, isActive, isOpen }: { icon: any, label: string, isActive: boolean, isOpen: boolean }) => (
  <button
    className={`w-full flex items-center gap-3 px-3 py-2.5 mb-1 rounded-lg transition-all duration-200 group ${
      isActive 
        ? 'bg-[#2563eb] text-white shadow-md shadow-blue-200/50' 
        : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900'
    } ${!isOpen && 'justify-center'}`}
  >
    <span className={`${!isActive && 'text-slate-400 group-hover:text-slate-600'}`}>
        {icon}
    </span>
    {isOpen && <span className="text-sm font-medium">{label}</span>}
  </button>
);

export enum AgentType {
  MAIL = 'MAIL',
  AI = 'AI'
}

export enum AgentStatus {
  DRAFT = 'DRAFT',
  ACTIVE = 'ACTIVE',
  INACTIVE = 'INACTIVE'
}

export enum UserRole {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export type Language = 'EN' | 'TH';

export interface AuditLog {
  id: string;
  action: string;
  user: string;
  timestamp: string;
  details: string;
}

export interface MailConfig {
  senderEmail?: string;
  receiverEmail?: string;
  enableFilter: boolean;
  subjectKeywords: string[];
  bodyKeywords: string[];
  subjectTemplate?: string;
  bodyTemplate?: string;
}

export interface AIConfig {
  inputSource?: string;
  outputAction?: string;
  model: string;
}

export interface DriveConfig {
  autoSave: boolean;
  targetFolderPath?: string;
  autoRename: boolean;
  renamePattern?: string; // e.g. {DocNo}_{Date}
  autoCreateFolder: boolean;
  folderStructure?: string; // e.g. /{Year}/{Customer}/
}

export interface Agent {
  id: string;
  name: string;
  description: string;
  type: AgentType;
  status: AgentStatus;
  createdAt: string;
  createdBy: string;
  updatedAt: string;
  updatedBy: string;
  companyId: string;
  workflowId?: string; // The workflow this agent is bound to
  triggerEvent?: string; // e.g., "On Document Create"

  // Specific Configs
  mailConfig?: MailConfig;
  aiConfig?: AIConfig;
  driveConfig?: DriveConfig;
}

// Mock Data Types
export const AVAILABLE_WORKFLOWS = [
  { id: 'wf-001', name: 'Invoice Processing' },
  { id: 'wf-002', name: 'Customer Support Ticket' },
  { id: 'wf-003', name: 'HR Onboarding' }
];

export const AVAILABLE_TRIGGERS = [
  'On Email Received',
  'On Document Created',
  'Schedule: Daily 9:00 AM',
  'Manual Trigger Only'
];

export const ALLOWED_VARIABLES = ['{DocNo}', '{Date}', '{Customer}', '{AgentName}', '{Year}', '{Month}', '{DocType}'];

import React, { useMemo, useState } from 'react';
import { Plus, Search, Filter, MoreVertical, Edit, Power, Eye, Trash2, ChevronLeft, ChevronRight } from 'lucide-react';
import { Agent, AgentStatus, AgentType, UserRole, Language } from '../types';
import { TRANSLATIONS } from '../translations';

interface AgentListProps {
  agents: Agent[];
  role: UserRole;
  language: Language;
  onEdit: (agent: Agent) => void;
  onView: (agent: Agent) => void;
  onCreate: () => void;
  onToggleStatus: (agent: Agent) => void;
  onDelete: (agent: Agent) => void;
}

export const AgentList: React.FC<AgentListProps> = ({ agents, role, language, onEdit, onView, onCreate, onToggleStatus, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('ALL');
  const [typeFilter, setTypeFilter] = useState<string>('ALL');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;
  const t = TRANSLATIONS[language];

  const filteredAgents = useMemo(() => {
    return agents.filter(agent => {
      const matchesSearch = agent.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'ALL' || agent.status === statusFilter;
      const matchesType = typeFilter === 'ALL' || agent.type === typeFilter;
      return matchesSearch && matchesStatus && matchesType;
    });
  }, [agents, searchTerm, statusFilter, typeFilter]);

  // Reset pagination when filters change
  React.useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, statusFilter, typeFilter]);

  const totalPages = Math.ceil(filteredAgents.length / itemsPerPage);
  const paginatedAgents = filteredAgents.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const getStatusColor = (status: AgentStatus) => {
    switch (status) {
      case AgentStatus.ACTIVE: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case AgentStatus.INACTIVE: return 'bg-slate-100 text-slate-600 border-slate-200';
      case AgentStatus.DRAFT: return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-gray-100 text-gray-600';
    }
  };

  const getStatusLabel = (status: AgentStatus) => {
      switch (status) {
          case AgentStatus.ACTIVE: return t.active;
          case AgentStatus.INACTIVE: return t.inactive;
          case AgentStatus.DRAFT: return t.draft;
          default: return status;
      }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">{t.agentManagement}</h1>
          <p className="text-slate-500 mt-1">{t.manageAgents}</p>
        </div>
        {role === UserRole.ADMIN && (
          <button 
            onClick={onCreate}
            className="flex items-center justify-center gap-2 bg-brand-600 hover:bg-brand-700 text-white px-4 py-2.5 rounded-lg font-medium transition-all shadow-sm active:scale-95"
          >
            <Plus size={18} />
            {t.createAgent}
          </button>
        )}
      </div>

      {/* Filters Toolbar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            placeholder={t.searchPlaceholder}
            className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex gap-3">
          <div className="relative">
            <select 
              className="appearance-none bg-slate-50 border border-slate-300 text-slate-700 py-2 pl-3 pr-10 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500 cursor-pointer min-w-[140px]"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
            >
              <option value="ALL">{t.allStatus}</option>
              <option value={AgentStatus.ACTIVE}>{t.active}</option>
              <option value={AgentStatus.INACTIVE}>{t.inactive}</option>
              <option value={AgentStatus.DRAFT}>{t.draft}</option>
            </select>
            <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
          </div>

          <div className="relative">
            <select 
              className="appearance-none bg-slate-50 border border-slate-300 text-slate-700 py-2 pl-3 pr-10 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500 cursor-pointer min-w-[140px]"
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
            >
              <option value="ALL">{t.allTypes}</option>
              <option value={AgentType.MAIL}>{t.mailAgent}</option>
              <option value={AgentType.AI}>{t.aiAgent}</option>
            </select>
            <Filter className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
          </div>
        </div>
      </div>

      {/* Agents Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 text-slate-600 text-xs uppercase font-semibold tracking-wider border-b border-slate-200">
              <tr>
                <th className="px-6 py-4">{t.agentName}</th>
                <th className="px-6 py-4">{t.type}</th>
                <th className="px-6 py-4">{t.status}</th>
                <th className="px-6 py-4">{t.createdBy}</th>
                <th className="px-6 py-4">{t.lastUpdated}</th>
                <th className="px-6 py-4 text-right">{t.actions}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {paginatedAgents.length > 0 ? (
                paginatedAgents.map((agent) => (
                  <tr key={agent.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex flex-col">
                        <span className="font-semibold text-slate-800">{agent.name}</span>
                        <span className="text-xs text-slate-500 truncate max-w-[200px]">{agent.description || '-'}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${
                        agent.type === AgentType.AI 
                          ? 'bg-purple-50 text-purple-700 border-purple-200' 
                          : 'bg-blue-50 text-blue-700 border-blue-200'
                      }`}>
                        {agent.type === AgentType.AI ? t.aiAgent : t.mailAgent}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${getStatusColor(agent.status)}`}>
                        <span className={`w-1.5 h-1.5 rounded-full mr-1.5 ${
                           agent.status === AgentStatus.ACTIVE ? 'bg-emerald-500' : 
                           agent.status === AgentStatus.INACTIVE ? 'bg-slate-500' : 'bg-amber-500'
                        }`}></span>
                        {getStatusLabel(agent.status)}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col text-sm text-slate-600">
                        <span className="font-medium text-slate-700">{agent.createdBy || '-'}</span>
                        {agent.createdAt && <span className="text-xs text-slate-400">{new Date(agent.createdAt).toLocaleDateString()}</span>}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex flex-col text-sm text-slate-600">
                        <span>{new Date(agent.updatedAt).toLocaleDateString()}</span>
                        <span className="text-xs text-slate-400">{t.by} {agent.updatedBy}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-1">
                         <button 
                            onClick={() => onView(agent)}
                            className="p-1.5 text-slate-500 hover:bg-slate-100 hover:text-brand-600 rounded-md transition-colors"
                            title={t.viewDetails}
                          >
                            <Eye size={18} />
                          </button>

                         {role === UserRole.ADMIN && (
                            <>
                              <button 
                                onClick={() => onEdit(agent)}
                                className="p-1.5 text-slate-500 hover:bg-blue-50 hover:text-blue-600 rounded-md transition-colors"
                                title={t.editConfig}
                              >
                                <Edit size={18} />
                              </button>
                              <button 
                                onClick={() => onToggleStatus(agent)}
                                className={`p-1.5 rounded-md transition-colors ${
                                  agent.status === AgentStatus.ACTIVE 
                                    ? 'text-emerald-600 hover:bg-emerald-50' 
                                    : 'text-slate-400 hover:bg-slate-100 hover:text-slate-600'
                                }`}
                                title={agent.status === AgentStatus.ACTIVE ? t.disableAgent : t.enableAgent}
                              >
                                <Power size={18} />
                              </button>
                              <button 
                                onClick={() => onDelete(agent)}
                                className="p-1.5 text-slate-400 hover:bg-red-50 hover:text-red-600 rounded-md transition-colors"
                                title={t.deleteAgent}
                              >
                                <Trash2 size={18} />
                              </button>
                            </>
                         )}
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center">
                    <div className="flex flex-col items-center justify-center text-slate-400">
                      <Search size={48} className="mb-4 text-slate-200" />
                      <p className="text-lg font-medium text-slate-600">{t.noAgentsFound}</p>
                      <p className="text-sm">{t.tryAdjusting}</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {filteredAgents.length > 0 && (
          <div className="px-6 py-4 border-t border-slate-200 flex items-center justify-between bg-slate-50/50">
             <div className="text-sm text-slate-500">
                {t.showing} <span className="font-medium text-slate-800">{(currentPage - 1) * itemsPerPage + 1}</span> {t.to} <span className="font-medium text-slate-800">{Math.min(currentPage * itemsPerPage, filteredAgents.length)}</span> {t.of} <span className="font-medium text-slate-800">{filteredAgents.length}</span> {t.items}
             </div>

             <div className="flex items-center gap-2">
                <button 
                   onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                   disabled={currentPage === 1}
                   className="p-2 rounded-lg border border-slate-200 bg-white text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                   title={t.previous}
                >
                   <ChevronLeft size={16} />
                </button>

                {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                   <button
                      key={p}
                      onClick={() => setCurrentPage(p)}
                      className={`w-8 h-8 rounded-lg text-sm font-medium transition-colors ${
                        currentPage === p 
                          ? 'bg-brand-600 text-white shadow-sm' 
                          : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
                      }`}
                   >
                      {p}
                   </button>
                ))}

                <button 
                   onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                   disabled={currentPage === totalPages}
                   className="p-2 rounded-lg border border-slate-200 bg-white text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                   title={t.next}
                >
                   <ChevronRight size={16} />
                </button>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  ArrowLeft, Save, Play, CheckCircle2, AlertCircle, FileCode, FolderOpen, 
  Mail, Bot, Settings2, History, RotateCcw, X, Beaker, Filter, MessageSquare 
} from 'lucide-react';
import { 
  Agent, AgentStatus, AgentType, UserRole, Language,
  AVAILABLE_WORKFLOWS, AVAILABLE_TRIGGERS, ALLOWED_VARIABLES, AuditLog 
} from '../types';
import { TRANSLATIONS } from '../translations';

interface AgentFormProps {
  initialData?: Agent;
  role: UserRole;
  language: Language;
  onSave: (agent: Agent) => void;
  onBack: () => void;
  auditLogs: AuditLog[];
  readOnly?: boolean;
}

export const AgentForm: React.FC<AgentFormProps> = ({ initialData, role, language, onSave, onBack, auditLogs, readOnly = false }) => {
  const [activeTab, setActiveTab] = useState('general');
  const [testResult, setTestResult] = useState<any>(null);
  const [testLoading, setTestLoading] = useState(false);
  const t = TRANSLATIONS[language];

  const TABS = [
    { id: 'general', label: t.tabGeneral, icon: <Settings2 size={16} /> },
    { id: 'config', label: t.tabConfig, icon: <FileCode size={16} /> },
    { id: 'automation', label: t.tabAutomation, icon: <FolderOpen size={16} /> },
    { id: 'test', label: t.tabTest, icon: <Beaker size={16} /> },
    { id: 'history', label: t.tabHistory, icon: <History size={16} /> },
  ];

  // Form State
  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, // Default
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    createdAt: new Date().toISOString(),
    createdBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: '',
      subjectTemplate: '',
      bodyTemplate: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
      targetFolderPath: '/Shared Drives/Company/',
      renamePattern: '{DocNo}_{Date}',
      folderStructure: '/{Year}/{Month}/'
    }
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Keyword input state
  const [subjectKeyInput, setSubjectKeyInput] = useState('');
  const [bodyKeyInput, setBodyKeyInput] = useState('');

  const isAdmin = role === UserRole.ADMIN;
  // Read only if explicitly passed prop OR if user is not admin
  const isFormReadOnly = readOnly || !isAdmin;

  const INPUT_CLASS = "w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 outline-none transition-all bg-white disabled:bg-slate-50 disabled:text-slate-500";

  // Handlers
  const handleInputChange = (field: string, value: any) => {
    if (isFormReadOnly) return;
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error if exists
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleNestedChange = (section: 'mailConfig' | 'aiConfig' | 'driveConfig', field: string, value: any) => {
    if (isFormReadOnly) return;
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const addKeyword = (type: 'subject' | 'body', value: string) => {
    if (isFormReadOnly || !value.trim()) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];

    if (!currentList.includes(value.trim())) {
      handleNestedChange(section, field, [...currentList, value.trim()]);
    }
    if (type === 'subject') setSubjectKeyInput('');
    else setBodyKeyInput('');
  };

  const removeKeyword = (type: 'subject' | 'body', keyword: string) => {
    if (isFormReadOnly) return;
    const section = 'mailConfig';
    const field = type === 'subject' ? 'subjectKeywords' : 'bodyKeywords';
    const currentList = formData.mailConfig?.[field] || [];
    handleNestedChange(section, field, currentList.filter(k => k !== keyword));
  };

  const validateForm = (checkStatus: AgentStatus) => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = t.errNameReq;
    if (formData.name.length > 120) newErrors.name = t.errNameLen;

    // Workflow validation: STRICT rule for activation
    if (checkStatus === AgentStatus.ACTIVE) {
      if (!formData.workflowId) {
        newErrors.workflowId = t.errWorkflowReq;
      }
      if (!formData.triggerEvent) {
        newErrors.triggerEvent = t.errTriggerReq;
      }
    }

    // Drive validation
    if (formData.driveConfig?.autoSave && !formData.driveConfig.targetFolderPath) {
      newErrors.targetPath = t.errTargetPathReq;
    }

    // Pattern validation (check for illegal chars or unknown variables)
    if (formData.driveConfig?.autoRename && formData.driveConfig.renamePattern) {
        // Simple regex for invalid filename chars (windows style)
        if (/[<>:"/\\|?*]/.test(formData.driveConfig.renamePattern)) {
            newErrors.renamePattern = t.errInvalidPattern;
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (targetStatus?: AgentStatus) => {
    if (isFormReadOnly) return;
    const statusToCheck = targetStatus || formData.status;

    if (!validateForm(statusToCheck)) {
        // Force switch to tab where error might be? Simple alert for now.
        const errorMsg = Object.values(errors)[0] || t.alertFixErrors;

        // Specific error mapping to tabs
        if (errors.workflowId || errors.triggerEvent) setActiveTab('general');
        else if (errors.targetPath || errors.renamePattern) setActiveTab('automation');

        return;
    }

    const updatedAgent = {
      ...formData,
      status: statusToCheck,
      updatedAt: new Date().toISOString()
    };
    onSave(updatedAgent);
  };

  const runTest = () => {
    setTestLoading(true);
    setTestResult(null);
    // Simulate API call
    setTimeout(() => {
        setTestLoading(false);
        setTestResult({
            success: true,
            message: t.msgSuccess,
            details: {
                trigger: "Manual Test",
                input: formData.type === AgentType.MAIL ? "Sample Email Subject: Invoice #1234" : "Sample Context Data",
                actions: [
                    "Filter matched: Yes",
                    "Workflow Triggered: Invoice Processing",
                    formData.driveConfig?.autoSave ? `File Saved to: ${formData.driveConfig.targetFolderPath}` : "File Save: Skipped"
                ]
            }
        });
    }, 1500);
  };

  const getStatusLabel = (status: AgentStatus) => {
      switch (status) {
          case AgentStatus.ACTIVE: return t.active;
          case AgentStatus.INACTIVE: return t.inactive;
          case AgentStatus.DRAFT: return t.draft;
          default: return status;
      }
  };

  // Helper to preview filename
  const getRenamingPreview = (pattern: string) => {
      if (!pattern) return '';
      const today = new Date();
      const yyyy = today.getFullYear().toString();
      const mm = (today.getMonth() + 1).toString().padStart(2, '0');
      const dd = today.getDate().toString().padStart(2, '0');

      return pattern
        .replace(/{DocNo}/g, 'INV-2024-001')
        .replace(/{Date}/g, `${yyyy}-${mm}-${dd}`)
        .replace(/{Customer}/g, 'Acme_Corp')
        .replace(/{AgentName}/g, (formData.name || 'MyAgent').replace(/\s+/g, '_'))
        .replace(/{Year}/g, yyyy)
        .replace(/{Month}/g, mm)
        .replace(/{DocType}/g, 'Invoice');
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-slate-50">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
             <h2 className="text-xl font-bold text-slate-800">
               {initialData 
                 ? (isFormReadOnly ? `${t.viewAgent}: ${formData.name}` : `${t.editAgent}: ${formData.name}`) 
                 : t.createNewAgent}
             </h2>
             <div className="flex items-center gap-2 text-sm text-slate-500 mt-0.5">
                <span className={`w-2 h-2 rounded-full ${
                    formData.status === AgentStatus.ACTIVE ? 'bg-emerald-500' : 
                    formData.status === AgentStatus.INACTIVE ? 'bg-slate-400' : 'bg-amber-400'
                }`}></span>
                {getStatusLabel(formData.status)}
             </div>
          </div>
        </div>

        {/* Only show save actions if NOT read only and IS Admin */}
        {!isFormReadOnly && isAdmin && (
          <div className="flex items-center gap-3">
             <button 
               onClick={() => handleSubmit(AgentStatus.DRAFT)}
               className="px-4 py-2 text-slate-700 bg-white border border-slate-300 rounded-lg hover:bg-slate-50 font-medium transition-colors"
             >
               {t.saveDraft}
             </button>
             <button 
               onClick={() => handleSubmit(AgentStatus.ACTIVE)}
               className="px-4 py-2 flex items-center gap-2 text-white bg-emerald-600 rounded-lg hover:bg-emerald-700 font-medium transition-colors shadow-sm"
               disabled={!!errors.workflowId || !!errors.triggerEvent}
             >
               <CheckCircle2 size={18} />
               {formData.status === AgentStatus.ACTIVE ? t.saveChanges : t.publishEnable}
             </button>
             {formData.status === AgentStatus.ACTIVE && (
                 <button 
                    onClick={() => handleSubmit(AgentStatus.INACTIVE)}
                    className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg"
                    title={t.disableAgent}
                 >
                    <PowerIcon />
                 </button>
             )}
          </div>
        )}
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Tabs */}
        <div className="w-64 bg-slate-50 border-r border-slate-200 p-4 space-y-1">
          {TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${
                activeTab === tab.id 
                  ? 'bg-white text-brand-600 shadow-sm border border-slate-200' 
                  : 'text-slate-600 hover:bg-slate-100'
              }`}
            >
              {tab.icon}
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto p-8">

          {/* GENERAL INFO TAB */}
          {activeTab === 'general' && (
            <div className="max-w-3xl space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2 col-span-2">
                  <label className="block text-sm font-semibold text-slate-700">{t.labelAgentName} <span className="text-red-500">*</span></label>
                  <input
                    type="text"
                    disabled={isFormReadOnly}
                    value={formData.name}
                    onChange={(e) => handleInputChange('name', e.target.value)}
                    className={`${INPUT_CLASS} ${errors.name ? 'border-red-500' : 'border-slate-300'}`}
                    placeholder={t.phAgentName}
                  />
                  {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                </div>

                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">{t.labelAgentType} <span className="text-red-500">*</span></label>
                  <select
                    disabled={isFormReadOnly}
                    value={formData.type}
                    onChange={(e) => handleInputChange('type', e.target.value)}
                    className={INPUT_CLASS}
                  >
                    <option value={AgentType.MAIL}>{t.mailAgent}</option>
                    <option value={AgentType.AI}>{t.aiAgent}</option>
                  </select>
                </div>

                <div className="col-span-2 grid grid-cols-2 gap-6 p-4 bg-blue-50 border border-blue-100 rounded-lg">
                    <div className="col-span-2 text-sm text-blue-800 font-semibold flex items-center gap-2">
                        <Settings2 size={16} /> {t.headerWorkflow}
                    </div>
                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-slate-700">{t.labelWorkflow} <span className="text-red-500">*</span></label>
                      <select
                        disabled={isFormReadOnly}
                        value={formData.workflowId}
                        onChange={(e) => handleInputChange('workflowId', e.target.value)}
                        className={`${INPUT_CLASS} ${errors.workflowId ? 'border-red-500' : 'border-slate-300'}`}
                      >
                        <option value="">{t.phWorkflow}</option>
                        {AVAILABLE_WORKFLOWS.map(wf => (
                          <option key={wf.id} value={wf.id}>{wf.name}</option>
                        ))}
                      </select>
                      {errors.workflowId && <p className="text-red-500 text-xs mt-1">{errors.workflowId}</p>}
                      <p className="text-xs text-slate-500">{t.helpWorkflow}</p>
                    </div>

                    <div className="space-y-2">
                      <label className="block text-sm font-semibold text-slate-700">{t.labelTrigger} <span className="text-red-500">*</span></label>
                      <select
                        disabled={isFormReadOnly}
                        value={formData.triggerEvent}
                        onChange={(e) => handleInputChange('triggerEvent', e.target.value)}
                        className={`${INPUT_CLASS} ${errors.triggerEvent ? 'border-red-500' : 'border-slate-300'}`}
                      >
                         <option value="">{t.phTrigger}</option>
                        {AVAILABLE_TRIGGERS.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                      {errors.triggerEvent && <p className="text-red-500 text-xs mt-1">{errors.triggerEvent}</p>}
                       <p className="text-xs text-slate-500">{t.helpTrigger}</p>
                    </div>
                </div>

                <div className="col-span-2 space-y-2">
                  <label className="block text-sm font-semibold text-slate-700">{t.labelDesc}</label>
                  <textarea
                    disabled={isFormReadOnly}
                    value={formData.description}
                    onChange={(e) => handleInputChange('description', e.target.value)}
                    className={`${INPUT_CLASS} h-24 resize-none`}
                    placeholder={t.phDesc}
                  />
                </div>
              </div>
            </div>
          )}

          {/* CONFIGURATION TAB */}
          {activeTab === 'config' && (
            <div className="max-w-3xl space-y-8 animate-fadeIn">
              {formData.type === AgentType.MAIL ? (
                <>
                  <SectionHeader icon={<Mail size={20} />} title={t.headerEmailScope} />

                  <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                    <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="space-y-2">
                         <label className="text-sm font-medium text-slate-700">{t.labelSender}</label>
                         <select 
                            disabled={isFormReadOnly}
                            value={formData.mailConfig?.senderEmail}
                            onChange={(e) => handleNestedChange('mailConfig', 'senderEmail', e.target.value)}
                            className={INPUT_CLASS}
                         >
                            <option value="">{t.phSender}</option>
                            <option value="notifications@acme.com">notifications@acme.com</option>
                            <option value="support@acme.com">support@acme.com</option>
                            <option value="hr@acme.com">hr@acme.com</option>
                         </select>
                         <p className="text-xs text-slate-500">{t.helpSender}</p>
                      </div>
                      <div className="space-y-2">
                         <label className="text-sm font-medium text-slate-700">{t.labelReceiver}</label>
                         <input 
                            type="email" 
                            disabled={isFormReadOnly}
                            value={formData.mailConfig?.receiverEmail}
                            onChange={(e) => handleNestedChange('mailConfig', 'receiverEmail', e.target.value)}
                            className={INPUT_CLASS}
                            placeholder={t.phReceiver}
                         />
                         <p className="text-xs text-slate-500">{t.helpReceiver}</p>
                      </div>
                    </div>

                    <div className="border-t border-slate-100 bg-slate-50/50 p-6">
                      <div className="flex items-center justify-between mb-4">
                         <div className="flex items-center gap-2">
                            <div className={`p-1.5 rounded-md ${formData.mailConfig?.enableFilter ? 'bg-brand-100 text-brand-600' : 'bg-slate-200 text-slate-500'}`}>
                              <Filter size={18} />
                            </div>
                            <div>
                                <h4 className="text-sm font-semibold text-slate-800">{t.headerAdvancedFilter}</h4>
                                <p className="text-xs text-slate-500">{t.helpAdvancedFilter}</p>
                            </div>
                         </div>
                         <Toggle 
                            enabled={formData.mailConfig?.enableFilter || false} 
                            onChange={(v) => handleNestedChange('mailConfig', 'enableFilter', v)} 
                            disabled={isFormReadOnly}
                         />
                      </div>

                      {formData.mailConfig?.enableFilter && (
                        <div className="space-y-6 pt-2 animate-fadeIn">
                           <KeywordInput 
                              label={t.labelSubjectKeys} 
                              keywords={formData.mailConfig?.subjectKeywords || []} 
                              inputValue={subjectKeyInput}
                              setInputValue={setSubjectKeyInput}
                              onAdd={() => addKeyword('subject', subjectKeyInput)}
                              onRemove={(k) => removeKeyword('subject', k)}
                              disabled={isFormReadOnly}
                              inputClass={INPUT_CLASS}
                              placeholder={t.phKeyword}
                           />
                           <KeywordInput 
                              label={t.labelBodyKeys} 
                              keywords={formData.mailConfig?.bodyKeywords || []} 
                              inputValue={bodyKeyInput}
                              setInputValue={setBodyKeyInput}
                              onAdd={() => addKeyword('body', bodyKeyInput)}
                              onRemove={(k) => removeKeyword('body', k)}
                              disabled={isFormReadOnly}
                              inputClass={INPUT_CLASS}
                              placeholder={t.phKeyword}
                           />
                        </div>
                      )}
                    </div>
                  </div>

                  <SectionHeader icon={<MessageSquare size={20} />} title={t.headerTemplate} />
                  <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm space-y-6">
                      <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">{t.labelSubjTemplate}</label>
                        <input 
                           type="text" 
                           disabled={isFormReadOnly}
                           value={formData.mailConfig?.subjectTemplate}
                           onChange={(e) => handleNestedChange('mailConfig', 'subjectTemplate', e.target.value)}
                           className={INPUT_CLASS}
                           placeholder={t.phSubjTemplate}
                        />
                      </div>
                      <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">{t.labelBodyTemplate}</label>
                        <textarea 
                           disabled={isFormReadOnly}
                           value={formData.mailConfig?.bodyTemplate}
                           onChange={(e) => handleNestedChange('mailConfig', 'bodyTemplate', e.target.value)}
                           className={`${INPUT_CLASS} h-32 font-mono text-sm`}
                           placeholder={t.phBodyTemplate}
                        />
                      </div>
                      <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 text-xs text-slate-600">
                         <span className="font-semibold mb-1 block">{t.labelSupportedVars}</span>
                         <div className="flex flex-wrap gap-2">
                            {ALLOWED_VARIABLES.map(v => (
                                <code key={v} className="bg-white border border-slate-300 px-1 py-0.5 rounded text-brand-600">{v}</code>
                            ))}
                         </div>
                      </div>
                  </div>
                </>
              ) : (
                <>
                  <SectionHeader icon={<Bot size={20} />} title={t.headerAISettings} />
                  <div className="space-y-4 p-4 bg-purple-50 rounded-lg border border-purple-100">
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">{t.labelAIModel}</label>
                        <select 
                           disabled={isFormReadOnly}
                           value={formData.aiConfig?.model}
                           onChange={(e) => handleNestedChange('aiConfig', 'model', e.target.value)}
                           className={INPUT_CLASS}
                        >
                           <option value="gemini-pro">Gemini Pro</option>
                           <option value="gpt-4">GPT-4</option>
                           <option value="claude-3">Claude 3</option>
                        </select>
                     </div>
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">{t.labelInputContext}</label>
                        <textarea 
                           disabled={isFormReadOnly}
                           value={formData.aiConfig?.inputSource}
                           onChange={(e) => handleNestedChange('aiConfig', 'inputSource', e.target.value)}
                           className={`${INPUT_CLASS} h-24`}
                           placeholder={t.phInputContext}
                        />
                        <p className="text-xs text-slate-500">{t.helpInputContext}</p>
                     </div>
                     <div className="space-y-2">
                        <label className="text-sm font-medium text-slate-700">{t.labelOutputAction}</label>
                        <textarea 
                           disabled={isFormReadOnly}
                           value={formData.aiConfig?.outputAction}
                           onChange={(e) => handleNestedChange('aiConfig', 'outputAction', e.target.value)}
                           className={`${INPUT_CLASS} h-24`}
                           placeholder={t.phOutputAction}
                        />
                        <p className="text-xs text-slate-500">{t.helpOutputAction}</p>
                     </div>
                  </div>
                </>
              )}
            </div>
          )}

          {/* AUTOMATION TAB */}
          {activeTab === 'automation' && (
             <div className="max-w-3xl space-y-8 animate-fadeIn">

                {/* Auto Save */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Save size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">{t.headerAutoSave}</h3>
                            <p className="text-xs text-slate-500">{t.descAutoSave}</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoSave || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoSave', v)} 
                        disabled={isFormReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoSave && (
                      <div className="ml-12 space-y-2">
                         <label className="text-sm font-medium text-slate-700">{t.labelTargetPath} <span className="text-red-500">*</span></label>
                         <div className="flex gap-2">
                            <input 
                              type="text" 
                              disabled={isFormReadOnly}
                              value={formData.driveConfig?.targetFolderPath}
                              onChange={(e) => handleNestedChange('driveConfig', 'targetFolderPath', e.target.value)}
                              className={`flex-1 ${INPUT_CLASS} ${errors.targetPath ? 'border-red-500' : ''}`}
                              placeholder="/My Drive/Agent_Output/"
                            />
                            <button className="px-3 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200" title={t.btnCheckPerms}>
                               <CheckCircle2 size={18} />
                            </button>
                         </div>
                         {errors.targetPath && <p className="text-red-500 text-xs">{errors.targetPath}</p>}
                      </div>
                   )}
                </div>

                {/* Auto Rename */}
                <div className="border border-slate-200 rounded-xl p-6 bg-white shadow-sm">
                   <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center gap-3">
                         <div className="p-2 bg-amber-100 text-amber-600 rounded-lg"><FileCode size={20}/></div>
                         <div>
                            <h3 className="font-semibold text-slate-800">{t.headerAutoRename}</h3>
                            <p className="text-xs text-slate-500">{t.descAutoRename}</p>
                         </div>
                      </div>
                      <Toggle 
                        enabled={formData.driveConfig?.autoRename || false} 
                        onChange={(v) => handleNestedChange('driveConfig', 'autoRename', v)} 
                        disabled={isFormReadOnly}
                      />
                   </div>

                   {formData.driveConfig?.autoRename && (
                      <div className="ml-12 space-y-3">
                         <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-700">{t.labelRenamePattern}</label>
                            <input 
                               type="text" 
                               disabled={isFormReadOnly}
                               value={formData.driveConfig?.renamePattern}
                               onChange={(e) => handleNestedChange('driveConfig', 'renamePattern', e.target.value)}
                               className={INPUT_CLASS}
                               placeholder="{DocNo}_{Customer}_{Date}"
                            />
                            {formData.driveConfig?.renamePattern && (
                                <div className="mt-2 p-3 bg-slate-100 rounded-lg border border-slate-200 text-sm">
                                    <span className="font-semibold text-slate-500 mr-2">{t.labelPreview}:</span>
                                    <span className="font-mono text-slate-800 break-all">{getRenamingPreview(formData.driveConfig.renamePattern)}</span>
                                </div>
                            )}
