                   <span className="text-[10px] text-slate-500 uppercase">{currentUserRole}</span>
                </div>
                <Avatar style={{ backgroundColor: '#fde3cf', color: '#f56a00' }}>K</Avatar>
                <i className="fa-solid fa-chevron-down text-xs text-slate-400" />
              </Space>
            </Dropdown>
          </div>
        </Header>

        <Content className="p-6 overflow-y-auto bg-slate-50">
          {children}
        </Content>
      </AntLayout>
    </AntLayout>
  );
};

import React, { useState } from 'react';
import { Table, Button, Input, Select, Tag, Tooltip, Space, Card, Row, Col, Typography, Modal } from 'antd';
import { Agent, AgentStatus, AgentType, UserRole, Language } from '../types';
import { TRANSLATIONS } from '../translations';

const { Title, Text } = Typography;
const { Search } = Input;
const { Option } = Select;

interface AgentListProps {
  agents: Agent[];
  role: UserRole;
  language: Language;
  onEdit: (agent: Agent) => void;
  onView: (agent: Agent) => void;
  onCreate: () => void;
  onToggleStatus: (agent: Agent) => void;
  onDelete: (agent: Agent) => void;
}

export const AgentList: React.FC<AgentListProps> = ({ agents, role, language, onEdit, onView, onCreate, onToggleStatus, onDelete }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('ALL');
  const [typeFilter, setTypeFilter] = useState<string>('ALL');
  const t = TRANSLATIONS[language];

  // Data Filtering
  const filteredAgents = agents.filter(agent => {
    const matchesSearch = agent.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'ALL' || agent.status === statusFilter;
    const matchesType = typeFilter === 'ALL' || agent.type === typeFilter;
    return matchesSearch && matchesStatus && matchesType;
  });

  // Table Columns Definition
  const columns = [
    {
      title: t.agentName,
      dataIndex: 'name',
      key: 'name',
      render: (text: string, record: Agent) => (
        <div className="flex flex-col">
          <Text strong className="text-base text-slate-800">{text}</Text>
          <Text type="secondary" className="text-xs truncate max-w-[250px]">{record.description || '-'}</Text>
        </div>
      ),
    },
    {
      title: t.type,
      dataIndex: 'type',
      key: 'type',
      render: (type: AgentType) => (
        <Tag color={type === AgentType.AI ? 'purple' : 'blue'}>
          {type === AgentType.AI ? <><i className="fa-solid fa-robot mr-1" /> {t.aiAgent}</> : <><i className="fa-solid fa-envelope mr-1" /> {t.mailAgent}</>}
        </Tag>
      ),
    },
    {
      title: t.status,
      dataIndex: 'status',
      key: 'status',
      render: (status: AgentStatus) => {
        let color = 'default';
        if (status === AgentStatus.ACTIVE) color = 'success';
        if (status === AgentStatus.INACTIVE) color = 'error';
        if (status === AgentStatus.DRAFT) color = 'warning';

        let label = status;
        if (status === AgentStatus.ACTIVE) label = t.active;
        if (status === AgentStatus.INACTIVE) label = t.inactive;
        if (status === AgentStatus.DRAFT) label = t.draft;

        return <Tag color={color}>{label}</Tag>;
      },
    },
    {
      title: t.createdBy,
      dataIndex: 'createdBy',
      key: 'createdBy',
      render: (text: string, record: Agent) => (
         <div className="flex flex-col">
            <Text strong>{text || '-'}</Text>
            {record.createdAt && <Text type="secondary" className="text-xs">{new Date(record.createdAt).toLocaleDateString()}</Text>}
         </div>
      ),
    },
    {
      title: t.lastUpdated,
      key: 'updatedAt',
      render: (_: any, record: Agent) => (
        <div className="flex flex-col">
          <Text>{new Date(record.updatedAt).toLocaleDateString()}</Text>
          <Text type="secondary" className="text-xs">{t.by} {record.updatedBy}</Text>
        </div>
      ),
    },
    {
      title: t.actions,
      key: 'actions',
      align: 'right' as const,
      render: (_: any, record: Agent) => (
        <Space size="small">
          <Tooltip title={t.viewDetails}>
             <Button icon={<i className="fa-solid fa-eye" />} onClick={() => onView(record)} />
          </Tooltip>

          {role === UserRole.ADMIN && (
            <>
              <Tooltip title={t.editConfig}>
                <Button type="primary" ghost icon={<i className="fa-solid fa-pen" />} onClick={() => onEdit(record)} />
              </Tooltip>
              <Tooltip title={record.status === AgentStatus.ACTIVE ? t.disableAgent : t.enableAgent}>
                <Button 
                   type={record.status === AgentStatus.ACTIVE ? 'default' : 'dashed'}
                   danger={record.status === AgentStatus.ACTIVE}
                   className={record.status !== AgentStatus.ACTIVE ? 'text-emerald-600 border-emerald-600 hover:!text-emerald-500 hover:!border-emerald-500' : ''}
                   icon={<i className="fa-solid fa-power-off" />} 
                   onClick={() => onToggleStatus(record)} 
                />
              </Tooltip>
              <Tooltip title={t.deleteAgent}>
                <Button danger icon={<i className="fa-solid fa-trash" />} onClick={() => onDelete(record)} />
              </Tooltip>
            </>
          )}
        </Space>
      ),
    },
  ];

  return (
    <div className="space-y-6">
      <Row justify="space-between" align="middle" gutter={[16, 16]}>
        <Col>
          <Title level={3} style={{ margin: 0 }}>{t.agentManagement}</Title>
          <Text type="secondary">{t.manageAgents}</Text>
        </Col>
        <Col>
          {role === UserRole.ADMIN && (
            <Button 
               type="primary" 
               icon={<i className="fa-solid fa-plus" />} 
               size="large"
               onClick={onCreate}
            >
              {t.createAgent}
            </Button>
          )}
        </Col>
      </Row>

      <Card bordered={false} className="shadow-sm rounded-xl">
        <Row gutter={[16, 16]} className="mb-6">
           <Col xs={24} md={12} lg={14}>
             <Input 
                prefix={<i className="fa-solid fa-magnifying-glass text-slate-400" />}
                placeholder={t.searchPlaceholder}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                size="large"
                allowClear
             />
           </Col>
           <Col xs={24} md={6} lg={5}>
              <Select 
                 value={statusFilter} 
                 onChange={setStatusFilter} 
                 style={{ width: '100%' }} 
                 size="large"
                 suffixIcon={<i className="fa-solid fa-filter" />}
              >
                  <Option value="ALL">{t.allStatus}</Option>
                  <Option value={AgentStatus.ACTIVE}>{t.active}</Option>
                  <Option value={AgentStatus.INACTIVE}>{t.inactive}</Option>
                  <Option value={AgentStatus.DRAFT}>{t.draft}</Option>
              </Select>
           </Col>
           <Col xs={24} md={6} lg={5}>
              <Select 
                 value={typeFilter} 
                 onChange={setTypeFilter} 
                 style={{ width: '100%' }} 
                 size="large"
                 suffixIcon={<i className="fa-solid fa-filter" />}
              >
                  <Option value="ALL">{t.allTypes}</Option>
                  <Option value={AgentType.MAIL}>{t.mailAgent}</Option>
                  <Option value={AgentType.AI}>{t.aiAgent}</Option>
              </Select>
           </Col>
        </Row>

        <Table 
           columns={columns} 
           dataSource={filteredAgents} 
           rowKey="id"
           pagination={{ 
             pageSize: 5, 
             showTotal: (total, range) => `${t.showing} ${range[0]}-${range[1]} ${t.of} ${total} ${t.items}`,
             position: ['bottomRight']
           }}
        />
      </Card>
    </div>
  );
};

import React, { useState } from 'react';
import { 
    Button, Input, Select, Switch, Tabs, Card, Form, Alert, 
    Row, Col, Typography, Space, Divider, Tag 
} from 'antd';
import { 
  Agent, AgentStatus, AgentType, UserRole, Language,
  AVAILABLE_WORKFLOWS, AVAILABLE_TRIGGERS, ALLOWED_VARIABLES, AuditLog 
} from '../types';
import { TRANSLATIONS } from '../translations';

const { Title, Text, Paragraph } = Typography;
const { TextArea } = Input;
const { Option } = Select;

interface AgentFormProps {
  initialData?: Agent;
  role: UserRole;
  language: Language;
  onSave: (agent: Agent) => void;
  onBack: () => void;
  auditLogs: AuditLog[];
  readOnly?: boolean;
}

export const AgentForm: React.FC<AgentFormProps> = ({ initialData, role, language, onSave, onBack, auditLogs, readOnly = false }) => {
  const [testResult, setTestResult] = useState<any>(null);
  const [testLoading, setTestLoading] = useState(false);
  const t = TRANSLATIONS[language];

  // Form State Management (Keeping simplified custom state for specific nested logic)
  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, // Default
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    createdAt: new Date().toISOString(),
    createdBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: '',
      subjectTemplate: '',
      bodyTemplate: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
      targetFolderPath: '/Shared Drives/Company/',
      renamePattern: '{DocNo}_{Date}',
      folderStructure: '/{Year}/{Month}/'
    }
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [activeTabKey, setActiveTabKey] = useState('general');

  // Input States for Keywords (AntD Select mode="tags" handles this better, but adapting existing logic)
  const isAdmin = role === UserRole.ADMIN;
  const isFormReadOnly = readOnly || !isAdmin;

  // -- Handlers --

  const handleInputChange = (field: string, value: any) => {
    if (isFormReadOnly) return;
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleNestedChange = (section: 'mailConfig' | 'aiConfig' | 'driveConfig', field: string, value: any) => {
    if (isFormReadOnly) return;
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const validateForm = (checkStatus: AgentStatus) => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = t.errNameReq;
    if (formData.name.length > 120) newErrors.name = t.errNameLen;

    if (checkStatus === AgentStatus.ACTIVE) {
      if (!formData.workflowId) newErrors.workflowId = t.errWorkflowReq;
      if (!formData.triggerEvent) newErrors.triggerEvent = t.errTriggerReq;
    }

    if (formData.driveConfig?.autoSave && !formData.driveConfig.targetFolderPath) {
      newErrors.targetPath = t.errTargetPathReq;
    }

    if (formData.driveConfig?.autoRename && formData.driveConfig.renamePattern) {
        if (/[<>:"/\\|?*]/.test(formData.driveConfig.renamePattern)) {
            newErrors.renamePattern = t.errInvalidPattern;
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (targetStatus?: AgentStatus) => {
    if (isFormReadOnly) return;
    const statusToCheck = targetStatus || formData.status;

    if (!validateForm(statusToCheck)) {
        if (errors.workflowId || errors.triggerEvent) setActiveTabKey('general');
        else if (errors.targetPath || errors.renamePattern) setActiveTabKey('automation');
        return;
    }

    const updatedAgent = {
      ...formData,
      status: statusToCheck,
      updatedAt: new Date().toISOString()
    };
    onSave(updatedAgent);
  };

  const runTest = () => {
    setTestLoading(true);
    setTestResult(null);
    setTimeout(() => {
        setTestLoading(false);
        setTestResult({
            success: true,
            message: t.msgSuccess,
            details: {
                trigger: "Manual Test",
                input: formData.type === AgentType.MAIL ? "Sample Email Subject: Invoice #1234" : "Sample Context Data",
                actions: [
                    "Filter matched: Yes",
                    "Workflow Triggered: Invoice Processing",
                    formData.driveConfig?.autoSave ? `File Saved to: ${formData.driveConfig.targetFolderPath}` : "File Save: Skipped"
                ]
            }
        });
    }, 1500);
  };

  const getRenamingPreview = (pattern: string) => {
      if (!pattern) return '';
      const today = new Date();
      return pattern
        .replace(/{DocNo}/g, 'INV-2024-001')
        .replace(/{Date}/g, today.toISOString().split('T')[0])
        .replace(/{Customer}/g, 'Acme_Corp')
        .replace(/{AgentName}/g, (formData.name || 'MyAgent').replace(/\s+/g, '_'))
        .replace(/{Year}/g, today.getFullYear().toString())
        .replace(/{Month}/g, (today.getMonth() + 1).toString().padStart(2, '0'))
        .replace(/{DocType}/g, 'Invoice');
  };

  // --- Render Sections ---

  const renderGeneralTab = () => (
      <Row gutter={[24, 24]}>
          <Col span={24}>
              <Text strong>{t.labelAgentName} <span className="text-red-500">*</span></Text>
              <Input 
                 size="large" 
                 value={formData.name} 
                 onChange={e => handleInputChange('name', e.target.value)} 
                 status={errors.name ? 'error' : ''}
                 placeholder={t.phAgentName}
                 disabled={isFormReadOnly}
              />
              {errors.name && <Text type="danger" className="text-xs">{errors.name}</Text>}
          </Col>
          <Col span={12}>
              <Text strong>{t.labelAgentType} <span className="text-red-500">*</span></Text>
              <Select 
                 size="large" 
                 className="w-full block mt-1"
                 value={formData.type} 
                 onChange={v => handleInputChange('type', v)}
                 disabled={isFormReadOnly}
              >
                  <Option value={AgentType.MAIL}>{t.mailAgent}</Option>
                  <Option value={AgentType.AI}>{t.aiAgent}</Option>
              </Select>
          </Col>
          <Col span={24}>
             <Card size="small" className="bg-blue-50 border-blue-100" title={<span className="text-blue-800"><i className="fa-solid fa-gears mr-2"/>{t.headerWorkflow}</span>}>
                <Row gutter={[24, 24]}>
                    <Col span={12}>
                        <Text strong>{t.labelWorkflow} <span className="text-red-500">*</span></Text>
                        <Select 
                            size="large"
                            className="w-full block mt-1"
                            value={formData.workflowId}
                            onChange={v => handleInputChange('workflowId', v)}
                            status={errors.workflowId ? 'error' : ''}
                            disabled={isFormReadOnly}
                            placeholder={t.phWorkflow}
                        >
                            {AVAILABLE_WORKFLOWS.map(wf => <Option key={wf.id} value={wf.id}>{wf.name}</Option>)}
                        </Select>
                        {errors.workflowId && <Text type="danger" className="text-xs">{errors.workflowId}</Text>}
                        <Text type="secondary" className="text-xs block mt-1">{t.helpWorkflow}</Text>
                    </Col>
                    <Col span={12}>
                        <Text strong>{t.labelTrigger} <span className="text-red-500">*</span></Text>
                        <Select
                            size="large"
                            className="w-full block mt-1"
                            value={formData.triggerEvent}
                            onChange={v => handleInputChange('triggerEvent', v)}
                            status={errors.triggerEvent ? 'error' : ''}
                            disabled={isFormReadOnly}
                            placeholder={t.phTrigger}
                        >
                             {AVAILABLE_TRIGGERS.map(tr => <Option key={tr} value={tr}>{tr}</Option>)}
                        </Select>
                        {errors.triggerEvent && <Text type="danger" className="text-xs">{errors.triggerEvent}</Text>}
                        <Text type="secondary" className="text-xs block mt-1">{t.helpTrigger}</Text>
                    </Col>
                </Row>
             </Card>
          </Col>
          <Col span={24}>
              <Text strong>{t.labelDesc}</Text>
              <TextArea 
                  rows={4} 
                  value={formData.description} 
                  onChange={e => handleInputChange('description', e.target.value)}
                  disabled={isFormReadOnly}
                  placeholder={t.phDesc}
                  className="mt-1"
              />
          </Col>
      </Row>
  );

  const renderConfigTab = () => (
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
          {formData.type === AgentType.MAIL ? (
              <>
                 <Divider orientation="left"><i className="fa-solid fa-envelope mr-2 text-brand-500" /> {t.headerEmailScope}</Divider>
                 <Card bordered={false} className="shadow-sm border border-slate-200">
                    <Row gutter={[24, 24]}>
                        <Col span={12}>
                            <Text strong>{t.labelSender}</Text>
                            <Select 
                                size="large" className="w-full mt-1"
                                value={formData.mailConfig?.senderEmail}
                                onChange={v => handleNestedChange('mailConfig', 'senderEmail', v)}
                                disabled={isFormReadOnly}
                            >
                                <Option value="">{t.phSender}</Option>
                                <Option value="notifications@acme.com">notifications@acme.com</Option>
                                <Option value="support@acme.com">support@acme.com</Option>
                            </Select>
                        </Col>
                        <Col span={12}>
                            <Text strong>{t.labelReceiver}</Text>
                            <Input 
                                size="large" className="mt-1"
                                value={formData.mailConfig?.receiverEmail}
                                onChange={e => handleNestedChange('mailConfig', 'receiverEmail', e.target.value)}
                                disabled={isFormReadOnly}
                                placeholder={t.phReceiver}
                            />
                        </Col>
                    </Row>

                    <Divider />

                    <div className="flex justify-between items-center mb-4">
                        <Space>
                            <div className="p-2 bg-slate-100 rounded text-slate-500"><i className="fa-solid fa-filter"/></div>
                            <div>
                                <Text strong>{t.headerAdvancedFilter}</Text>
                                <div className="text-xs text-slate-400">{t.helpAdvancedFilter}</div>
                            </div>
                        </Space>
                        <Switch 
                            checked={formData.mailConfig?.enableFilter}
                            onChange={v => handleNestedChange('mailConfig', 'enableFilter', v)}
                            disabled={isFormReadOnly}
                        />
                    </div>

                    {formData.mailConfig?.enableFilter && (
                        <Row gutter={[24, 24]}>
                            <Col span={24}>
                                <Text strong>{t.labelSubjectKeys}</Text>
                                <Select
                                    mode="tags"
                                    size="large"
                                    className="w-full mt-1"
                                    placeholder={t.phKeyword}
                                    value={formData.mailConfig?.subjectKeywords}
                                    onChange={v => handleNestedChange('mailConfig', 'subjectKeywords', v)}
                                    disabled={isFormReadOnly}
                                />
                            </Col>
                            <Col span={24}>
                                <Text strong>{t.labelBodyKeys}</Text>
                                <Select
                                    mode="tags"
                                    size="large"
                                    className="w-full mt-1"
                                    placeholder={t.phKeyword}
                                    value={formData.mailConfig?.bodyKeywords}
                                    onChange={v => handleNestedChange('mailConfig', 'bodyKeywords', v)}
                                    disabled={isFormReadOnly}
                                />
                            </Col>
                        </Row>
                    )}
                 </Card>

                 <Divider orientation="left"><i className="fa-solid fa-message mr-2 text-brand-500" /> {t.headerTemplate}</Divider>
                 <Card bordered={false} className="shadow-sm border border-slate-200">
                     <Space direction="vertical" style={{width: '100%'}} size="middle">
                         <div>
                             <Text strong>{t.labelSubjTemplate}</Text>
                             <Input 
                                size="large" className="mt-1"
                                value={formData.mailConfig?.subjectTemplate}
                                onChange={e => handleNestedChange('mailConfig', 'subjectTemplate', e.target.value)}
                                disabled={isFormReadOnly}
                                placeholder={t.phSubjTemplate}
                             />
                         </div>
                         <div>
                             <Text strong>{t.labelBodyTemplate}</Text>
                             <TextArea 
                                rows={6} className="mt-1 font-mono"
                                value={formData.mailConfig?.bodyTemplate}
                                onChange={e => handleNestedChange('mailConfig', 'bodyTemplate', e.target.value)}
                                disabled={isFormReadOnly}
                                placeholder={t.phBodyTemplate}
                             />
                         </div>
                         <Alert 
                            message={t.labelSupportedVars} 
                            description={
                                <Space wrap>
                                    {ALLOWED_VARIABLES.map(v => <Tag key={v}>{v}</Tag>)}
                                </Space>
                            }
                            type="info"
                            showIcon
                         />
                     </Space>
                 </Card>
              </>
          ) : (
              <>
                <Divider orientation="left"><i className="fa-solid fa-robot mr-2 text-brand-500" /> {t.headerAISettings}</Divider>
                <Card className="bg-purple-50 border-purple-100">
                    <Space direction="vertical" style={{ width: '100%' }} size="middle">
                        <div>
                            <Text strong>{t.labelAIModel}</Text>
                            <Select 
                                size="large" className="w-full mt-1"
                                value={formData.aiConfig?.model}
                                onChange={v => handleNestedChange('aiConfig', 'model', v)}
                                disabled={isFormReadOnly}
                            >
                                <Option value="gemini-pro">Gemini Pro</Option>
                                <Option value="gpt-4">GPT-4</Option>
                                <Option value="claude-3">Claude 3</Option>
                            </Select>
                        </div>
                        <div>
                            <Text strong>{t.labelInputContext}</Text>
                            <TextArea 
                                rows={4} className="mt-1"
                                value={formData.aiConfig?.inputSource}
                                onChange={e => handleNestedChange('aiConfig', 'inputSource', e.target.value)}
                                disabled={isFormReadOnly}
                                placeholder={t.phInputContext}
                            />
                        </div>
                        <div>
                            <Text strong>{t.labelOutputAction}</Text>
                            <TextArea 
                                rows={4} className="mt-1"
                                value={formData.aiConfig?.outputAction}
                                onChange={e => handleNestedChange('aiConfig', 'outputAction', e.target.value)}
                                disabled={isFormReadOnly}
                                placeholder={t.phOutputAction}
                            />
                        </div>
                    </Space>
                </Card>
              </>
          )}
      </Space>
  );

  const renderAutomationTab = () => (
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
          {/* Auto Save */}
          <Card bordered={false} className="shadow-sm border border-slate-200">
              <Row justify="space-between" align="middle" className="mb-4">
                  <Col>
                      <Space>
                          <div className="p-2 bg-blue-100 text-blue-600 rounded"><i className="fa-solid fa-floppy-disk"/></div>
                          <div>
                              <Text strong className="block">{t.headerAutoSave}</Text>
                              <Text type="secondary" className="text-xs">{t.descAutoSave}</Text>
                          </div>
                      </Space>
                  </Col>
                  <Col>
                      <Switch 
                          checked={formData.driveConfig?.autoSave} 
                          onChange={v => handleNestedChange('driveConfig', 'autoSave', v)}
                          disabled={isFormReadOnly}
                      />
                  </Col>
              </Row>
              {formData.driveConfig?.autoSave && (
                  <div className="pl-12">
                      <Text strong>{t.labelTargetPath} <span className="text-red-500">*</span></Text>
                      <Space.Compact style={{ width: '100%', marginTop: 4 }}>
                          <Input 
                              value={formData.driveConfig?.targetFolderPath}
                              onChange={e => handleNestedChange('driveConfig', 'targetFolderPath', e.target.value)}
                              status={errors.targetPath ? 'error' : ''}
                              disabled={isFormReadOnly}
                              placeholder="/My Drive/Agent_Output/"
                          />
                          <Button icon={<i className="fa-solid fa-circle-check" />} />
                      </Space.Compact>
                      {errors.targetPath && <Text type="danger" className="text-xs">{errors.targetPath}</Text>}
                  </div>
              )}
          </Card>

          {/* Auto Rename */}
          <Card bordered={false} className="shadow-sm border border-slate-200">
              <Row justify="space-between" align="middle" className="mb-4">
                  <Col>
                      <Space>
                          <div className="p-2 bg-amber-100 text-amber-600 rounded"><i className="fa-solid fa-file-code"/></div>
                          <div>
                              <Text strong className="block">{t.headerAutoRename}</Text>
                              <Text type="secondary" className="text-xs">{t.descAutoRename}</Text>
                          </div>
                      </Space>
                  </Col>
                  <Col>
                      <Switch 
                          checked={formData.driveConfig?.autoRename} 
                          onChange={v => handleNestedChange('driveConfig', 'autoRename', v)}
                          disabled={isFormReadOnly}
                      />
                  </Col>
              </Row>
              {formData.driveConfig?.autoRename && (
                  <div className="pl-12">
                      <Text strong>{t.labelRenamePattern}</Text>
                      <Input 
                          className="mt-1"
                          value={formData.driveConfig?.renamePattern}
                          onChange={e => handleNestedChange('driveConfig', 'renamePattern', e.target.value)}
                          status={errors.renamePattern ? 'error' : ''}
                          disabled={isFormReadOnly}
                          placeholder="{DocNo}_{Customer}_{Date}"
                      />
                      {formData.driveConfig?.renamePattern && (
                          <Alert 
                             message={`${t.labelPreview}: ${getRenamingPreview(formData.driveConfig.renamePattern)}`} 
                             type="success" 
                             showIcon 
                             className="mt-2"
                             style={{ padding: '4px 12px' }}
                          />
                      )}
                      <Text type="secondary" className="text-xs mt-2 block">
                         Vars: {ALLOWED_VARIABLES.map(v => <Tag key={v} className="mr-1">{v}</Tag>)}
                      </Text>
                  </div>
              )}
          </Card>

          {/* Auto Folder */}
          <Card bordered={false} className="shadow-sm border border-slate-200">
              <Row justify="space-between" align="middle" className="mb-4">
                  <Col>
                      <Space>
                          <div className="p-2 bg-emerald-100 text-emerald-600 rounded"><i className="fa-solid fa-folder-open"/></div>
                          <div>
                              <Text strong className="block">{t.headerAutoFolder}</Text>
                              <Text type="secondary" className="text-xs">{t.descAutoFolder}</Text>
                          </div>
                      </Space>
                  </Col>
                  <Col>
                      <Switch 
                          checked={formData.driveConfig?.autoCreateFolder} 
                          onChange={v => handleNestedChange('driveConfig', 'autoCreateFolder', v)}
                          disabled={isFormReadOnly}
                      />
                  </Col>
              </Row>
              {formData.driveConfig?.autoCreateFolder && (
                  <div className="pl-12">
                      <Text strong>{t.labelFolderRule}</Text>
                      <Input 
                          className="mt-1"
                          value={formData.driveConfig?.folderStructure}
                          onChange={e => handleNestedChange('driveConfig', 'folderStructure', e.target.value)}
                          disabled={isFormReadOnly}
                          placeholder="/{Year}/{Month}/{Customer}/"
                      />
                      <Text type="secondary" className="text-xs">{t.helpFolderRule}</Text>
                  </div>
              )}
          </Card>
      </Space>
  );

  const renderHistoryTab = () => (
      <div className="mt-4">
          <Title level={4}>{t.headerAudit}</Title>
          <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
             <table className="w-full text-sm text-left">
                <thead className="bg-slate-50 border-b border-slate-200 text-slate-600">
                   <tr>
                      <th className="p-4">{t.thTime}</th>
                      <th className="p-4">{t.thUser}</th>
                      <th className="p-4">{t.thAction}</th>
                      <th className="p-4">{t.thDetails}</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                   {auditLogs.map(log => (
                      <tr key={log.id}>
                         <td className="p-4 text-slate-500">{new Date(log.timestamp).toLocaleString()}</td>
                         <td className="p-4 font-medium text-slate-700">{log.user}</td>
                         <td className="p-4"><Tag>{log.action}</Tag></td>
                         <td className="p-4 text-slate-600">{log.details}</td>
                      </tr>
                   ))}
                   {auditLogs.length === 0 && (
                       <tr><td colSpan={4} className="p-8 text-center text-slate-400">{t.noHistory}</td></tr>
                   )}
                </tbody>
             </table>
          </div>
      </div>
  );

  const renderTestTab = () => (
      <Card className="bg-slate-900 border-slate-800 text-slate-300">
          <div className="flex justify-between items-center mb-4">
              <Title level={4} style={{ color: 'white', margin: 0 }}><i className="fa-solid fa-flask mr-2"/> {t.headerTestSim}</Title>
              {role === UserRole.ADMIN && !isFormReadOnly ? (
                  <Button 
                      type="primary" 
                      loading={testLoading} 
                      onClick={runTest}
                      icon={!testLoading && <i className="fa-solid fa-play" />}
                  >
                      {t.btnRunTest}
                  </Button>
              ) : (
                  <Tag color="warning">{isFormReadOnly ? t.viewAgent : t.msgAdminReq}</Tag>
              )}
          </div>

          <div className="font-mono text-sm bg-black/50 p-4 rounded-lg min-h-[300px] overflow-auto">
              <div className="mb-2 text-brand-400">$ {t.logInit}</div>
              <div className="mb-2 text-brand-400">$ {t.logLoadConfig} "{formData.name}"...</div>

              {testLoading && (
                  <div className="animate-pulse text-slate-500 mt-4">
                      &gt; {t.logProcess}<br/>
                      &gt; {t.logFilter}<br/>
                      &gt; {t.logDrive}
                  </div>
              )}

              {testResult && (
                  <div className="mt-4 space-y-2">
                      <div className="text-emerald-400 font-bold">✓ {testResult.message}</div>
                      <div className="text-slate-400">----------------------------------------</div>
                      {Object.entries(testResult.details).map(([key, val]: any) => (
                          <div key={key}>
                              <span className="text-purple-400">{key}: </span>
                              <span className="text-slate-200">
                                  {Array.isArray(val) ? val.map(v => <div className="pl-4 text-xs text-slate-400" key={v}>- {v}</div>) : val}
                              </span>
                          </div>
                      ))}
                      <div className="text-slate-400">----------------------------------------</div>
                      <div className="text-xs text-slate-500 mt-4">{t.msgSandbox}</div>
                  </div>
              )}

              {!testLoading && !testResult && (
                  <div className="mt-8 text-center text-slate-600 italic">
                      {t.msgReady}
                  </div>
              )}
          </div>
      </Card>
  );

  const tabItems = [
    { key: 'general', label: <span><i className="fa-solid fa-gear mr-2"/> {t.tabGeneral}</span>, children: renderGeneralTab() },
    { key: 'config', label: <span><i className="fa-solid fa-file-code mr-2"/> {t.tabConfig}</span>, children: renderConfigTab() },
    { key: 'automation', label: <span><i className="fa-solid fa-folder-open mr-2"/> {t.tabAutomation}</span>, children: renderAutomationTab() },
    { key: 'test', label: <span><i className="fa-solid fa-flask mr-2"/> {t.tabTest}</span>, children: renderTestTab() },
    { key: 'history', label: <span><i className="fa-solid fa-clock-rotate-left mr-2"/> {t.tabHistory}</span>, children: renderHistoryTab() },
  ];

  return (
    <Card className="h-full flex flex-col shadow-sm rounded-xl overflow-hidden border border-slate-200" bodyStyle={{ padding: 0, height: '100%', display: 'flex', flexDirection: 'column' }}>
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
             <Space>
                 <Button shape="circle" icon={<i className="fa-solid fa-arrow-left"/>} onClick={onBack} />
                 <div>
                     <Title level={4} style={{ margin: 0 }}>
                         {initialData 
                           ? (isFormReadOnly ? `${t.viewAgent}: ${formData.name}` : `${t.editAgent}: ${formData.name}`) 
                           : t.createNewAgent}
                     </Title>
                     <Space size={4}>
                        <Tag color={formData.status === AgentStatus.ACTIVE ? 'success' : formData.status === AgentStatus.INACTIVE ? 'default' : 'warning'}>
                            {formData.status}
                        </Tag>
                     </Space>
                 </div>
             </Space>

             {!isFormReadOnly && isAdmin && (
                 <Space>
                     <Button onClick={() => handleSubmit(AgentStatus.DRAFT)}>{t.saveDraft}</Button>
                     <Button 
                        type="primary" 
                        icon={<i className="fa-solid fa-check"/>}
                        onClick={() => handleSubmit(AgentStatus.ACTIVE)}
                        disabled={!!errors.workflowId || !!errors.triggerEvent}
                     >
                        {formData.status === AgentStatus.ACTIVE ? t.saveChanges : t.publishEnable}
                     </Button>
                     {formData.status === AgentStatus.ACTIVE && (
                         <Button danger icon={<i className="fa-solid fa-power-off"/>} onClick={() => handleSubmit(AgentStatus.INACTIVE)} />
                     )}
                 </Space>
             )}
        </div>

        {/* Tabs & Content */}
        <div className="flex-1 overflow-hidden flex">
            <Tabs 
               activeKey={activeTabKey}
               onChange={setActiveTabKey}
               tabPosition="left"
               items={tabItems}
               style={{ height: '100%', width: '100%' }}
               tabBarStyle={{ width: 220, paddingTop: 16, background: '#f8fafc', borderRight: '1px solid #e2e8f0' }}
               className="custom-tabs"
            />
        </div>

        {/* Inject custom styles for tab scrolling override */}
        <style>{`
           .custom-tabs .ant-tabs-content { height: 100%; overflow-y: auto; }
           .custom-tabs .ant-tabs-tabpane { padding: 24px; }
        `}</style>
    </Card>
  );
};

