function App() {
  const [currentView, setCurrentView] = useState<'LIST' | 'FORM'>('LIST');
  const [formMode, setFormMode] = useState<'CREATE' | 'EDIT' | 'VIEW'>('CREATE');
  const [agents, setAgents] = useState<Agent[]>(MOCK_AGENTS);
  const [selectedAgent, setSelectedAgent] = useState<Agent | undefined>(undefined);
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [logs, setLogs] = useState<AuditLog[]>(MOCK_LOGS);
  const [language, setLanguage] = useState<Language>('EN');

  const getCurrentUser = () => role === UserRole.ADMIN ? 'Admin User' : 'Kunawut W.';

  const handleEdit = (agent: Agent) => {
    setSelectedAgent(agent);
    setFormMode('EDIT');
    setCurrentView('FORM');
  };

  const handleView = (agent: Agent) => {
    setSelectedAgent(agent);
    setFormMode('VIEW');
    setCurrentView('FORM');
  };

  const handleCreate = () => {
    setSelectedAgent(undefined);
    setFormMode('CREATE');
    setCurrentView('FORM');
  };

  const handleSave = (savedAgent: Agent) => {
    setAgents(prev => {
      const exists = prev.find(a => a.id === savedAgent.id);
      if (exists) {
        return prev.map(a => a.id === savedAgent.id ? savedAgent : a);
      }
      // New agent
      const newAgentWithMeta = {
          ...savedAgent,
          createdAt: new Date().toISOString(),
          createdBy: getCurrentUser(),
          updatedBy: getCurrentUser()
      };
      return [...prev, newAgentWithMeta];
    });

    // Add Audit Log
    const action = selectedAgent ? 'UPDATE' : 'CREATE';
    const newLog: AuditLog = {
        id: `log-${Date.now()}`,
        action,
        user: getCurrentUser(),
        timestamp: new Date().toISOString(),
        details: `${action === 'CREATE' ? 'Created' : 'Updated'} agent "${savedAgent.name}". Status: ${savedAgent.status}`
    };
    setLogs(prev => [newLog, ...prev]);

    setCurrentView('LIST');
  };

  const handleDelete = (agent: Agent) => {
      Modal.confirm({
          title: TRANSLATIONS[language].confirmDelete,
          content: `Agent: ${agent.name}`,
          okType: 'danger',
          onOk() {
            setAgents(prev => prev.filter(a => a.id !== agent.id));
            const newLog: AuditLog = {
                id: `log-${Date.now()}`,
                action: 'DELETE',
                user: getCurrentUser(),
                timestamp: new Date().toISOString(),
                details: `Deleted agent "${agent.name}"`
            };
            setLogs(prev => [newLog, ...prev]);
          }
      });
  };

  const handleToggleStatus = (agent: Agent) => {
    if (role !== UserRole.ADMIN) return;

    const newStatus = agent.status === AgentStatus.ACTIVE ? AgentStatus.INACTIVE : AgentStatus.ACTIVE;
    // Check validation if trying to activate
    if (newStatus === AgentStatus.ACTIVE && !agent.workflowId) {
        Modal.error({
            title: 'Action Failed',
            content: 'Cannot activate agent without a bound Workflow.',
        });
        return;
    }

    const updatedAgent = { 
        ...agent, 
        status: newStatus, 
        updatedAt: new Date().toISOString(),
        updatedBy: getCurrentUser()
    };

    setAgents(prev => prev.map(a => a.id === updatedAgent.id ? updatedAgent : a));

    // Log
    const newLog: AuditLog = {
        id: `log-${Date.now()}`,
        action: newStatus === AgentStatus.ACTIVE ? 'ENABLE' : 'DISABLE',
        user: getCurrentUser(),
        timestamp: new Date().toISOString(),
        details: `Changed status to ${newStatus}`
    };
    setLogs(prev => [newLog, ...prev]);
  };

  const toggleRole = () => {
      setRole(prev => prev === UserRole.ADMIN ? UserRole.USER : UserRole.ADMIN);
  };

  return (
    <ConfigProvider
      theme={{
        token: {
          colorPrimary: '#0ea5e9', // Brand Blue
          fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
          borderRadius: 8,
        },
      }}
    >
      <Layout 
        currentUserRole={role} 
        onToggleRole={toggleRole} 
        language={language} 
        onLanguageChange={setLanguage}
      >
        {currentView === 'LIST' ? (
          <AgentList 
            agents={agents} 
            role={role}
            language={language}
            onEdit={handleEdit} 
            onView={handleView}
            onCreate={handleCreate} 
            onToggleStatus={handleToggleStatus}
            onDelete={handleDelete}
          />
        ) : (
          <AgentForm 
            initialData={selectedAgent} 
            role={role}
            language={language}
            onSave={handleSave} 
            onBack={() => setCurrentView('LIST')}
            auditLogs={selectedAgent ? logs.filter(l => l.details.includes(selectedAgent.name)) : []}
            readOnly={formMode === 'VIEW'}
          />
        )}
      </Layout>
    </ConfigProvider>
  );
}

export default App;

import React, { useState } from 'react';
import { 
    Button, Input, Select, Switch, Tabs, Card, Form, Alert, 
    Row, Col, Typography, Space, Divider, Tag, Tooltip, message 
} from 'antd';
import { 
  Agent, AgentStatus, AgentType, UserRole, Language,
  AVAILABLE_WORKFLOWS, AVAILABLE_TRIGGERS, ALLOWED_VARIABLES, AuditLog 
} from '../types';
import { TRANSLATIONS } from '../translations';

const { Title, Text, Paragraph } = Typography;
const { TextArea } = Input;
const { Option } = Select;

interface AgentFormProps {
  initialData?: Agent;
  role: UserRole;
  language: Language;
  onSave: (agent: Agent) => void;
  onBack: () => void;
  auditLogs: AuditLog[];
  readOnly?: boolean;
}

export const AgentForm: React.FC<AgentFormProps> = ({ initialData, role, language, onSave, onBack, auditLogs, readOnly = false }) => {
  const [testResult, setTestResult] = useState<any>(null);
  const [testLoading, setTestLoading] = useState(false);
  const t = TRANSLATIONS[language];

  // Form State Management (Keeping simplified custom state for specific nested logic)
  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, // Default
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    createdAt: new Date().toISOString(),
    createdBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: '',
      subjectTemplate: '',
      bodyTemplate: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
      targetFolderPath: '/Shared Drives/Company/',
      renamePattern: '{DocNo}_{Date}',
      folderStructure: '/{Year}/{Month}/'
    }
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [activeTabKey, setActiveTabKey] = useState('general');

  // Input States for Keywords (AntD Select mode="tags" handles this better, but adapting existing logic)
  const isAdmin = role === UserRole.ADMIN;
  const isFormReadOnly = readOnly || !isAdmin;

  // -- Handlers --

  const handleInputChange = (field: string, value: any) => {
    if (isFormReadOnly) return;
    setFormData(prev => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }));
  };

  const handleNestedChange = (section: 'mailConfig' | 'aiConfig' | 'driveConfig', field: string, value: any) => {
    if (isFormReadOnly) return;
    setFormData(prev => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value
      }
    }));
  };

  const handleCopyVariable = (variable: string) => {
    navigator.clipboard.writeText(variable);
    message.success(`${t.copiedToClipboard}: ${variable}`);
  };

  const validateForm = (checkStatus: AgentStatus) => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = t.errNameReq;
    if (formData.name.length > 120) newErrors.name = t.errNameLen;

    if (checkStatus === AgentStatus.ACTIVE) {
      if (!formData.workflowId) newErrors.workflowId = t.errWorkflowReq;
      if (!formData.triggerEvent) newErrors.triggerEvent = t.errTriggerReq;
    }

    if (formData.driveConfig?.autoSave && !formData.driveConfig.targetFolderPath) {
      newErrors.targetPath = t.errTargetPathReq;
    }

    if (formData.driveConfig?.autoRename && formData.driveConfig.renamePattern) {
        if (/[<>:"/\\|?*]/.test(formData.driveConfig.renamePattern)) {
            newErrors.renamePattern = t.errInvalidPattern;
        }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (targetStatus?: AgentStatus) => {
    if (isFormReadOnly) return;
    const statusToCheck = targetStatus || formData.status;

    if (!validateForm(statusToCheck)) {
        if (errors.workflowId || errors.triggerEvent) setActiveTabKey('general');
        else if (errors.targetPath || errors.renamePattern) setActiveTabKey('automation');
        return;
    }

    const updatedAgent = {
      ...formData,
      status: statusToCheck,
      updatedAt: new Date().toISOString()
    };
    onSave(updatedAgent);
  };

  const runTest = () => {
    setTestLoading(true);
    setTestResult(null);
    setTimeout(() => {
        setTestLoading(false);
        setTestResult({
            success: true,
            message: t.msgSuccess,
            details: {
                trigger: "Manual Test",
                input: formData.type === AgentType.MAIL ? "Sample Email Subject: Invoice #1234" : "Sample Context Data",
                actions: [
                    "Filter matched: Yes",
                    "Workflow Triggered: Invoice Processing",
                    formData.driveConfig?.autoSave ? `File Saved to: ${formData.driveConfig.targetFolderPath}` : "File Save: Skipped"
                ]
            }
        });
    }, 1500);
  };

  const getRenamingPreview = (pattern: string) => {
      if (!pattern) return '';
      const today = new Date();
      return pattern
        .replace(/{DocNo}/g, 'INV-2024-001')
        .replace(/{Date}/g, today.toISOString().split('T')[0])
        .replace(/{Customer}/g, 'Acme_Corp')
        .replace(/{AgentName}/g, (formData.name || 'MyAgent').replace(/\s+/g, '_'))
        .replace(/{Year}/g, today.getFullYear().toString())
        .replace(/{Month}/g, (today.getMonth() + 1).toString().padStart(2, '0'))
        .replace(/{DocType}/g, 'Invoice');
  };

  // --- Render Sections ---

  const renderGeneralTab = () => (
      <Row gutter={[24, 24]}>
          <Col span={24}>
              <Text strong>{t.labelAgentName} <span className="text-red-500">*</span></Text>
              <Input 
                 size="large" 
                 value={formData.name} 
                 onChange={e => handleInputChange('name', e.target.value)} 
                 status={errors.name ? 'error' : ''}
                 placeholder={t.phAgentName}
                 disabled={isFormReadOnly}
              />
              {errors.name && <Text type="danger" className="text-xs">{errors.name}</Text>}
          </Col>
          <Col span={12}>
              <Text strong>{t.labelAgentType} <span className="text-red-500">*</span></Text>
              <Select 
                 size="large" 
                 className="w-full block mt-1"
                 value={formData.type} 
