    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: '',
      subjectTemplate: '',
      bodyTemplate: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
    },
    driveConfig: {
      autoSave: false,
      autoRename: false,
      autoCreateFolder: false,
