  const t = TRANSLATIONS[language];

  const [formData, setFormData] = useState<Agent>(initialData || {
    id: `agent-${Date.now()}`,
    name: '',
    description: '',
    type: AgentType.MAIL, 
    status: AgentStatus.DRAFT,
    updatedAt: new Date().toISOString(),
    updatedBy: 'Current User',
    createdAt: new Date().toISOString(),
    createdBy: 'Current User',
    companyId: 'comp-001',
    workflowId: '',
    triggerEvent: '',
    startTime: '',
    endTime: '',
    mailConfig: {
      enableFilter: false,
      subjectKeywords: [],
      bodyKeywords: [],
      senderEmail: '',
      receiverEmail: '',
      subjectTemplate: '',
      bodyTemplate: ''
    },
    aiConfig: {
      model: 'gemini-pro',
      inputSource: '',
      outputAction: ''
