                      <div className="mb-2 text-sky-400">$ {t.logInit}</div>
                      <div className="mb-2 text-sky-400">$ {t.logLoadConfig} "{formData.name}"...</div>

                      {testLoading && (
                          <div className="animate-pulse text-slate-500 mt-4 space-y-1">
                              <div>&gt; {t.logProcess}</div>
                              <div>&gt; {t.logFilter}</div>
                              <div>&gt; {t.logDrive}</div>
