                                      <span className="text-purple-400">{key}: </span>
                                      <span className="text-slate-300">
                                          {Array.isArray(val) ? val.map(v => <div className="pl-4 text-xs text-slate-400 my-0.5" key={v}>- {v}</div>) : val}
                                      </span>
                                  </div>
                              ))}
                              <div className="text-slate-600">----------------------------------------</div>
                              <div className="text-xs text-slate-500 mt-4 bg-slate-800/50 p-2 rounded border border-slate-700">{t.msgSandbox}</div>
                          </div>
                      )}

                      {!testLoading && !testResult && (
                          <div className="mt-12 text-center text-slate-600 italic">
                              {t.msgReady}
                          </div>
                      )}
                   </div>
                </div>
