                         <div className="space-y-6 max-w-lg mx-auto">
                            {TEST_STEPS.map((step) => {
                                const isCompleted = testProgress > step.id;
                                const isCurrent = testProgress === step.id;
                                const isWaiting = testProgress < step.id;

                                return (
                                    <div key={step.id} className={`flex gap-4 p-4 rounded-xl transition-all duration-300 ${isCurrent ? 'bg-sky-50 border border-sky-100 shadow-sm transform scale-105' : 'border border-transparent'}`}>
                                        <div className="flex-shrink-0 pt-1">
                                            {isCompleted ? (
                                                <CheckCircle2 size={24} className="text-emerald-500" />
                                            ) : isCurrent ? (
                                                <Loader2 size={24} className="text-sky-500 animate-spin" />
                                            ) : (
                                                <Circle size={24} className="text-slate-300" />
                                            )}
                                        </div>
                                        <div>
                                            <h4 className={`font-semibold text-sm ${isWaiting ? 'text-slate-400' : 'text-slate-800'}`}>
                                                {step.label}
                                            </h4>
                                            <p className={`text-xs mt-0.5 ${isWaiting ? 'text-slate-300' : 'text-slate-500'}`}>
                                                {step.desc}
                                            </p>
                                        </div>
                                    </div>
                                )
                            })}
                         </div>
                      )}

                      {testStatus === 'COMPLETED' && testResult && (
                          <div className="mt-8 pt-6 border-t border-slate-100 animate-in fade-in slide-in-from-bottom-4 duration-500">
                              <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-6">
                                  <div className="flex items-start gap-3">
                                      <div className="p-2 bg-emerald-100 rounded-full text-emerald-600">
                                          <Check size={20} />
                                      </div>
                                      <div className="flex-1">
                                          <h4 className="font-bold text-emerald-800 text-lg mb-1">{testResult.message}</h4>
                                          <div className="text-sm text-emerald-700/80 mb-4">{t.msgSandbox}</div>

                                          <div className="bg-white/60 rounded-lg p-4 space-y-2 text-sm text-emerald-900 border border-emerald-100/50">
                                               {Object.entries(testResult.details).map(([key, val]: any) => (
                                                  <div key={key} className="flex flex-col sm:flex-row sm:gap-2">
                                                      <span className="font-semibold capitalize min-w-[80px]">{key}:</span>
                                                      <span className="text-emerald-800">
                                                          {Array.isArray(val) ? (
                                                              <ul className="list-disc list-inside pl-2 sm:pl-0">
                                                                  {val.map((v, idx) => <li key={idx}>{v}</li>)}
                                                              </ul>
                                                          ) : val}
                                                      </span>
                                                  </div>
                                               ))}
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      )}
                   </div>
                </div>
             </div>
          )}

          {/* HISTORY TAB */}
          {activeTab === 'history' && (
             <div className="max-w-4xl">
                <h3 className="text-lg font-bold text-slate-800 mb-4">{t.headerAudit}</h3>
                <div className="bg-white border border-slate-200 rounded-lg overflow-hidden shadow-sm">
                   <table className="w-full text-sm text-left">
                      <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-medium">
                         <tr>
                            <th className="px-6 py-4">{t.thTime}</th>
                            <th className="px-6 py-4">{t.thUser}</th>
                            <th className="px-6 py-4">{t.thAction}</th>
                            <th className="px-6 py-4">{t.thDetails}</th>
                         </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                         {auditLogs.map(log => (
                            <tr key={log.id} className="hover:bg-slate-50">
                               <td className="px-6 py-4 text-slate-500 whitespace-nowrap">{new Date(log.timestamp).toLocaleString()}</td>
                               <td className="px-6 py-4 font-medium text-slate-700">{log.user}</td>
                               <td className="px-6 py-4">
                                 <span className="bg-slate-100 text-slate-600 px-2 py-1 rounded text-xs font-bold">{log.action}</span>
                               </td>
                               <td className="px-6 py-4 text-slate-600">{log.details}</td>
                            </tr>
                         ))}
                         {auditLogs.length === 0 && (
                             <tr><td colSpan={4} className="p-12 text-center text-slate-400 italic">{t.noHistory}</td></tr>
                         )}
                      </tbody>
                   </table>
                </div>
             </div>
          )}

        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
