  onBack: () => void;
  onSave: () => void;
}

const TagInput = ({ value, onChange, placeholder }: any) => {
  const [input, setInput] = useState('');

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && input.trim()) {
      e.preventDefault();
      const trimmedInput = input.trim();
      if (!value.includes(trimmedInput)) {
        onChange([...value, trimmedInput]);
      }
      setInput('');
    }
  };

  const removeTag = (tagToRemove: string) => {
    onChange(value.filter((tag: string) => tag !== tagToRemove));
  };

  return (
    <div className="flex flex-wrap gap-2 p-2 border border-slate-800 rounded-sm bg-white min-h-[42px] focus-within:ring-1 focus-within:ring-slate-800">
      {value.map((tag: string) => (
        <span key={tag} className="bg-slate-200 text-slate-800 px-2 py-0.5 text-xs flex items-center gap-1 rounded-sm">
          {tag}
          <button onClick={() => removeTag(tag)} className="hover:text-red-600"><X size={12} /></button>
        </span>
      ))}
      <input 
        type="text" 
        value={input}
        onChange={e => setInput(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder={value.length === 0 ? placeholder : ''}
        className="flex-1 outline-none text-xs min-w-[120px] bg-transparent"
      />
    </div>
  );
};

