  const t = TRANSLATIONS[language];
  const [metadataTags, setMetadataTags] = useState<string[]>(['Invoice Number', 'Invoice Date', 'Due Date', 'Payment Status']);
  const [activeSheet, setActiveSheet] = useState('Sheet1');
  const [activeRow, setActiveRow] = useState<number>(3); // 1-based index for logic, corresponds to EXCEL_DATA[activeRow-1]
  const [mappingMode, setMappingMode] = useState<string | null>(null); // Holds the field ID currently being mapped

  const isExcel = item.fileName.endsWith('.xlsx') || item.fileName.endsWith('.xls');

  // State for fields to allow updates
  const [fields, setFields] = useState<FieldItem[]>([
     { id: 'invDate', label: t.fInvoiceDate, value: '01/03/2025', mappedColIndex: 1 }, // Column B
     { id: 'seller', label: t.fSellerName, value: 'Gamma Solutions', mappedColIndex: 2 }, // Column C
     { id: 'item', label: t.fItem, value: 'Widget C Deluxe', mappedColIndex: 6 }, // Column G
     { id: 'subtotal', label: t.fSubtotal, value: '1000', mappedColIndex: 12 }, // Column M
     { id: 'tax', label: t.fTax, value: '70', mappedColIndex: 13 }, // Column N
     { id: 'total', label: 'Grand Total', value: '1070', mappedColIndex: 14 }, // Column O
  ]);

  // Update field values when active row changes
  useEffect(() => {
      if (!isExcel) return;
      // Data index = activeRow - 1 (because Row 1 is header)
      // Actually in our mock EXCEL_DATA: Index 0 is Header, Index 1 is Row 2, Index 2 is Row 3...
      // So activeRow (e.g. 4) corresponds to EXCEL_DATA[activeRow - 2] if row 1 is data[0]
      // Let's simplify: EXCEL_DATA[0] is Header. EXCEL_DATA[1] is Row 2.
      // If Active Row is 4. Index is 4 - 1 = 3 -> EXCEL_DATA[3].

      const dataIndex = activeRow - 1;
      if (dataIndex >= 0 && dataIndex < EXCEL_DATA.length) {
          const rowData = EXCEL_DATA[dataIndex];
          setFields(prev => prev.map(field => ({
              ...field,
              value: field.mappedColIndex !== undefined ? rowData[field.mappedColIndex] || '' : field.value
          })));
      }
  }, [activeRow, isExcel]);

  const handleColumnClick = (colIndex: number) => {
      if (mappingMode) {
          // Update mapping
          setFields(prev => prev.map(f => {
              if (f.id === mappingMode) {
                  // Get value from current active row
                  const currentValue = EXCEL_DATA[activeRow - 1][colIndex];
                  return { ...f, mappedColIndex: colIndex, value: currentValue };
              }
              return f;
          }));
          setMappingMode(null);
      }
  };

  const getColumnBadge = (colIndex: number) => {
      const mappedField = fields.find(f => f.mappedColIndex === colIndex);
      if (mappedField) {
          return (
              <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-blue-600 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap z-30">
                  {mappedField.label}
              </div>
          );
      }
      return null;
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Top Header */}
