                  <div className="bg-[#dcdcdc] p-4 min-h-full">
                       <div className="bg-[#dcdcdc] rounded shadow-sm border border-[#ccc] min-h-[600px] p-2 text-sm">
                           <div className="px-2 py-1 text-xs text-slate-500 font-bold mb-2">XML</div>
                           <div className="overflow-x-auto">
                               {XML_CONTENT.split('\n').map((line, idx) => renderXmlLine(line, idx))}
