                                        <div className="absolute -top-5 left-0 bg-blue-600 text-white text-[10px] px-1.5 py-0.5 rounded shadow-sm whitespace-nowrap">
                                            {mappedField?.label}
                                        </div>
                                    )}
                                </div>
                             );
                          })}
                      </div>
                  </div>
              )}
           </div>
        </div>

        {/* Right Pane: Extraction Form */}
        <div className={`
             bg-slate-50 flex flex-col border-l border-slate-200 shadow-xl z-20 transition-all duration-300 ease-in-out relative
