                                                                onClick={() => setMappingMode(isMapping ? null : field.id)}
                                                                className={`
                                                                    flex items-center gap-1.5 text-[10px] px-2 py-1 rounded-full font-medium transition-colors border
                                                                    ${isMapping 
                                                                        ? 'bg-blue-600 text-white border-blue-600' 
