                                                                        >
                                                                            <Trash2 size={14} />
                                                                            {t.btnRemove}
                                                                        </button>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="flex gap-2">
                                                        <input 
                                                            type="text" 
                                                            value={field.value}
                                                            onChange={(e) => {
                                                                const newVal = e.target.value;
                                                                setFields(prev => prev.map(f => f.id === field.id ? { ...f, value: newVal } : f));
                                                            }}
                                                            className="w-full text-sm font-medium text-slate-900 border-b border-slate-200 pb-1 focus:outline-none focus:border-blue-500 bg-transparent"
                                                        />
                                                    </div>

                                                    {isMapped && (
                                                        <div className="mt-1.5 flex items-center gap-1 text-[10px] text-slate-400">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                                                            {t.sourcePrefix} <span className="font-mono text-slate-600">{sourceLabel}</span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}

                        {/* Add Field Button (Only for Excel/PDF) */}
                        {!isXml && (
                            <div className="mt-6 relative" ref={addDropdownRef}>
                                <button 
                                    onClick={() => setIsAddDropdownOpen(!isAddDropdownOpen)}
                                    className="w-full py-2 border-2 border-dashed border-slate-300 rounded-lg text-slate-500 text-sm font-medium hover:border-slate-400 hover:text-slate-600 hover:bg-slate-50 transition-colors flex items-center justify-center gap-2"
                                >
                                    <Plus size={16} /> {t.btnAddField}
                                </button>

                                {isAddDropdownOpen && (
                                    <div className="absolute left-0 right-0 bottom-full mb-2 bg-white rounded-lg shadow-xl border border-slate-200 max-h-60 overflow-y-auto z-50 animate-in slide-in-from-bottom-2">
                                        {availableFields.length > 0 ? (
                                            <div className="p-1">
                                                <div className="px-3 py-2 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.lblSelectField}</div>
                                                {availableFields.map(def => (
                                                    <button 
                                                        key={def.id}
                                                        onClick={() => addField(def)}
                                                        className="w-full text-left px-3 py-2 text-sm text-slate-700 hover:bg-slate-100 rounded-md transition-colors"
                                                    >
                                                        {def.label}
                                                    </button>
                                                ))}
                                            </div>
                                        ) : (
                                            <div className="p-4 text-center text-sm text-slate-400 italic">
                                                {t.noMoreFields}
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Custom Metadata for Excel/PDF/XML (at bottom) */}
                        <div className="mt-8 pt-6 border-t border-slate-200">
                            <h2 className="font-bold text-slate-800 mb-3 text-sm">{t.headerCustomMetadata}</h2>
                            <TagInput 
                                value={metadataTags}
                                onChange={setMetadataTags}
                                placeholder={t.phMetadataInput}
                            />
                            <div className="text-[10px] text-slate-400 mt-2 flex items-center gap-1">
                                <FileText size={10} />
                                {t.phMetadataInput}
                            </div>
                        </div>
                    </div>
                </div>

               <div className="p-4 bg-white border-t border-slate-200 shrink-0">
                   <button 
                      onClick={onSave}
                      className="w-full bg-[#1d4ed8] hover:bg-blue-700 text-white font-bold py-3 rounded-lg shadow-sm transition-all active:scale-[0.98] flex justify-center items-center gap-2"
                   >
                      <Check size={18} />
                      {t.btnConfirmVerify}
                   </button>
               </div>
           </div>
        </div>

      </div>
    </div>
  );
};

