                    <Calendar size={14} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                  </div>
              </div>
            </div>
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-slate-500">{t.sourceLabel}</label>
              <div className="relative">
                <select className="w-full px-3 py-2 border border-slate-200 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-sky-500/20 appearance-none bg-white text-slate-600">
                  <option>{t.phSource}</option>
                </select>
                <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
