                        </select>
                        <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                      </div>
                    </td>
                    <td className="px-4 py-3 text-slate-600">{item.ref}</td>
                    <td className="px-4 py-3">
                      {renderActionButtons(item)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="px-6 py-4 border-t border-slate-200 flex flex-wrap items-center gap-4 text-sm text-slate-500 shrink-0 bg-white">
            <span>{t.showing} {totalItems > 0 ? indexOfFirstItem + 1 : 0}-{Math.min(indexOfLastItem, totalItems)} {t.of} {totalItems} {t.items}</span>

            <div className="flex items-center gap-1">
              <button 
                  onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                  disabled={currentPage === 1}
                  className="w-8 h-8 flex items-center justify-center border border-slate-200 bg-white rounded hover:bg-slate-50 disabled:opacity-50"
              >
                  <ChevronLeft size={16} />
              </button>
              {/* Mock Pagination buttons */}
              <button className="w-8 h-8 flex items-center justify-center border border-sky-500 bg-white text-sky-600 rounded font-medium">1</button>
              <button className="w-8 h-8 flex items-center justify-center border border-slate-200 bg-white rounded hover:bg-slate-50">2</button>
              <span className="px-2">...</span>
              <button 
                  onClick={() => setCurrentPage(Math.min(Math.ceil(totalItems/itemsPerPage), currentPage + 1))}
                  disabled={currentPage >= Math.ceil(totalItems/itemsPerPage)}
                  className="w-8 h-8 flex items-center justify-center border border-slate-200 bg-white rounded hover:bg-slate-50 disabled:opacity-50"
              >
                  <ChevronRight size={16} />
              </button>
            </div>

            <select 
                value={itemsPerPage} 
                onChange={(e) => setItemsPerPage(Number(e.target.value))}
                className="border border-slate-200 rounded px-2 py-1 text-sm bg-white focus:outline-none"
            >
                <option value={10}>10 / {t.rowsPerPage.split(' ')[0]}</option>
                <option value={20}>20 / {t.rowsPerPage.split(' ')[0]}</option>
            </select>
          </div>
        </div>

      </div>
    </div>
  );
};

