const MOCK_LOGS: AuditLog[] = [
    { id: 'l1', action: 'CREATE', user: 'Admin User', timestamp: '2023-10-20T09:00:00Z', details: 'Created agent "Invoice Processor Alpha"' },
    { id: 'l2', action: 'ENABLE', user: 'Admin User', timestamp: '2023-10-25T10:30:00Z', details: 'Changed status from Draft to Active' },
];

function App() {
  // New State: Tracking View is default, EXTRACTION is new
  const [currentView, setCurrentView] = useState<'TRACKING' | 'AGENT_LIST' | 'AGENT_FORM' | 'EXTRACTION' | 'UPLOAD'>('TRACKING');
  const [formMode, setFormMode] = useState<'CREATE' | 'EDIT' | 'VIEW'>('CREATE');
  const [agents, setAgents] = useState<Agent[]>(MOCK_AGENTS);
  const [selectedAgent, setSelectedAgent] = useState<Agent | undefined>(undefined);

  // State for Tracking Items
  const [trackingItems, setTrackingItems] = useState<TrackingItem[]>(MOCK_TRACKING_DATA);
  // State for Extraction View
  const [extractionItem, setExtractionItem] = useState<TrackingItem | null>(null);

  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [logs, setLogs] = useState<AuditLog[]>(MOCK_LOGS);
  const [language, setLanguage] = useState<Language>('TH'); // Default to TH based on screenshot

  const getCurrentUser = () => role === UserRole.ADMIN ? 'Admin User' : 'Kunawut W.';

  const handleEdit = (agent: Agent) => {
    setSelectedAgent(agent);
    setFormMode('EDIT');
    setCurrentView('AGENT_FORM');
  };

  const handleView = (agent: Agent) => {
    setSelectedAgent(agent);
    setFormMode('VIEW');
    setCurrentView('AGENT_FORM');
  };

  const handleCreate = () => {
    setSelectedAgent(undefined);
    setFormMode('CREATE');
    setCurrentView('AGENT_FORM');
  };

  const handleSave = (savedAgent: Agent) => {
    setAgents(prev => {
      const exists = prev.find(a => a.id === savedAgent.id);
      if (exists) {
        return prev.map(a => a.id === savedAgent.id ? savedAgent : a);
      }
      // New agent
      const newAgentWithMeta = {
          ...savedAgent,
          createdAt: new Date().toISOString(),
          createdBy: getCurrentUser(),
          updatedBy: getCurrentUser()
      };
      return [...prev, newAgentWithMeta];
    });

    // Add Audit Log
    const action = selectedAgent ? 'UPDATE' : 'CREATE';
    const newLog: AuditLog = {
        id: `log-${Date.now()}`,
        action,
        user: getCurrentUser(),
        timestamp: new Date().toISOString(),
        details: `${action === 'CREATE' ? 'Created' : 'Updated'} agent "${savedAgent.name}". Status: ${savedAgent.status}`
    };
    setLogs(prev => [newLog, ...prev]);

    setCurrentView('AGENT_LIST');
  };

  const handleDelete = (agent: Agent) => {
      if (window.confirm(`${TRANSLATIONS[language].confirmDelete}\nAgent: ${agent.name}`)) {
        setAgents(prev => prev.filter(a => a.id !== agent.id));
        const newLog: AuditLog = {
            id: `log-${Date.now()}`,
            action: 'DELETE',
            user: getCurrentUser(),
            timestamp: new Date().toISOString(),
            details: `Deleted agent "${agent.name}"`
        };
        setLogs(prev => [newLog, ...prev]);
      }
  };

  const handleToggleStatus = (agent: Agent) => {
    if (role !== UserRole.ADMIN) return;

    const newStatus = agent.status === AgentStatus.ACTIVE ? AgentStatus.INACTIVE : AgentStatus.ACTIVE;
    // Check validation if trying to activate
    if (newStatus === AgentStatus.ACTIVE && !agent.workflowId) {
        window.alert(TRANSLATIONS[language].alertActivateFail || 'Cannot activate agent without a bound Workflow.');
        return;
    }

    const updatedAgent = { 
        ...agent, 
        status: newStatus, 
        updatedAt: new Date().toISOString(),
        updatedBy: getCurrentUser()
    };

    setAgents(prev => prev.map(a => a.id === updatedAgent.id ? updatedAgent : a));

    // Log
    const newLog: AuditLog = {
        id: `log-${Date.now()}`,
        action: newStatus === AgentStatus.ACTIVE ? 'ENABLE' : 'DISABLE',
        user: getCurrentUser(),
        timestamp: new Date().toISOString(),
        details: `Changed status to ${newStatus}`
    };
    setLogs(prev => [newLog, ...prev]);
  };

  const toggleRole = () => {
      setRole(prev => prev === UserRole.ADMIN ? UserRole.USER : UserRole.ADMIN);
  };

  const handleNavigate = (view: 'TRACKING' | 'AGENT_LIST' | 'UPLOAD') => {
      setCurrentView(view);
  };

  const handleViewExtraction = (item: TrackingItem) => {
      setExtractionItem(item);
      setCurrentView('EXTRACTION');
  };

  const handleUploadFiles = (files: File[]) => {
      // Mock converting Files to TrackingItems
      const newItems: TrackingItem[] = files.map((file, idx) => ({
          id: `up-${Date.now()}-${idx}`,
          fileName: file.name,
          date: new Date().toISOString().split('T')[0],
          performer: getCurrentUser(),
          source: TrackingSource.UPLOAD,
          reviewStatus: ReviewStatus.UNREAD,
          sendStatus: SendStatus.NOT_SENT,
          docType: 'Invoice',
          ref: '-'
      }));

      setTrackingItems(prev => [...newItems, ...prev]);
      setCurrentView('TRACKING');
  };

  return (
      <Layout 
        currentUserRole={role} 
        onToggleRole={toggleRole} 
        language={language} 
        onLanguageChange={setLanguage}
        onNavigate={handleNavigate}
      >
        {currentView === 'TRACKING' && (
           <TrackingPage 
              language={language} 
              items={trackingItems}
              onViewExtraction={handleViewExtraction}
              onUploadClick={() => setCurrentView('UPLOAD')}
           />
        )}

        {currentView === 'UPLOAD' && (
           <UploadPage 
              language={language}
              onUpload={handleUploadFiles}
           />
        )}

        {currentView === 'EXTRACTION' && extractionItem && (
            <ExtractionView 
               item={extractionItem}
               language={language}
               onBack={() => setCurrentView('TRACKING')}
               onSave={() => setCurrentView('TRACKING')}
            />
        )}

        {currentView === 'AGENT_LIST' && (
          <AgentList 
            agents={agents} 
            role={role}
            language={language}
            onEdit={handleEdit} 
            onView={handleView}
            onCreate={handleCreate} 
            onToggleStatus={handleToggleStatus}
            onDelete={handleDelete}
          />
        )}

        {currentView === 'AGENT_FORM' && (
          <AgentForm 
            initialData={selectedAgent} 
            role={role}
            language={language}
            onSave={handleSave} 
            onBack={() => setCurrentView('AGENT_LIST')}
            auditLogs={selectedAgent ? logs.filter(l => l.details.includes(selectedAgent.name)) : []}
            readOnly={formMode === 'VIEW'}
          />
        )}
      </Layout>
  );
}

export default App;

import React, { useState } from 'react';
import { 
  Search, Upload, Info, RefreshCw, Send, Trash2, 
  ChevronLeft, ChevronRight, Eye, FileText, ChevronDown, Calendar,
  ScanEye, RefreshCcw, FileScan, XCircle, RotateCcw, X
} from 'lucide-react';
import { Language, TrackingItem, TrackingSource, ReviewStatus, SendStatus } from '../types';
import { TRANSLATIONS } from '../translations';

interface TrackingPageProps {
  language: Language;
  items: TrackingItem[];
  onViewExtraction: (item: TrackingItem) => void;
  onUploadClick: () => void;
  onStartRead: (item: TrackingItem) => void;
}

// Simple Tooltip Component
interface TooltipProps {
  children: React.ReactNode;
  content: string;
}

const Tooltip: React.FC<TooltipProps> = ({ children, content }) => {
  const [isVisible, setIsVisible] = useState(false);

  return (
    <div 
      className="relative inline-block"
      onMouseEnter={() => setIsVisible(true)}
      onMouseLeave={() => setIsVisible(false)}
    >
      {children}
      {isVisible && (
        <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2 px-2 py-1 text-xs font-medium text-white bg-slate-800 rounded shadow-md whitespace-nowrap z-50">
          {content}
          <div className="absolute top-full left-1/2 transform -translate-x-1/2 border-4 border-transparent border-t-slate-800"></div>
        </div>
      )}
    </div>
  );
};

export const TrackingPage: React.FC<TrackingPageProps> = ({ language, items, onViewExtraction, onUploadClick, onStartRead }) => {
  const t = TRANSLATIONS[language];
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);

  // Read Config Modal State
  const [readModalOpen, setReadModalOpen] = useState(false);
  const [selectedItemForRead, setSelectedItemForRead] = useState<TrackingItem | null>(null);
  const [selectedDocType, setSelectedDocType] = useState('Invoice');
  const [selectedTemplate, setSelectedTemplate] = useState('General');

  const totalItems = items.length; // Use real length

  const getSourceBadge = (source: TrackingSource) => {
    switch (source) {
      case TrackingSource.UPLOAD:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-sky-100 text-sky-700">{t.sourceUpload}</span>;
      case TrackingSource.EMAIL:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-orange-100 text-orange-700">{t.sourceEmail}</span>;
      case TrackingSource.API:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-purple-100 text-purple-700">{t.sourceApi}</span>;
      default:
        return source;
    }
  };

  const getReviewBadge = (status: ReviewStatus) => {
    switch (status) {
      case ReviewStatus.REVIEWED:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-700">{t.statusReviewed}</span>;
      case ReviewStatus.UNREAD:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-slate-200 text-slate-600">{t.statusUnread}</span>;
      case ReviewStatus.READING:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-amber-100 text-amber-700 animate-pulse">{t.statusReading}</span>;
      case ReviewStatus.READ_FAILED:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-700">{t.statusReadFailed}</span>;
      case ReviewStatus.WAIT_FOR_REVIEW:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-sky-100 text-sky-700">{t.statusWaitForReview}</span>;
      case ReviewStatus.DRAFT:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-amber-100 text-amber-700">{t.statusDraft}</span>;
      default:
        return status;
    }
  };

  const getSendBadge = (status: SendStatus) => {
    switch (status) {
      case SendStatus.SENT:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-700">{t.statusSent}</span>;
      case SendStatus.SENDING:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-amber-100 text-amber-700">{t.statusSending}</span>;
      case SendStatus.FAILED:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-700">{t.statusSendFailed}</span>;
      case SendStatus.NOT_SENT:
      default:
        return <span className="px-2 py-0.5 rounded text-xs font-medium bg-gray-500 text-white">{t.statusNotSent}</span>;
    }
  };

  const openReadModal = (item: TrackingItem) => {
      setSelectedItemForRead(item);
      setSelectedDocType(item.docType || 'Invoice');
      setSelectedTemplate('General');
      setReadModalOpen(true);
  };

  const handleConfirmRead = () => {
      if (selectedItemForRead) {
          onStartRead(selectedItemForRead);
      }
      setReadModalOpen(false);
      setSelectedItemForRead(null);
  };

  const renderActionButtons = (item: TrackingItem) => {
    const { reviewStatus, sendStatus, source } = item;
    const isMail = source === TrackingSource.EMAIL;
    // const isUpload = source === TrackingSource.UPLOAD;

    // Logic Configuration
    const actions = {
        view: { show: true, disabled: false },
        reExtract: { show: false, disabled: false },
        readData: { show: false, disabled: false },
        review: { show: false, disabled: false },
        send: { show: true, disabled: true },
        reject: { show: false, disabled: false },
        delete: { show: true, disabled: false },
    };

    // Apply Logic Table
    switch(reviewStatus) {
        case ReviewStatus.UNREAD:
        case ReviewStatus.READ_FAILED:
            actions.readData.show = true;
            actions.send.show = false;
            actions.reject.show = isMail;
            break;
        case ReviewStatus.READING:
            actions.view.disabled = true;
            // Table implies Review is visible but disabled, or logic suggests just showing nothing except View/Delete
            // Using standard approach: Show review but disabled
            actions.review.show = true;
            actions.review.disabled = true;
            actions.readData.show = true; // Show icon but disabled
            actions.readData.disabled = true;
            actions.send.disabled = true;
            actions.reject.show = isMail;
            actions.reject.disabled = true;
            actions.delete.disabled = true;
            break;
        case ReviewStatus.WAIT_FOR_REVIEW:
        case ReviewStatus.DRAFT:
            actions.review.show = true;
            actions.send.disabled = true;
            actions.reject.show = isMail;
            break;
        case ReviewStatus.REVIEWED:
            actions.reExtract.show = true;
            actions.send.disabled = false;
            actions.reject.show = isMail;

            if (sendStatus === SendStatus.SENDING) {
                actions.send.disabled = true;
                actions.delete.disabled = true;
            } else if (sendStatus === SendStatus.SENT) {
                actions.send.disabled = true;
            }
            break;
    }

    return (
        <div className="flex items-center justify-end gap-3 text-slate-400">
             {/* View Document */}
            {actions.view.show && (
                <Tooltip content={t.ttView}>
                    <button 
                        className={`transition-colors ${actions.view.disabled ? 'opacity-30 cursor-not-allowed' : 'hover:text-slate-600'}`}
                        disabled={actions.view.disabled}
                    >
                        <Eye size={18} strokeWidth={2} />
                    </button>
                </Tooltip>
            )}

            {/* Re-extract (Reviewed Only) */}
            {actions.reExtract.show && (
                <Tooltip content={t.ttReExtract}>
                    <button 
                         className={`transition-colors ${actions.reExtract.disabled ? 'opacity-30 cursor-not-allowed' : 'hover:text-slate-600'}`}
                         disabled={actions.reExtract.disabled}
                    >
                        <RotateCcw size={18} strokeWidth={2} />
                    </button>
                </Tooltip>
            )}

            {/* Read Data (Unread/Failed/Reading) */}
            {actions.readData.show && (
                <Tooltip content={t.ttReadData}>
                    <button 
                         onClick={() => openReadModal(item)}
                         className={`transition-colors ${reviewStatus === ReviewStatus.READING ? 'text-blue-500 animate-pulse' : 'text-slate-500'} ${actions.readData.disabled ? 'opacity-50 cursor-not-allowed' : 'hover:text-blue-600'}`}
                         disabled={actions.readData.disabled}
                    >
                        <FileScan size={18} strokeWidth={2} />
                    </button>
                </Tooltip>
            )}

            {/* Review File (Wait/Draft) */}
            {actions.review.show && (
                <Tooltip content={t.ttReview}>
                    <button 
                        onClick={() => onViewExtraction(item)}
                        className={`transition-colors ${actions.review.disabled ? 'opacity-30 cursor-not-allowed text-slate-400' : 'text-blue-500 hover:text-blue-700'}`}
                        disabled={actions.review.disabled}
                    >
                        <ScanEye size={18} strokeWidth={2} />
                    </button>
                </Tooltip>
            )}

            {/* Send */}
            {actions.send.show && (
                <Tooltip content={t.ttSend}>
                    <button 
                        className={`transition-colors ${actions.send.disabled ? 'opacity-30 cursor-not-allowed' : 'hover:text-slate-600'}`}
                        disabled={actions.send.disabled}
                    >
                        <Send size={18} strokeWidth={2} />
                    </button>
                </Tooltip>
            )}

            {/* Reject (Mail Agent Only) */}
            {actions.reject.show && (
                 <Tooltip content={t.ttReject}>
                    <button 
                        className={`transition-colors ${actions.reject.disabled ? 'opacity-30 cursor-not-allowed' : 'hover:text-red-500'}`}
                        disabled={actions.reject.disabled}
