                    <button 
                        className={`transition-colors ${actions.delete.disabled ? 'opacity-30 cursor-not-allowed' : 'hover:text-red-500'}`}
                        disabled={actions.delete.disabled}
                    >
                        <Trash2 size={18} strokeWidth={2} />
                    </button>
                </Tooltip>
            )}
        </div>
    );
  };

  // Logic to slice items for pagination
