  // State for Change Field Dropdown
  const [changingFieldId, setChangingFieldId] = useState<string | null>(null);
  const changeDropdownRef = useRef<HTMLDivElement>(null);

  // Drag and Drop State
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const ext = item.fileName.split('.').pop()?.toLowerCase();
  const isExcel = ['xlsx', 'xls'].includes(ext || '');
  const isXml = ext === 'xml';
  const isImage = ['png', 'jpg', 'jpeg'].includes(ext || '');
  const isPdf = !isExcel && !isXml && !isImage;

  // Determine Image Format (Short vs Long) based on filename for demo purposes
  const isLongImage = isImage && (item.fileName.toLowerCase().includes('long') || item.fileName.toLowerCase().includes('receipt'));

  // Get current dataset definitions based on selection
  const currentDatasetDefs = DATASET_DEFINITIONS[selectedDataset] || DATASET_EDECLARATION;

  // State for fields (used for PDF/Excel) - Initial subset of DATASET_DEFS
  const [fields, setFields] = useState<FieldItem[]>([
     { id: 'invDate', label: 'Invoice Date', value: isImage ? '22/01/2026' : '01/03/2025', mappedColIndex: isExcel ? 1 : undefined, mappedRegionId: isPdf ? 'r-date' : (isImage ? 'img-date' : undefined) },
     { id: 'seller', label: 'Seller Name', value: isImage ? '7-Eleven' : 'Gamma Solutions', mappedColIndex: isExcel ? 2 : undefined, mappedRegionId: isPdf ? 'r-seller' : (isImage ? 'img-store' : undefined) },
     { id: 'item', label: 'Item', value: isImage ? 'Water 500ml' : 'Widget C Deluxe', mappedColIndex: isExcel ? 6 : undefined, mappedRegionId: isPdf ? 'r-item1' : (isImage ? 'img-item1' : undefined) },
     { id: 'subtotal', label: 'Subtotal', value: isImage ? '45.00' : '1000', mappedColIndex: isExcel ? 12 : undefined, mappedRegionId: isPdf ? 'r-sub' : (isImage ? 'img-total' : undefined) },
     { id: 'tax', label: 'Tax', value: isImage ? '3.15' : '70', mappedColIndex: isExcel ? 13 : undefined, mappedRegionId: isPdf ? 'r-tax' : (isImage ? 'img-tax' : undefined) },
     { id: 'total', label: 'Grand Total', value: isImage ? '45.00' : '1070', mappedColIndex: isExcel ? 14 : undefined, mappedRegionId: isPdf ? 'r-total' : (isImage ? 'img-total' : undefined) },
  ]);

  // Derived available fields (exclude already used fields)
  // Use currentDatasetDefs instead of static DATASET_DEFS
  const availableFields = currentDatasetDefs.filter(def => !fields.some(f => f.id === def.id));

  // Helper to get options when swapping a field (include current field + available ones)
  const getSwapOptions = (currentId: string) => {
      return currentDatasetDefs.filter(def => 
          def.id === currentId || !fields.some(f => f.id === def.id)
      );
  };

  // Determine current Excel Data based on Sheet
  const currentExcelData = activeSheet === 'Sheet1' ? SHEET1_DATA : SHEET2_DATA;

  // Determine Save Button Label
  const getSaveButtonLabel = () => {
     if (selectedWorkflow === 'จัดทำใบขน') return t.btnSendToEDecl;
     if (selectedWorkflow === 'จัดทำใบเพิ่มหนี้ ลดหนี้') return t.btnSendToAiBox;
     return t.btnConfirmVerify;
  };

  // Update field values when active row changes (Excel only)
  useEffect(() => {
      if (!isExcel) return;
      const dataIndex = activeRow - 1;
      if (dataIndex >= 0 && dataIndex < currentExcelData.length) {
          const rowData = currentExcelData[dataIndex];
          setFields(prev => prev.map(field => ({
              ...field,
              value: field.mappedColIndex !== undefined ? rowData[field.mappedColIndex] || '' : field.value
          })));
      }
  }, [activeRow, isExcel, activeSheet, currentExcelData]);

  // Close dropdwon on click outside
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (addDropdownRef.current && !addDropdownRef.current.contains(event.target as Node)) {
              setIsAddDropdownOpen(false);
          }
          if (changeDropdownRef.current && !changeDropdownRef.current.contains(event.target as Node)) {
              setChangingFieldId(null);
          }
          if (openMenuId && !(event.target as Element).closest('.card-menu-btn')) {
              setOpenMenuId(null);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [openMenuId, changingFieldId]);

  // Drag and Drop Handlers
  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    // Optional: Set custom drag image or effect
    e.dataTransfer.effectAllowed = 'move';
    // Firefox requires setting data
    e.dataTransfer.setData('text/plain', index.toString());
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault(); // Necessary to allow dropping
    if (draggedIndex === null || draggedIndex === index) return;

    // Real-time reordering
    const newFields = [...fields];
    const draggedItem = newFields[draggedIndex];
    newFields.splice(draggedIndex, 1);
    newFields.splice(index, 0, draggedItem);

    setFields(newFields);
    setDraggedIndex(index);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
  };

  const handleColumnClick = (colIndex: number) => {
      if (mappingMode && isExcel) {
          setFields(prev => prev.map(f => {
              if (f.id === mappingMode) {
                  const currentValue = currentExcelData[activeRow - 1][colIndex];
                  return { ...f, mappedColIndex: colIndex, mappedRegionId: undefined, value: currentValue };
              }
              return f;
          }));
          setMappingMode(null);
      }
  };

  const handleRegionClick = (regionId: string, regionValue: string) => {
      if (mappingMode && (isPdf || isImage)) {
          setFields(prev => prev.map(f => {
              if (f.id === mappingMode) {
                  return { ...f, mappedRegionId: regionId, mappedColIndex: undefined, value: regionValue };
              }
              return f;
          }));
          setMappingMode(null);
      }
  };

  const addField = (def: { id: string, label: string }) => {
      setFields(prev => [...prev, { id: def.id, label: def.label, value: '' }]);
      setIsAddDropdownOpen(false);
  };

  const swapFieldType = (currentId: string, newDef: { id: string, label: string }) => {
      setFields(prev => prev.map(f => {
          if (f.id === currentId) {
              return { ...f, id: newDef.id, label: newDef.label };
          }
          return f;
      }));
      setChangingFieldId(null);
  };

  const removeField = (id: string) => {
      setFields(prev => prev.filter(f => f.id !== id));
      setOpenMenuId(null);
  };

  const moveField = (index: number, direction: 'up' | 'down') => {
      if (direction === 'up' && index === 0) return;
      if (direction === 'down' && index === fields.length - 1) return;

      const newFields = [...fields];
      const targetIndex = direction === 'up' ? index - 1 : index + 1;
      [newFields[index], newFields[targetIndex]] = [newFields[targetIndex], newFields[index]];
      setFields(newFields);
      setOpenMenuId(null);
  };

  const getColumnBadge = (colIndex: number) => {
      const mappedField = fields.find(f => f.mappedColIndex === colIndex);
      if (mappedField) {
          return (
              <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-blue-600 text-white text-[10px] px-2 py-0.5 rounded shadow-sm whitespace-nowrap z-30">
                  {mappedField.label}
              </div>
          );
      }
      return null;
  };

  const renderXmlLine = (line: string, index: number) => {
    // Simple mock highlighting
    if (line.trim().startsWith('<!--')) {
        return <div key={index} className="text-slate-400 italic font-mono pl-4">{line}</div>;
    }
    // Tag highlighting regex approach (simplified)
    const parts = line.split(/(<[^>]+>)/g).filter(Boolean);
    return (
        <div key={index} className="font-mono pl-4 whitespace-pre text-slate-800">
            {parts.map((part, i) => {
                if (part.startsWith('<')) return <span key={i} className="text-blue-600">{part}</span>;
                return <span key={i}>{part}</span>;
            })}
        </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Top Header */}
      <div className="flex justify-between items-center px-6 py-4 border-b border-slate-200">
        <h1 className="text-xl font-bold text-slate-800">{t.verifyTitle}</h1>
        <div className="flex gap-2">
          <button 
            onClick={onBack}
            className="flex items-center gap-2 px-4 py-2 border border-slate-300 rounded-md text-slate-600 text-sm font-medium hover:bg-slate-50 transition-colors"
          >
            <ArrowLeft size={16} />
            {t.btnBack}
          </button>
          <button 
            onClick={onSave}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-300 rounded-md text-slate-700 text-sm font-medium hover:bg-slate-50 transition-colors shadow-sm"
          >
             <Save size={16} />
             {t.btnSaveDraft}
          </button>
        </div>
      </div>

      {/* Info Bar */}
      <div className="bg-slate-50 px-6 py-3 border-b border-slate-200 text-xs text-slate-600">
         <div className="grid grid-cols-2 md:grid-cols-6 gap-4">
            <div>
               <span className="block text-slate-400 mb-0.5">{t.lblFileName}</span>
               <span className="font-medium text-slate-800">{item.fileName}</span>
            </div>
            <div>
               <span className="block text-slate-400 mb-0.5">{t.lblDocType}</span>
               <span className="font-medium text-slate-800">{item.docType}</span>
            </div>
            <div>
               <span className="block text-slate-400 mb-0.5">{t.lblExtension}</span>
               <span className="font-medium text-slate-800 uppercase">{item.fileName.split('.').pop()}</span>
            </div>
            <div>
               <span className="block text-slate-400 mb-0.5">{t.lblTemplate}</span>
               <span className="font-medium text-slate-800">General</span>
            </div>

            {/* Dataset Dropdown */}
            <div>
               <span className="block text-slate-400 mb-0.5">{t.lblDataset}</span>
               <div className="relative">
                   <select 
                      value={selectedDataset}
                      onChange={(e) => setSelectedDataset(e.target.value)}
                      className="w-full font-medium text-slate-800 bg-transparent border-b border-slate-300 pb-0.5 focus:outline-none focus:border-blue-500 pr-4 truncate"
                   >
                      {Object.keys(DATASET_DEFINITIONS).map(ds => <option key={ds} value={ds}>{ds}</option>)}
                   </select>
                   <ChevronDown size={12} className="absolute right-0 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
               </div>
            </div>

            {/* Workflow Dropdown */}
            <div>
               <span className="block text-slate-400 mb-0.5">{t.lblWorkflow}</span>
               <div className="relative">
                   <select 
                      value={selectedWorkflow}
                      onChange={(e) => setSelectedWorkflow(e.target.value)}
                      className="w-full font-medium text-slate-800 bg-transparent border-b border-slate-300 pb-0.5 focus:outline-none focus:border-blue-500 pr-4 truncate"
                   >
                      {WORKFLOW_OPTIONS.map(wf => <option key={wf} value={wf}>{wf}</option>)}
                   </select>
                   <ChevronDown size={12} className="absolute right-0 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
               </div>
            </div>
         </div>
      </div>

      {/* Main Split View */}
      <div className="flex flex-1 overflow-hidden relative">

        {/* Left Pane: Content (Excel, PDF, or XML) */}
        <div className="flex-1 bg-slate-100 flex flex-col border-r border-slate-200 overflow-hidden relative">

           {/* Toolbar */}
           <div className="bg-white border-b border-slate-200 px-4 py-2 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-4">
                 <div className="flex items-center gap-2 text-sm text-slate-700">
                    <div className={`p-1.5 rounded ${isExcel ? 'bg-green-100 text-green-700' : (isXml ? 'bg-slate-100 text-slate-700' : (isImage ? 'bg-purple-100 text-purple-700' : 'bg-red-100 text-red-700'))}`}>
                        {isExcel ? <FileSpreadsheet size={18} /> : (isXml ? <FileCode size={18} /> : (isImage ? <ImageIcon size={18} /> : <FileText size={18} />))}
                    </div>
                    <span className="font-bold">{item.fileName}</span>
                 </div>

                 {isExcel && (
                    <>
                        <div className="h-4 w-px bg-slate-300"></div>
                        <div className="flex items-center gap-2 text-xs">
                            <span className="text-slate-500">Sheet:</span>
                            <select 
                                value={activeSheet}
                                onChange={(e) => setActiveSheet(e.target.value)}
                                className="bg-slate-50 border border-slate-200 rounded px-2 py-1 focus:outline-none focus:ring-1 focus:ring-blue-500"
                            >
                                <option value="Sheet1">Sheet1</option>
                                <option value="Sheet2">Sheet2</option>
                            </select>
                        </div>
                    </>
                 )}
                 {isPdf && (
                    <>
                        <div className="h-4 w-px bg-slate-300"></div>
                        <div className="flex items-center gap-2 text-xs">
                             <button 
                                onClick={() => setActivePdfPage(Math.max(1, activePdfPage - 1))}
                                disabled={activePdfPage === 1}
                                className="p-1 hover:bg-slate-100 rounded text-slate-500 disabled:opacity-30"
                             >
                                <ChevronLeft size={16} />
                             </button>
                             <span className="text-slate-500">Page {activePdfPage} of {TOTAL_PDF_PAGES}</span>
                             <button 
                                onClick={() => setActivePdfPage(Math.min(TOTAL_PDF_PAGES, activePdfPage + 1))}
                                disabled={activePdfPage === TOTAL_PDF_PAGES}
                                className="p-1 hover:bg-slate-100 rounded text-slate-500 disabled:opacity-30"
                             >
                                <ChevronRight size={16} />
                             </button>
                        </div>
                    </>
                 )}
                 {isXml && (
                     <div className="text-xs text-slate-400 italic ml-2">XML Viewer</div>
                 )}
                 {isImage && (
                     <div className="text-xs text-slate-400 italic ml-2">Image Viewer</div>
                 )}
              </div>

              {mappingMode && (
                  <div className="bg-blue-600 text-white px-3 py-1.5 rounded-full text-xs font-bold animate-pulse shadow-md flex items-center gap-2">
                      <MousePointerClick size={14} />
                      {isExcel ? t.selectColumnToMap : t.selectRegionToMap}
                  </div>
              )}

              <div className="flex items-center gap-2">
                 <button className="p-1.5 hover:bg-slate-100 rounded text-slate-500"><ZoomOut size={16} /></button>
                 <span className="text-xs text-slate-500 font-mono">100%</span>
                 <button className="p-1.5 hover:bg-slate-100 rounded text-slate-500"><ZoomIn size={16} /></button>
              </div>
           </div>

           {/* Content Area */}
           <div className={`flex-1 overflow-auto bg-slate-200 p-4 relative ${isXml ? 'bg-[#e5e7eb]' : ''}`}>
              {isExcel ? (
                  // EXCEL GRID
                  <div className="bg-white shadow-sm border border-slate-300 inline-block min-w-full">
                     <table className="text-xs border-collapse table-fixed w-max">
                         <thead>
                             <tr>
                                 <th className="w-10 bg-slate-50 border border-slate-300 sticky top-0 left-0 z-20"></th>
                                 {EXCEL_HEADERS.map((col, idx) => {
                                     const isMapped = fields.some(f => f.mappedColIndex === idx);
                                     const isMappingTarget = mappingMode && !isMapped;

                                     return (
                                         <th 
                                            key={idx} 
                                            onClick={() => handleColumnClick(idx)}
                                            className={`
                                                w-32 border border-slate-300 px-2 py-2 font-bold text-center sticky top-0 z-10 select-none
                                                ${isMappingTarget ? 'bg-blue-50 hover:bg-blue-100 cursor-pointer ring-2 ring-inset ring-blue-400' : 'bg-slate-50 text-slate-600'}
                                                ${isMapped ? 'bg-blue-50/50 border-b-blue-400' : ''}
                                            `}
                                         >
                                             <div className="relative">
                                                 {getColumnBadge(idx)}
                                                 <div className="mb-1">{col}</div>
                                                 <div className={`text-[10px] font-normal truncate px-1 py-0.5 rounded ${isMapped ? 'bg-blue-100 text-blue-700' : 'bg-slate-200 text-slate-500'}`}>
                                                     {currentExcelData[0][idx] || ''}
                                                 </div>
                                             </div>
                                         </th>
                                     );
                                 })}
                             </tr>
                         </thead>
                         <tbody>
                             {currentExcelData.slice(1).map((row, rIdx) => {
                                 const rowNumber = rIdx + 2; 
                                 const isActive = activeRow === rowNumber;
                                 return (
                                     <tr 
                                        key={rIdx} 
                                        onClick={() => setActiveRow(rowNumber)}
                                        className={`
                                            group hover:bg-slate-50 cursor-pointer
                                            ${isActive ? 'bg-yellow-50' : 'bg-white'}
                                        `}
                                     >
                                         <td className={`
                                            border border-slate-300 text-center font-bold text-slate-500 sticky left-0 z-10
                                            ${isActive ? 'bg-yellow-100 text-yellow-800 border-r-yellow-300' : 'bg-slate-50'}
                                         `}>
                                             {rowNumber}
                                         </td>
                                         {row.map((cell, cIdx) => {
                                             const isMapped = fields.some(f => f.mappedColIndex === cIdx);
                                             return (
                                                 <td 
                                                    key={cIdx} 
                                                    className={`
                                                        border border-slate-300 px-2 py-1.5 whitespace-nowrap overflow-hidden text-ellipsis max-w-[150px]
                                                        ${isActive && isMapped ? 'font-bold text-blue-900 bg-blue-50/30' : 'text-slate-700'}
                                                    `}
                                                 >
                                                     {cell}
                                                 </td>
                                             );
                                         })}
                                     </tr>
                                 );
                             })}
                         </tbody>
                     </table>
                  </div>
              ) : isXml ? (
                  // XML VIEWER
                  <div className="bg-[#dcdcdc] p-4 min-h-full">
                       <div className="bg-[#dcdcdc] rounded shadow-sm border border-[#ccc] min-h-[600px] p-2 text-sm">
                           <div className="px-2 py-1 text-xs text-slate-500 font-bold mb-2">XML</div>
                           <div className="overflow-x-auto">
                               {XML_CONTENT.split('\n').map((line, idx) => renderXmlLine(line, idx))}
                           </div>
                       </div>
                  </div>
              ) : isImage ? (
                  // IMAGE VIEWER
                  <div className="flex justify-center min-h-full p-4">
                      <div className="relative bg-white shadow-lg transition-all duration-300 flex flex-col items-center"
                          style={{
                              width: isLongImage ? '380px' : '595px',
                              height: isLongImage ? '1200px' : '842px',
                          }}
                      >
                          {/* Simulated Image Content */}
                          <div className="absolute inset-0 flex flex-col items-center justify-start pt-16 opacity-30 select-none pointer-events-none">
                               <ImageIcon size={64} className="text-slate-400 mb-4" />
                               <div className="text-slate-400 font-bold text-2xl uppercase tracking-widest border-2 border-slate-300 px-4 py-1 rounded">
                                  {isLongImage ? 'Thermal Receipt' : 'Scanned Document'}
                               </div>

                               {/* Abstract Lines */}
                               <div className="w-[80%] h-4 bg-slate-300 mt-12 mb-2 rounded"></div>
                               <div className="w-[60%] h-4 bg-slate-300 mb-8 rounded"></div>

                               <div className="w-[90%] space-y-3">
                                  {Array.from({ length: isLongImage ? 25 : 12 }).map((_, i) => (
                                     <div key={i} className="flex justify-between">
                                        <div className="h-3 bg-slate-200 rounded w-[40%]"></div>
                                        <div className="h-3 bg-slate-200 rounded w-[20%]"></div>
                                     </div>
                                  ))}
                               </div>
                          </div>

                          {/* Interactive Regions */}
                          {IMAGE_REGIONS.map((region) => {
                             const isMapped = fields.some(f => f.mappedRegionId === region.id);
                             const mappedField = fields.find(f => f.mappedRegionId === region.id);
                             const isActive = mappingMode;

                             return (
                                <div
                                   key={region.id}
                                   onClick={() => handleRegionClick(region.id, region.value)}
                                   className={`
                                       absolute transition-all duration-200 rounded
                                       ${isMapped ? 'bg-blue-500/20 border-2 border-blue-500' : ''}
                                       ${isActive && !isMapped ? 'hover:bg-blue-500/10 hover:border-2 hover:border-blue-400 cursor-pointer border border-transparent' : ''}
                                   `}
                                   style={{ 
                                       left: region.x, 
                                       top: region.y, 
                                       width: region.w, 
                                       height: region.h 
                                   }}
                                   title={region.value}
                                >
                                    {isMapped && (
                                        <div className="absolute -top-5 left-0 bg-blue-600 text-white text-[10px] px-1.5 py-0.5 rounded shadow-sm whitespace-nowrap z-10">
                                            {mappedField?.label}
                                        </div>
                                    )}
                                </div>
                             );
                          })}
                      </div>
                  </div>
              ) : (
                  // PDF VIEWER MOCK
                  <div className="flex justify-center min-h-full">
                      <div className="bg-white shadow-lg w-[595px] h-[842px] relative">
                          {activePdfPage === 1 ? (
                              /* Page 1 Content (Existing Invoice Layout) */
                              <div className="p-10">
                                  <div className="flex justify-between items-start mb-12">
                                      <div className="text-3xl font-bold text-slate-800 tracking-tight flex flex-col">
                                          <span>GAMMA</span>
                                          <span className="text-sm font-normal text-slate-500">SOLUTIONS</span>
                                      </div>
                                      <div className="text-right">
                                          <h2 className="text-4xl font-light text-slate-300 mb-2">INVOICE</h2>
                                          <div className="text-sm font-bold text-slate-700"># INV-2025-001</div>
                                          <div className="text-xs text-slate-500">Date: 01/03/2025</div>
                                      </div>
                                  </div>

                                  <div className="flex justify-between mb-16">
                                      <div>
                                          <h3 className="text-xs font-bold text-slate-400 uppercase mb-2">Bill To:</h3>
                                          <div className="text-sm font-bold text-slate-800">Acme Corp</div>
                                          <div className="text-xs text-slate-600">456 Industry Way</div>
                                          <div className="text-xs text-slate-600">Tech City, TC 90210</div>
                                      </div>
                                      <div className="text-right">
                                          <h3 className="text-xs font-bold text-slate-400 uppercase mb-2">Pay To:</h3>
                                          <div className="text-sm font-bold text-slate-800">Gamma Solutions</div>
                                          <div className="text-xs text-slate-600">123 Tech Park, Silicon Valley</div>
                                          <div className="text-xs text-slate-600">San Jose, CA 94000</div>
                                      </div>
                                  </div>

                                  {/* Items Table Mock */}
                                  <div className="mb-8">
                                      <div className="flex border-b-2 border-slate-800 pb-2 mb-4 text-xs font-bold text-slate-800 uppercase">
                                          <div className="w-[40%]">Item Description</div>
                                          <div className="w-[20%] text-right">Qty</div>
                                          <div className="w-[20%] text-right">Price</div>
                                          <div className="w-[20%] text-right">Total</div>
                                      </div>
                                      <div className="flex border-b border-slate-100 py-3 text-sm text-slate-600">
                                          <div className="w-[40%]">Widget C Deluxe</div>
                                          <div className="w-[20%] text-right">20</div>
                                          <div className="w-[20%] text-right">50.00</div>
                                          <div className="w-[20%] text-right">1,000.00</div>
                                      </div>
                                      <div className="flex border-b border-slate-100 py-3 text-sm text-slate-600">
                                          <div className="w-[40%]">Service Fee</div>
                                          <div className="w-[20%] text-right">1</div>
                                          <div className="w-[20%] text-right">0.00</div>
                                          <div className="w-[20%] text-right">0.00</div>
                                      </div>
                                  </div>

                                  {/* Totals */}
                                  <div className="flex justify-end mt-8">
                                      <div className="w-48 space-y-2">
                                          <div className="flex justify-between text-sm text-slate-600">
                                              <span>Subtotal:</span>
                                              <span>1,000.00</span>
                                          </div>
                                          <div className="flex justify-between text-sm text-slate-600">
                                              <span>Tax (7%):</span>
                                              <span>70.00</span>
                                          </div>
                                          <div className="flex justify-between text-base font-bold text-slate-800 border-t border-slate-200 pt-2 mt-2">
                                              <span>Total:</span>
                                              <span>1,070.00</span>
                                          </div>
                                      </div>
                                  </div>
                              </div>
                          ) : (
                              /* Page 2 Content (Mock Content) */
                              <div className="p-10">
                                  <div className="flex justify-between items-start mb-12">
                                      <div className="text-3xl font-bold text-slate-800 tracking-tight flex flex-col">
                                          <span>GAMMA</span>
                                          <span className="text-sm font-normal text-slate-500">SOLUTIONS</span>
                                      </div>
                                      <div className="text-right">
                                          <h2 className="text-xl font-light text-slate-300 mb-2">TERMS & CONDITIONS</h2>
                                      </div>
                                  </div>

                                  <div className="mb-8">
                                      <h3 className="text-lg font-bold text-slate-800 mb-4">Additional Notes</h3>
                                      <div className="p-4 bg-slate-50 border border-slate-100 rounded mb-6">
                                          <p className="text-sm text-slate-600 italic">"Thank you for your business!"</p>
                                      </div>

                                      <h3 className="text-lg font-bold text-slate-800 mb-4">Payment Terms</h3>
                                      <div className="text-xs text-slate-500 leading-relaxed space-y-4 text-justify">
                                          <p>
                                              1. <strong>Payment Due Date:</strong> Payment is due within 30 days of the invoice date unless otherwise specified in writing. Late payments may be subject to interest charges at the maximum rate permitted by law.
                                          </p>
                                          <p>
                                              2. <strong>Retention of Title:</strong> Goods remain the property of Gamma Solutions until paid for in full. The customer shall store the goods separately and clearly identifiable as belonging to Gamma Solutions until full payment is received.
                                          </p>
                                          <p>
                                              3. <strong>Warranty:</strong> We warrant that the goods will correspond with their specification at the time of delivery and will be free from defects in material and workmanship for a period of 12 months from the date of delivery.
                                          </p>
                                      </div>
                                  </div>

                                  <div className="mt-20 border-t border-slate-200 pt-8">
                                      <div className="w-64 border-b border-slate-800 pb-2"></div>
                                      <div className="text-xs text-slate-500 mt-1 uppercase tracking-wider">Authorized Signatory</div>
                                      <div className="text-sm font-bold text-slate-800">John Doe (Manager)</div>
                                  </div>
                              </div>
                          )}

                          {/* INTERACTIVE REGIONS OVERLAY */}
                          {PDF_REGIONS.filter(r => r.page === activePdfPage).map((region) => {
                             const isMapped = fields.some(f => f.mappedRegionId === region.id);
                             const mappedField = fields.find(f => f.mappedRegionId === region.id);
                             const isActive = mappingMode; // In PDF mode, any region can be clicked if mapping is active

                             return (
                                <div
                                   key={region.id}
                                   onClick={() => handleRegionClick(region.id, region.value)}
                                   className={`
                                       absolute transition-all duration-200 rounded
                                       ${isMapped ? 'bg-blue-500/20 border-2 border-blue-500' : ''}
                                       ${isActive && !isMapped ? 'hover:bg-blue-500/10 hover:border-2 hover:border-blue-400 cursor-pointer border border-transparent' : ''}
                                   `}
                                   style={{ 
                                       left: region.x, 
                                       top: region.y, 
                                       width: region.w, 
                                       height: region.h 
                                   }}
                                   title={region.value}
                                >
                                    {isMapped && (
                                        <div className="absolute -top-5 left-0 bg-blue-600 text-white text-[10px] px-1.5 py-0.5 rounded shadow-sm whitespace-nowrap z-10">
                                            {mappedField?.label}
                                        </div>
                                    )}
                                </div>
                             );
                          })}
                      </div>
                  </div>
              )}
           </div>
        </div>

        {/* Right Pane: Extraction Form */}
        <div className={`
             bg-slate-50 flex flex-col border-l border-slate-200 shadow-xl z-20 transition-all duration-300 ease-in-out relative
             ${isPanelOpen ? 'w-[400px]' : 'w-12 bg-white'}
        `}>

           {/* Toggle Button */}
           <div className="absolute -left-3 top-6 z-30">
                <button 
                    onClick={() => setIsPanelOpen(!isPanelOpen)}
                    className="bg-white border border-slate-200 rounded-full p-1 shadow-md hover:bg-slate-50 text-slate-500 transition-transform active:scale-95"
                    title={isPanelOpen ? t.tooltipHidePanel : t.tooltipShowPanel}
                >
                    {isPanelOpen ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
                </button>
           </div>

           {/* Collapsed State Vertical Text */}
           {!isPanelOpen && (
                <div 
                    className="flex-1 flex items-center justify-center cursor-pointer hover:bg-slate-50 transition-colors" 
                    onClick={() => setIsPanelOpen(true)}
                    title={t.tooltipShowPanel}
                >
                    <div className="rotate-180" style={{ writingMode: 'vertical-rl' }}>
                         <span className="font-bold text-slate-500 tracking-wider text-xs flex items-center gap-3 py-6 whitespace-nowrap">
                            <FileText size={16} /> {t.headerExtractedData}
                         </span>
                    </div>
                </div>
           )}

           <div className={`flex-1 flex flex-col overflow-hidden ${!isPanelOpen ? 'opacity-0 invisible hidden' : 'opacity-100 visible'} transition-all duration-200`}>
                <div className="flex-1 overflow-y-auto">
                    <div className="p-6">

                        {!isXml && (
                            <div className="mb-6">
                                <h2 className="font-bold text-slate-800 text-lg flex items-center gap-2">
                                    {t.headerExtractedData}
                                </h2>
                                <p className="text-xs text-slate-500 mt-1">
                                    {isExcel 
                                      ? <span>{t.reviewingDataRow} <span className="font-bold text-slate-800">{activeRow}</span></span>
                                      : <span>{t.reviewingDataPage} <span className="font-bold text-slate-800">{activePdfPage}</span></span>
                                    }
                                </p>
                            </div>
                        )}

                        {/* Read-Only Fields for XML (Always at top for XML) */}
                        {isXml && (
                            <div className="mb-6">
                                <h2 className="font-bold text-slate-800 mb-3 text-sm">{t.headerXmlMetadata}</h2>
                                <div className="border border-slate-300 rounded-lg overflow-hidden">
                                     {XML_READONLY_FIELDS.map((field, index) => (
                                         <div key={field.id} className={`flex items-center text-sm ${index !== XML_READONLY_FIELDS.length -1 ? 'border-b border-slate-200' : ''}`}>
                                             <div className="w-1/3 bg-slate-100 p-3 text-slate-600 font-medium text-xs truncate" title={field.label}>
                                                 {field.label}:
                                             </div>
                                             <div className="w-2/3 p-3 bg-slate-200/50 text-slate-800 font-mono text-xs">
                                                 {field.value}
                                             </div>
                                         </div>
                                     ))}
                                </div>
                            </div>
                        )}

                        {/* Interactive Fields for Excel/PDF */}
                        {!isXml && (
                            <div className="space-y-4">
                                {fields.map((field, index) => {
                                    const isMapping = mappingMode === field.id;
                                    const isDragging = draggedIndex === index;
                                    const isChanging = changingFieldId === field.id;

                                    // Determine Source Label
                                    let sourceLabel = 'Not Mapped';
                                    let isMapped = false;

                                    if (isExcel && field.mappedColIndex !== undefined) {
                                        isMapped = true;
                                        const colName = EXCEL_HEADERS[field.mappedColIndex];
                                        const headerName = currentExcelData[0][field.mappedColIndex];
                                        sourceLabel = `${t.lblCol} ${colName} (${headerName})`;
                                    } else if (!isExcel && field.mappedRegionId) {
                                        isMapped = true;
                                        sourceLabel = isImage ? 'Image Region' : 'PDF Region';
                                    }

                                    const swapOptions = getSwapOptions(field.id);

                                    return (
                                        <div 
                                            key={field.id} 
                                            draggable
                                            onDragStart={(e) => handleDragStart(e, index)}
                                            onDragOver={(e) => handleDragOver(e, index)}
                                            onDragEnd={handleDragEnd}
                                            className={`
                                                bg-white border rounded-lg p-3 transition-all duration-200 relative group
                                                ${isDragging ? 'opacity-50 ring-2 ring-blue-400 bg-blue-50' : 'opacity-100'}
                                                ${isMapping ? 'border-blue-500 ring-4 ring-blue-500/10 shadow-md' : 'border-slate-200 hover:border-slate-300'}
                                            `}
                                        >
                                            <div className="flex items-start gap-2">
                                                {/* Drag Handle */}
                                                <div className="mt-1 text-slate-300 hover:text-slate-500 cursor-grab active:cursor-grabbing p-0.5 -ml-1">
                                                    <GripVertical size={16} />
                                                </div>

                                                <div className="flex-1">
                                                    <div className="flex justify-between items-start mb-2 relative">

                                                        <div className="relative">
                                                             <button 
                                                                onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    setChangingFieldId(isChanging ? null : field.id);
                                                                    setOpenMenuId(null);
                                                                }}
                                                                className="flex items-center gap-1 text-xs font-bold text-slate-500 uppercase tracking-wider hover:text-blue-600 hover:bg-blue-50 px-1.5 py-0.5 rounded transition-colors group/label"
                                                             >
                                                                 {field.label}
                                                                 <ChevronDown size={12} className="opacity-0 group-hover/label:opacity-100 transition-opacity" />
                                                             </button>

                                                             {isChanging && (
                                                                <div 
                                                                    ref={changeDropdownRef}
                                                                    className="absolute left-0 top-full mt-1 w-60 bg-white rounded-lg shadow-xl border border-slate-200 max-h-60 overflow-y-auto z-50 animate-in fade-in zoom-in-95 duration-100"
                                                                >
                                                                    <div className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-wider sticky top-0 bg-white border-b border-slate-50">
                                                                        Switch Field To...
                                                                    </div>
                                                                    {swapOptions.map(def => (
                                                                        <button 
                                                                            key={def.id}
                                                                            onClick={() => swapFieldType(field.id, def)}
                                                                            className={`w-full text-left px-3 py-2 text-xs hover:bg-slate-50 transition-colors flex items-center justify-between
                                                                                ${def.id === field.id ? 'bg-blue-50 text-blue-700 font-bold' : 'text-slate-700'}
                                                                            `}
                                                                        >
                                                                            {def.label}
                                                                            {def.id === field.id && <Check size={12} />}
                                                                        </button>
                                                                    ))}
                                                                </div>
                                                             )}
                                                        </div>

                                                        <div className="flex items-center gap-2">
                                                            <button 
                                                                onClick={() => setMappingMode(isMapping ? null : field.id)}
                                                                className={`
                                                                    flex items-center gap-1.5 text-[10px] px-2 py-1 rounded-full font-medium transition-colors border
                                                                    ${isMapping 
                                                                        ? 'bg-blue-600 text-white border-blue-600' 
                                                                        : isMapped
                                                                            ? 'bg-slate-100 text-slate-600 border-slate-200 hover:bg-slate-200'
                                                                            : 'bg-slate-100 text-slate-400 border-slate-200 hover:text-slate-600'
                                                                    }
                                                                `}
                                                            >
                                                                {isMapping ? (
                                                                    <>{t.msgClickColumn} <MousePointerClick size={10} /></>
                                                                ) : (
                                                                    <>
                                                                        <LinkIcon size={10} /> 
                                                                        {isMapped ? `${t.lblCol} ${sourceLabel.replace(`${t.lblCol} `, '')}` : t.btnMapColumn}
                                                                    </>
                                                                )}
                                                            </button>

                                                            {/* Card Menu */}
                                                            <div className="relative">
                                                                <button 
                                                                    onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === field.id ? null : field.id); }}
                                                                    className="p-1 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded card-menu-btn"
                                                                >
                                                                    <MoreVertical size={14} />
                                                                </button>

                                                                {openMenuId === field.id && (
                                                                    <div className="absolute right-0 top-full mt-1 w-40 bg-white rounded-lg shadow-lg border border-slate-100 z-50 py-1 animate-in fade-in zoom-in-95 duration-100">
                                                                        <button 
                                                                            onClick={() => {
                                                                                setMappingMode(field.id);
                                                                                setOpenMenuId(null);
                                                                            }}
                                                                            className="w-full text-left px-3 py-2 text-xs text-slate-600 hover:bg-slate-50 flex items-center gap-2"
                                                                        >
                                                                            <LinkIcon size={14} className="text-slate-400" />
                                                                            {t.btnMapColumn}
                                                                        </button>

                                                                        <button 
                                                                            onClick={() => moveField(index, 'up')}
                                                                            disabled={index === 0}
                                                                            className="w-full text-left px-3 py-2 text-xs text-slate-600 hover:bg-slate-50 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                                                        >
                                                                            <ArrowUp size={14} className="text-slate-400" />
                                                                            {t.btnMoveUp}
                                                                        </button>

                                                                        <button 
                                                                            onClick={() => moveField(index, 'down')}
                                                                            disabled={index === fields.length - 1}
                                                                            className="w-full text-left px-3 py-2 text-xs text-slate-600 hover:bg-slate-50 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                                                        >
                                                                            <ArrowDown size={14} className="text-slate-400" />
                                                                            {t.btnMoveDown}
                                                                        </button>

                                                                        <div className="border-t border-slate-100 my-1"></div>

                                                                        <button 
                                                                            onClick={() => removeField(field.id)}
                                                                            className="w-full text-left px-3 py-2 text-xs text-red-600 hover:bg-red-50 flex items-center gap-2"
                                                                        >
                                                                            <Trash2 size={14} />
                                                                            {t.btnRemove}
                                                                        </button>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="flex gap-2">
                                                        <input 
                                                            type="text" 
                                                            value={field.value}
                                                            onChange={(e) => {
                                                                const newVal = e.target.value;
                                                                setFields(prev => prev.map(f => f.id === field.id ? { ...f, value: newVal } : f));
                                                            }}
                                                            className="w-full text-sm font-medium text-slate-900 border-b border-slate-200 pb-1 focus:outline-none focus:border-blue-500 bg-transparent"
                                                        />
                                                    </div>

                                                    {isMapped && (
                                                        <div className="mt-1.5 flex items-center gap-1 text-[10px] text-slate-400">
                                                            <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                                                            {t.sourcePrefix} <span className="font-mono text-slate-600">{sourceLabel}</span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}

                        {/* Custom Metadata for Excel/PDF/XML (at bottom) */}
                        <div className="mt-8 pt-6 border-t border-slate-200">
                            <h2 className="font-bold text-slate-800 mb-3 text-sm">{t.headerCustomMetadata}</h2>
                            <TagInput 
                                value={metadataTags}
                                onChange={setMetadataTags}
                                placeholder={t.phMetadataInput}
                            />
                            <div className="text-[10px] text-slate-400 mt-2 flex items-center gap-1">
                                <FileText size={10} />
                                {t.phMetadataInput}
                            </div>
                        </div>
                    </div>
                </div>

               <div className="p-4 bg-white border-t border-slate-200 shrink-0">
                   <button 
                      onClick={onSave}
                      className="w-full bg-[#1d4ed8] hover:bg-blue-700 text-white font-bold py-3 rounded-lg shadow-sm transition-all active:scale-[0.98] flex justify-center items-center gap-2"
                   >
                      <Check size={18} />
                      {getSaveButtonLabel()}
                   </button>
               </div>
           </div>
        </div>

      </div>
    </div>
  );
};
